import type { TopicId } from "./topics";

// Three kinds, like the professor's quiz. o + a (number): one answer; o: ["Verdadero", "Falso"] keeps its order.
// o + a (number[]): "selecciona una o más", right only with exactly those ticked. s: short answer typed in; any of
// the strings in s is accepted, and one with «;» has several elements that must come in that order.
// src: where it comes from (shown next to why). prof: from the professor's quiz or exercises.
export interface Question {
  t: TopicId;
  q: string;
  o?: string[];
  a?: number | number[];
  s?: string[];
  why: string;
  src?: string;
  prof?: true;
}

export type Answer = number | number[] | string;

/** How short answers are compared: lowercase, no accents, single spaces. */
export const normalize = (s: string) => s.normalize("NFD").replace(/\p{M}/gu, "").toLowerCase().replace(/\s+/g, " ").trim();

const parts = (s: string) => s.split(";").map(normalize).filter(Boolean).join(";");

export function isCorrect(q: Question, ans: Answer | undefined): boolean {
  if (q.s) return typeof ans === "string" && q.s.some((ok) => parts(ok) === parts(ans));
  if (Array.isArray(q.a)) return Array.isArray(ans) && ans.length === q.a.length && q.a.every((k) => ans.includes(k));
  return ans === q.a;
}

/**
 * Points with negative marking, as assumed for the exam: right 1, blank 0, wrong −1/(k−1) with k options, so guessing
 * averages 0 (−1/3 with four, −1 in true or false). One or more right answers: Moodle's partial credit, +1/c per right
 * option ticked and −1/(k−c) per wrong one, kept between 0 and 1. Short answers: 1 or 0.
 */
export function points(q: Question, ans: Answer | undefined): number {
  const a = q.a;
  const k = q.o?.length ?? 0;
  if (q.s || ans === undefined) return isCorrect(q, ans) ? 1 : 0;
  if (!Array.isArray(a)) return ans === a ? 1 : -1 / (k - 1);
  if (!Array.isArray(ans)) return 0;
  const sum = ans.reduce((s, x) => s + (a.includes(x) ? 1 / a.length : -1 / (k - a.length)), 0);
  return Math.min(1, Math.max(0, sum));
}

export const shuffle = <T,>(list: T[]) => {
  const a = [...list];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
};

/**
 * A draw like the real exam: n test questions (no short answers) from these topics, each topic with its share of the
 * weights (by default, of the bank). Systematic sampling, so each topic gets the floor or the ceiling of its share; within
 * a topic, the least seen first, so one exam repeats as little as possible of the last. Indices into QUESTIONS.
 */
export function examDraw(n: number, topics: readonly string[], seen: (i: number) => number, weight?: (t: string) => number): number[] {
  const blocks = topics.map((t) => shuffle(QUESTIONS.flatMap((q, i) => (q.t === t && !q.s ? [i] : []))).sort((x, y) => seen(x) - seen(y)));
  const w = topics.map((t, j) => (weight ? weight(t) : blocks[j].length));
  const step = w.reduce((s, x) => s + x, 0) / n;
  const r = Math.random() * step;
  let k = 0;
  let end = 0;
  return blocks.flatMap((b, j) => {
    const from = k;
    end += w[j];
    while (k < n && r + k * step < end) k++;
    return b.slice(0, k - from);
  });
}

/** A short stable id from the statement (FNV-1a), so the stats survive adding or reordering questions. */
export const qid = (q: Question) => {
  let h = 2166136261;
  for (let i = 0; i < q.q.length; i++) h = Math.imul(h ^ q.q.charCodeAt(i), 16777619);
  return (h >>> 0).toString(36);
};

// The exam bank, with the reason for each answer.
export const QUESTIONS: Question[] = [
  // ---------- 01 virtualizar e hipervisor
  { t: "virtualizar", q: "¿Qué es virtualizar?", o: ["Ejecutar varios procesos a la vez", "Ofrecer recursos hardware ficticios sobre los que el software preexistente funciona sin modificarse", "Comprimir la memoria de un sistema", "Traducir un programa a otro lenguaje"], a: 1, why: "Es la definición del tema 1: hardware ficticio (implementado en software o hardware) y software sin modificar." },
  { t: "virtualizar", q: "Formalmente, la virtualización construye…", o: ["Un isomorfismo entre el sistema real (host) y el virtual (guest)", "Una tabla de páginas invertida", "Un árbol de procesos", "Un protocolo de red"], a: 0, why: "Cada estado y transición del real tiene su equivalente en el virtual." },
  { t: "virtualizar", q: "¿Qué diferencia puede percibir el software entre ejecutarse en una MV o en una máquina real?", o: ["El juego de instrucciones", "El tamaño de la memoria", "Solo temporizaciones atípicas: retardos de E/S y pausas sin razón aparente", "Ninguna, ni siquiera de tiempos"], a: 2, why: "La equivalencia de Popek y Goldberg admite una única excepción: las temporizaciones." },
  { t: "virtualizar", q: "¿Cuál NO es una motivación de la virtualización según el tema?", o: ["Consolidación de servidores", "Ejecutar software obsoleto", "Aumentar la frecuencia del procesador", "Green computing"], a: 2, why: "Las motivaciones son emulación, legacy, experimentación, aislamiento, consolidación, failover, balanceo y green computing." },
  { t: "virtualizar", q: "Separar servicios en servidores virtuales distintos para que el fallo de uno no afecte a otros es…", o: ["Balanceo de carga", "Aislamiento (seguridad y fiabilidad)", "Paravirtualización", "Consolidación"], a: 1, why: "Fuerte aislamiento entre guests." },
  { t: "virtualizar", q: "Mover una MV a otro servidor físico antes de un mantenimiento se relaciona con…", o: ["Infraestructuras a prueba de fallos (migración)", "Emulación", "Software obsoleto", "What-if"], a: 0, why: "Failover: migración entre soportes físicos y clonación." },
  { t: "virtualizar", q: "El sistema operativo instalado dentro de la máquina virtual se llama…", o: ["Host", "Hipervisor", "Guest", "Dom0"], a: 2, why: "Guest = el de dentro; host = el instalado en el hardware físico." },
  { t: "virtualizar", q: "El conjunto de recursos virtualizados (CPU, RAM, disco, red…) es…", o: ["La máquina virtual", "El host", "El dispatcher", "El VMCB"], a: 0, why: "La MV es el hardware virtual sobre el que se instala el guest." },
  { t: "virtualizar", q: "¿Qué módulo del hipervisor decide a qué módulo llamar tras un trap?", o: ["Allocator", "Intérprete", "Dispatcher", "Scheduler"], a: 2, why: "El dispatcher es el punto de entrada tras la interrupción." },
  { t: "virtualizar", q: "El módulo que asigna recursos físicos reales a las MVs es…", o: ["El allocator", "El dispatcher", "El intérprete", "El balloon driver"], a: 0, why: "Allocator = asignación de recursos." },
  { t: "virtualizar", q: "El intérprete del hipervisor…", o: ["Traduce el SO guest a otro lenguaje", "Simula el efecto de las instrucciones que le manda el dispatcher", "Gestiona la red", "Programa la TLB"], a: 1, why: "Simula las instrucciones delicadas." },
  { t: "virtualizar", q: "Comparado con un SO, el hipervisor ofrece el disco como…", o: ["Ficheros", "Sockets", "Un disco virtual", "Procesos"], a: 2, why: "El hipervisor ofrece recursos hardware virtuales; el SO, servicios de alto nivel (ficheros)." },
  { t: "virtualizar", q: "Los clientes del hipervisor son…", o: ["Procesos", "Máquinas virtuales", "Hilos", "Sockets"], a: 1, why: "Los del kernel son procesos; los del hipervisor, MVs que ejecutan sistemas operativos." },
  { t: "virtualizar", q: "¿Qué garantiza el aislamiento (isolation)?", o: ["Que una MV no puede acceder a recursos que no se le han asignado", "Que las MVs no comparten CPU", "Que el guest sabe que está virtualizado", "Que no hay red entre MVs"], a: 0, why: "Es una de las funciones del hipervisor." },
  // del profesor: cuestionario
  { t: "virtualizar", q: "Formalmente la virtualización implica la construcción de una correspondencia v:R→V, entre dos máquinas, la real (R) y la virtual (V). Dicha correspondencia es:", o: ["Un isomorfismo", "Un polimorfismo", "Un monomorfismo", "Un automorfismo"], a: 0, why: "Cada estado y cada transición de la máquina real tienen su equivalente en la virtual: la virtualización construye un isomorfismo entre host y guest.", src: "Cuestionario, pregunta 5 · T1 diap. 5", prof: true },
  { t: "virtualizar", q: "¿Cuál de las siguientes no es una de las funcionalidades clave de las que normalmente se atribuyen a un hipervisor?", o: ["Controlar los privilegios de usuario en las máquinas virtuales", "Despachar (dispatch) las máquinas virtuales entre los cores de la CPU", "Interpretar adecuadamente las instrucciones críticas y privilegiadas", "Asignar recursos hardware a la máquina virtual"], a: 0, why: "Los privilegios de usuario dentro de cada MV los controla su SO guest, no el hipervisor. Las otras tres sí son del hipervisor: despachar (dispatcher), interpretar (intérprete) y asignar recursos (allocator).", src: "Cuestionario, pregunta 17", prof: true },
  { t: "virtualizar", q: "El sistema operativo que corre sobre una máquina virtual es:", o: ["El sistema operativo invitado (guest)", "El monitor de máquina virtual (VMM)", "El monitor de sistema", "El sistema operativo anfitrión (host)"], a: 0, why: "El SO de dentro de la MV es el guest (invitado). El host (anfitrión) es el instalado en el hardware físico y el VMM es el hipervisor.", src: "Cuestionario, pregunta 19", prof: true },
  { t: "virtualizar", q: "¿Qué término hace referencia a la característica de aislamiento (isolation) de un sistema virtual?", o: ["Virtualbox", "Honeybox", "Honeypot", "Sandbox"], a: 3, why: "Sandbox (caja de arena): un entorno aislado donde lo que pasa dentro no afecta al exterior; las MVs se usan así para prototipos y pruebas. Un honeypot es un señuelo para atraer atacantes y VirtualBox es un hipervisor.", src: "Cuestionario, pregunta 28 · T1 diap. 7", prof: true },
  { t: "virtualizar", q: "Por VMM (Virtual Machine Monitor) se entiende:", o: ["El sistema operativo host", "El sistema operativo guest", "El hipervisor", "El módulo de traducción binaria"], a: 2, why: "VMM (Virtual Machine Monitor) es otro nombre del hipervisor.", src: "Cuestionario, pregunta 29", prof: true },
  // nuevas
  { t: "virtualizar", q: "Según la definición del tema, los recursos hardware ficticios de una MV pueden implementarse tanto por software como por hardware.", o: ["Verdadero", "Falso"], a: 0, why: "La diap. 5 habla de «implementaciones software o hardware», y la diap. 11 dice que el hipervisor es una capa software «aunque puede estar asistida por el hardware». Decir «solo software» confunde el hipervisor típico con la definición.", src: "T1 diap. 5" },
  { t: "virtualizar", q: "En el diagrama del isomorfismo (diap. 5), una operación e lleva el sistema real del estado S₁ al S₂. ¿Qué exige el isomorfismo en el sistema virtual?", o: ["Que S'₁ y S'₂ sean copias idénticas, bit a bit, de S₁ y S₂", "Que e' se ejecute directamente en la CPU real, sin intervención del hipervisor", "Que exista una operación e' que lleve de S'₁ a S'₂, los estados que corresponden a S₁ y S₂", "Que la correspondencia se mantenga solo para las instrucciones privilegiadas"], a: 2, why: "El isomorfismo hace corresponder cada estado real con uno virtual (S₁ → S'₁, S₂ → S'₂) y conserva las transiciones: si e lleva de S₁ a S₂, en el virtual tiene que haber una e' que lleve de S'₁ a S'₂. No pide estados idénticos bit a bit y vale para todas las operaciones, no solo para las privilegiadas. Ejecutar sin el hipervisor es otra propiedad, la eficiencia de Popek y Goldberg (diap. 16), y solo se pide para «una fracción importante» de las instrucciones.", src: "T1 diap. 5" },
  { t: "virtualizar", q: "Un programa se ejecuta dentro de un guest. ¿Cuáles de estas observaciones son «temporizaciones atípicas»?", o: ["Una suma da un resultado distinto del que daría la máquina real", "Una lectura de disco tarda más que en la máquina real", "El kernel del SO guest tiene que modificarse para poder arrancar", "Un bucle de cálculo se queda parado unos milisegundos sin razón aparente"], a: [1, 3], why: "La diap. 6 da dos ejemplos: retardos adicionales en la E/S y pausas de la CPU sin razón aparente, por la implementación y por compartir recursos con otras MVs. Un resultado distinto o un guest modificado no son temporizaciones: rompen la propia definición (mismo comportamiento y sin modificación).", src: "T1 diap. 6" },
  { t: "virtualizar", q: "Un laboratorio quiere (1) seguir usando un programa antiguo de MS-DOS y (2) probar qué pasaría si actualiza su servidor, sin tocar el real. ¿Qué motivaciones de la virtualización cubren estos casos?", o: ["Ejecución de software obsoleto (legacy code)", "Green computing", "Simulación y experimentación (prototipos, sandboxes, what-if?)", "Facilitar el balanceo de carga"], a: [0, 2], why: "El caso 1 es legacy code y el 2, un what-if en un sandbox (diap. 7). Green computing y balanceo de carga son ventajas de la consolidación (diap. 8), que va de aprovechar mejor el hardware, no de estos casos.", src: "T1 diap. 7" },
  { t: "virtualizar", q: "Una empresa pasa de 20 servidores físicos casi ociosos a 20 MVs en 2 servidores, para ahorrar energía, espacio y gestión. ¿Qué motivación de las diapositivas persigue este cambio?", o: ["Simulación y experimentación (what-if?)", "Consolidación: ejecutar varios SSOO sobre un mismo hardware", "Seguridad y fiabilidad: fuerte aislamiento entre guests", "Ejecución de software obsoleto (legacy code)"], a: 1, why: "Es la consolidación de la diap. 8: varios SSOO sobre un mismo hardware y, dentro de ella, el green computing, porque «las máquinas físicas son caras, y su gestión». El aislamiento (diap. 7) ya lo tenían con 20 servidores separados: no es lo que busca este cambio.", src: "T1 diap. 8" },
  { t: "virtualizar", q: "Según la terminología de la diap. 9, ¿en cuál de estos casos hay un SO host?", o: ["Un servidor con un hipervisor bare metal (tipo 1) que ejecuta tres MVs", "Un servidor con Xen, un Linux en el Dom0 y dos DomU", "Un portátil con Windows 11 que ejecuta una MV de Ubuntu en VirtualBox", "Un portátil con Windows 11, sin hipervisor ni MVs"], a: 2, why: "Host es un SO instalado en el hardware físico «asumiendo que contiene algún guest»: el Windows con VirtualBox. En el bare metal, el hipervisor es un kernel sin SO debajo (diap. 24), y en Xen el Dom0 es una MV privilegiada cuyo SO la diap. 27 dibuja como «SO GUEST». Un Windows sin guests no hospeda nada.", src: "T1 diap. 9" },
  { t: "virtualizar", q: "En el esquema de capas de la diap. 9, ¿qué capa tiene justo debajo el kernel del SO guest?", o: ["El hipervisor, al que llama mediante hipercalls", "El hardware real, que comparte con el hipervisor", "El SO host", "La máquina virtual (hardware virtual)"], a: 3, why: "En la diap. 9, debajo del kernel del guest está la «Máquina Virtual (Hardware Virtual)» y, debajo de ella, el hipervisor y el hardware real. El guest ve un hardware, aunque sea virtual: por eso funciona sin modificación. Que luego muchas de sus instrucciones se ejecuten directamente en la CPU real es cómo lo implementa el hipervisor (trap & emulate), no la capa que tiene debajo. Llamar al hipervisor con hipercalls es paravirtualización (diap. 23), y el SO host, si lo hay, queda por debajo del hipervisor (diap. 25).", src: "T1 diap. 9" },
  { t: "virtualizar", q: "Los primeros SO se llamaban «supervisores» y el hipervisor nace como una evolución suya. En un x86 con soporte de virtualización (VT-x), ¿en qué anillo está el kernel de un SO y en cuál el hipervisor, respectivamente?", o: ["Ring 0 y ring 1", "Ring 0 y ring −1", "Ring 0 y ring −2", "Ring 3 y ring 0"], a: 1, why: "«Hiper» va más allá de «super»: el kernel del SO (el antiguo supervisor) está en el ring 0 y el hipervisor, por debajo y con más privilegio, en el que el dibujo de T3 diap. 14 llama «Ring −1». El ring −2 es el SMM (T3 diap. 8) y los anillos 1 y 2 «no se utilizan» (T3 diap. 6). «Ring 3 y ring 0» es el trap & emulate sin soporte hardware, con el guest deprivilegiado en modo usuario y el hipervisor en el ring 0 (T2 diap. 19). Es la P16 del cuestionario.", src: "T1 diap. 10; T3 diaps. 6, 8 y 14 (P16 del cuestionario)" },
  { t: "virtualizar", q: "El nombre «hipervisor» se debe a que se ejecuta siempre directamente sobre el hardware, sin ningún SO debajo.", o: ["Verdadero", "Falso"], a: 1, why: "Viene de que los primeros SO se llamaban «supervisores»: el hipervisor se concibe como una evolución del SO (diap. 10). Y no siempre va sobre el hardware: el tipo 2 (hosted) es una aplicación de un SO host (diap. 22).", src: "T1 diap. 10" },
  { t: "virtualizar", q: "El hipervisor debe tener el control completo de los recursos físicos. ¿Qué pasaría si el kernel del guest se ejecutara con todos los privilegios de la CPU real?", o: ["Las aplicaciones del guest tendrían que modificarse para poder ejecutarse", "Se perdería eficiencia, porque el hipervisor tendría que interpretar todas sus instrucciones", "Nada importante: el aislamiento entre MVs lo garantiza el propio SO guest", "Podría reprogramar el hardware real (MMU, dispositivos) y saltarse el control y el aislamiento del hipervisor"], a: 3, why: "Por eso trap & emulate siempre deprivilegia al guest: su modo privilegiado se emula por software «para que el kernel virtual no tenga privilegios sobre el hardware real» (T2 diaps. 5 y 18). La opción de la eficiencia es al revés: con todos los privilegios no habría traps que interpretar.", src: "T1 diap. 11 (y T2 diap. 5)" },
  { t: "virtualizar", q: "Un guest virtualizado con trap & emulate ejecuta 1000 sumas y después un OUT a un controlador de E/S, que provoca un trap. Según los módulos de la diap. 12, ¿qué le llega al intérprete del hipervisor?", o: ["Solo el OUT, que le pasa el dispatcher tras el trap", "Las 1001: el intérprete simula una a una todas las instrucciones del guest", "Solo las 1000 sumas: el OUT se ejecuta directamente en la CPU real", "Nada: tras un trap, el dispatcher llama siempre al allocator"], a: 0, why: "Con trap & emulate, las sumas se ejecutan directamente en la CPU real, sin el hipervisor. El OUT provoca el trap (T2 diap. 19) y el dispatcher se lo pasa al intérprete, que simula su efecto sobre el controlador virtual. Simularlas todas una a una es lo que hace un emulador (T2 diap. 5), y el allocator asigna recursos físicos a las MVs: no recibe todos los traps.", src: "T1 diap. 12 (y T2 diaps. 5 y 19)" },
  { t: "virtualizar", q: "Según la diap. 12, el hipervisor se parece mucho al kernel de un SO. ¿Qué tareas gestionan los dos, cada uno con sus clientes?", o: ["Compartir la CPU entre sus clientes", "Ofrecer ficheros y sockets a sus clientes", "Compartir la memoria entre sus clientes", "Controlar permisos y arbitrar el acceso a periféricos, discos y red"], a: [0, 2, 3], why: "La diap. 12 cita compartir CPU y memoria y controlar permisos y arbitrar periféricos, discos y red (permisos de acceso a dispositivos, no los de los usuarios del guest). Lo que ofrecen sí cambia: el SO da ficheros y sockets; el hipervisor, disco y NIC virtuales (diap. 13).", src: "T1 diap. 12" },
  { t: "virtualizar", q: "Escribe los tres módulos del hipervisor, en el orden de la diapositiva y separados por punto y coma (;).", s: ["dispatcher;allocator;interprete"], why: "Diap. 12: dispatcher (decide a qué módulo llamar tras un trap), allocator (asigna recursos físicos a las MVs) e intérprete (simula el efecto de las instrucciones que le manda el dispatcher). Moodle compara el texto: los nombres de la diapositiva, en orden y separados por «;».", src: "T1 diap. 12" },
  { t: "virtualizar", q: "Un servidor web que corre en un guest abre un socket TCP. Según la comparación hipervisor/SO, ¿quién le ofrece el socket y sobre qué?", o: ["El hipervisor, directamente sobre la NIC real", "El kernel del SO guest, sobre la NIC virtual que le ofrece el hipervisor", "El kernel del SO guest, directamente sobre la NIC real", "El hipervisor, que ofrece sockets a las MVs en lugar de NICs"], a: 1, why: "El SO convierte el hardware en servicios de alto nivel (NIC → sockets) y el hipervisor, en hardware virtual (NIC → NIC virtual). Las capas se apilan: el socket lo da el kernel del guest, que solo ve la NIC virtual.", src: "T1 diap. 13" },
  { t: "virtualizar", q: "Un proceso de un guest accede a una dirección de su espacio lógico. Según las capas de las diaps. 13 y 14, ¿qué traducciones hay, conceptualmente, hasta la RAM real?", o: ["Una: el kernel del guest traduce el espacio lógico directamente a la RAM real", "Una: el hipervisor traduce el espacio lógico a la RAM real y el guest no interviene", "Dos: el guest traduce a la RAM real y el hipervisor solo comprueba los permisos", "Dos: el kernel del guest, del espacio lógico a la RAM virtual, y el hipervisor, de la RAM virtual a la RAM real"], a: 3, why: "El SO ofrece la RAM como espacio lógico y el hipervisor, como RAM virtual (diap. 13), y en la diap. 14 una capa va encima de la otra: ELV → EFV dentro de la MV (tablas del guest) y EFV → EFR en el hipervisor (T2 diap. 39). Por eso son necesarias dos MMUs, una privada a cada MV y otra real en el hipervisor (T2 diap. 38, la P2 del cuestionario), y el hipervisor traduce, no solo comprueba permisos.", src: "T1 diaps. 13–14 (y T2 diaps. 38–39)" },
  { t: "virtualizar", q: "El hipervisor planifica directamente los threads de los procesos que corren dentro de cada guest.", o: ["Verdadero", "Falso"], a: 1, why: "Los clientes del hipervisor son MVs (diap. 13), y reparte la CPU entre ellas (round-robin, T2 diap. 36). Los procesos y threads de cada guest los planifica su propio kernel, encima del hardware virtual (diap. 14).", src: "T1 diap. 14" },
  { t: "virtualizar", q: "En un hipervisor tipo 2 (hosted), ¿quién tiene los drivers nativos y gestiona el hardware físico, y qué implica?", o: ["El SO host: el tipo 2 es menos seguro y, si el host se actualiza o se reinicia, puede afectar a la disponibilidad de los guests", "El propio hipervisor tipo 2, y por eso se considera más seguro que el tipo 1", "Cada SO guest, sobre la parte del hardware real que le asigna el allocator", "Una MV privilegiada (Dom0), que ejecuta los drivers de todos los guests"], a: 0, why: "En el hosted, el hipervisor es una aplicación (más un módulo del kernel) de un SO host que tiene los drivers nativos, el scheduling, la memoria virtual y las RTIs (diaps. 24–25): si ese SO se actualiza o se reinicia, caen los guests. En el ejercicio de las cajitas, «menos seguro» es del tipo 2 y «más seguro», del tipo 1; el Dom0 es del tipo 1 con dominio 0 (diap. 27).", src: "T1 diaps. 24–25 (y ejercicio de las cajitas)" },

  // ---------- 02 popek
  { t: "popek", q: "Las tres propiedades de un VMM según Popek y Goldberg (1974) son…", o: ["Equivalencia, eficiencia y control de recursos", "Velocidad, seguridad y portabilidad", "Aislamiento, migración y clonación", "Emulación, traducción y paravirtualización"], a: 0, why: "Equivalencia (salvo tiempos), eficiencia (la mayoría de instrucciones sin hipervisor) y control total de recursos." },
  { t: "popek", q: "La propiedad de eficiencia exige que…", o: ["El guest ocupe poca memoria", "Una fracción importante de las instrucciones se ejecute sin intervención del hipervisor", "El hipervisor sea tipo 1", "No haya traps"], a: 1, why: "Si todo pasara por el hipervisor, sería emulación." },
  { t: "popek", q: "Una instrucción privilegiada es la que…", o: ["Cambia la configuración de recursos", "Genera un trap si se ejecuta en modo usuario y solo funciona en modo privilegiado", "Depende del modo de la CPU", "Accede a memoria"], a: 1, why: "Definición de instrucción privilegiada." },
  { t: "popek", q: "Una instrucción que cambia la configuración de recursos del sistema (p. ej., la tabla de páginas) es…", o: ["Inocua", "Sensible de comportamiento", "Sensible de control", "Ilegal"], a: 2, why: "Control sensitive: cambia el modo, la memoria asignada, etc." },
  { t: "popek", q: "Una instrucción cuyo resultado depende de si la CPU está en modo usuario o supervisor es…", o: ["Sensible de comportamiento", "Sensible de control", "Inocua", "Privilegiada siempre"], a: 0, why: "Behaviour sensitive." },
  { t: "popek", q: "Teorema 1: se puede construir un VMM si…", o: ["Las privilegiadas son un subconjunto de las sensibles", "Las sensibles son un subconjunto de las privilegiadas", "No hay instrucciones privilegiadas", "La CPU tiene MMU"], a: 1, why: "Así toda sensible genera trap y cede el control al hipervisor." },
  { t: "popek", q: "El teorema 1 es una condición…", o: ["Necesaria", "Suficiente", "Necesaria y suficiente", "Ni necesaria ni suficiente"], a: 1, why: "Así lo dice la transparencia: condición suficiente de virtualizabilidad." },
  { t: "popek", q: "La virtualización recursiva (teorema 2) requiere que la máquina sea virtualizable y…", o: ["Que tenga soporte VT-x", "Que se pueda construir un VMM sin dependencias temporales", "Que sea de tipo 2", "Que el guest esté paravirtualizado"], a: 1, why: "Y no siempre es posible." },
  { t: "popek", q: "¿Qué relaja el teorema 3 (virtualización híbrida)?", o: ["La equivalencia", "El control de recursos", "La eficiencia: interpreta todo lo que el guest ejecuta en modo kernel", "Nada"], a: 2, why: "Basta con que las sensibles de usuario sean privilegiadas." },
  { t: "popek", q: "¿Por qué el x86 clásico (IA-32) no es virtualizable en sentido clásico?", o: ["Porque no tiene modo kernel", "Porque tiene instrucciones sensibles no privilegiadas que no generan trap en modo usuario (p. ej., POPF)", "Porque no tiene MMU", "Porque es de 32 bits"], a: 1, why: "No cumple el teorema 1." },
  { t: "popek", q: "En la matriz de la vCPU, si la CPU virtual es distinta de la real (V ≠ R) solo cabe…", o: ["Trap & emulate", "Traducción binaria", "Emulación", "Paravirtualización"], a: 2, why: "La emulación interpreta instrucción a instrucción; pierde la eficiencia." },
  { t: "popek", q: "¿Qué propiedad de Popek y Goldberg pierde la paravirtualización?", o: ["Equivalencia", "Eficiencia", "Control de recursos", "Ninguna"], a: 0, why: "El guest se modifica: ya no es idéntico a ejecutarse en la máquina real." },
  // del profesor: cuestionario
  { t: "popek", q: "¿Qué factor constituye una excepción al principio de fidelidad ó equivalencia de Popek y Golberg?", s: ["temporizaciones", "las temporizaciones", "temporización"], why: "T1, diap. 16: «Equivalencia: el programa debe mostrar un comportamiento idéntico… Excepción: temporizaciones». La idea de las pausas porque la CPU se comparte es buena, pero Moodle compara el texto: escribe solo la palabra de la diapositiva.", src: "Cuestionario, pregunta 11 · T1 diap. 16", prof: true },
  { t: "popek", q: "Considerese que se ejecuta un programa en el modo usuario de una CPU moderna. Si dicho programa intenta realizar la ejecución de una instrucción privilegiada, ¿qué evento tendrá lugar?", o: ["Un trap", "Una exceptión de división por cero", "Un fallo de TLB", "Un fallo de página"], a: 0, why: "Una instrucción privilegiada ejecutada en modo usuario provoca un trap (una excepción por falta de privilegio) que pasa el control al modo kernel. Es la base de trap & emulate.", src: "Cuestionario, pregunta 12", prof: true },
  { t: "popek", q: "¿Cuáles son las tres características esenciales de un monitor de máquinas virtuales (VMM) según el trabajo de Popek y Golberg?", s: ["equivalencia; eficiencia; control de recursos", "equivalencia; control de recursos; eficiencia"], why: "Equivalencia (se comporta igual que en la máquina real, salvo las temporizaciones), eficiencia (una fracción importante de las instrucciones se ejecuta sin el hipervisor) y control de recursos (el hipervisor controla por completo los recursos). Truco: E-E-C.", src: "Cuestionario, pregunta 25 · T1 diap. 16", prof: true },
  // nuevas
  { t: "popek", q: "Un programa del guest obtiene en la MV los mismos resultados que en la máquina real, pero sus operaciones de E/S tardan el doble. Según Popek y Goldberg, la MV incumple la equivalencia.", o: ["Verdadero", "Falso"], a: 1, why: "La equivalencia exige un comportamiento idéntico con una sola excepción: las temporizaciones. Los retardos adicionales de E/S son justo las «temporizaciones atípicas» que el tema admite como única diferencia (T1 diap. 6).", src: "T1 diap. 16" },
  { t: "popek", q: "Para ser lo más eficiente posible, un hipervisor deja que el guest ejecute directamente en la CPU real todas sus instrucciones, también las sensibles. Según Popek y Goldberg, ¿qué problema tiene?", o: ["Incumple la eficiencia, que exige que el hipervisor intervenga en todas las instrucciones", "Incumple la equivalencia, porque el guest notaría temporizaciones atípicas", "Pierde el control de recursos: las sensibles cambiarían o leerían la configuración real de la máquina", "Ninguno: así cumple a la vez las tres características esenciales"], a: 2, why: "La eficiencia solo pide que una fracción importante de instrucciones vaya sin el hipervisor, no todas: las sensibles cambian o dependen de la configuración de recursos y, si no pasan por él, pierde el control completo de los recursos reales y virtuales. Las temporizaciones no cuentan, porque son la excepción que admite la equivalencia.", src: "T1 diaps. 16–17" },
  { t: "popek", q: "Un guest infectado intenta leer la memoria de otras MVs del mismo servidor y no puede. ¿Qué característica esencial de Popek y Goldberg lo garantiza? (escribe su nombre exacto)", s: ["control de recursos", "el control de recursos", "control de los recursos"], why: "Con el control de recursos, el hipervisor tiene el control completo de los recursos reales y virtuales, y de ahí salen el aislamiento y la seguridad (vCPU: «Control de recursos => Aislamiento, seguridad»). «Aislamiento» no vale: es la consecuencia, no el nombre de la característica.", src: "vCPU" },
  { t: "popek", q: "Un hipervisor ejecuta una MV cuya CPU virtual es distinta de la real (V ≠ R) decodificando y simulando una a una todas las instrucciones del guest. ¿Qué característica esencial de Popek y Goldberg no cumple? (una palabra)", s: ["eficiencia", "la eficiencia"], why: "La eficiencia pide que una fracción importante de instrucciones se ejecute sin el hipervisor, y el emulador interviene en todas, inocuas incluidas: por eso la vCPU tacha la ❸ en la emulación. La equivalencia y el control de recursos sí se mantienen.", src: "vCPU" },
  { t: "popek", q: "Según el resumen de la vCPU, ¿qué técnica(s) cumple(n) la equivalencia (❶) de Popek y Goldberg?", o: ["Paravirtualización", "Emulación", "Trap & emulate", "Traducción binaria"], a: [1, 2, 3], why: "Las tres son full virtualization (❶ + ❷ + ❸) y el guest se ejecuta sin modificar; la emulación solo pierde la eficiencia (❸ tachada). La paravirtualización (❷ + ❸) renuncia a la equivalencia porque hay que modificar el kernel del guest.", src: "vCPU" },
  { t: "popek", q: "En una CPU que cumple el teorema 1, con un hipervisor de trap & emulate, ¿cuál de estas instrucciones del kernel del guest se ejecuta directamente en la CPU real, sin intervención del hipervisor?", o: ["La carga del registro base de la tabla de páginas", "Un OUT a un registro del controlador de red", "Un IRET, para volver del kernel a la aplicación de usuario", "Una suma entre dos registros (ADD)"], a: 3, why: "La suma es inocua: ni cambia ni depende de la configuración de recursos, así que va directa, y de ahí sale la eficiencia. Las otras tres son privilegiadas (cambio de la tabla de páginas, E/S con OUT y cambio de modo con IRET): el guest deprivilegiado provoca un trap y el hipervisor las emula (T2 diaps. 19 y 24).", src: "T1 diap. 17" },
  { t: "popek", q: "Clasifica, en terminología de Popek y Goldberg, estas dos instrucciones sensibles: (1) la que carga un valor nuevo en el registro base de la tabla de páginas y (2) POPF en el IA-32. Escribe las dos clases con los términos de la diapositiva, en ese orden y separadas por «;».", s: ["control sensitive;behaviour sensitive", "control sensitive;behavior sensitive"], why: "Cargar la base de la tabla de páginas cambia la configuración de recursos: control sensitive. POPF hace cosas distintas según esté la CPU en modo usuario o supervisor, y en modo usuario no da trap: su comportamiento depende de la configuración, así que es behaviour sensitive (control = cambia; behaviour = depende). Escríbelas en inglés, como en la diapositiva.", src: "T1 diap. 17" },
  { t: "popek", q: "En un IA-32 sin soporte hardware, el kernel de un guest deprivilegiado ejecuta POPF para deshabilitar las interrupciones: no salta ningún trap, las interrupciones siguen habilitadas en la CPU real y el guest continúa creyendo que las ha deshabilitado. Con trap & emulate puro, ¿qué característica de Popek y Goldberg se incumple?", o: ["Control de recursos", "Equivalencia", "Eficiencia", "Ninguna: si no hay trap, el hipervisor no tiene nada que emular"], a: 1, why: "En la máquina real, POPF en modo kernel sí deshabilitaría las interrupciones; en la MV no, y el guest no se entera, así que ya no se comporta igual: falla la equivalencia. El control de recursos se mantiene, porque el guest no ha cambiado nada real, y la eficiencia no se ve afectada. Lo confirma T3 diap. 12: POPF en el anillo 3 solo escribe los flags aritméticos y la MV no puede enmascarar las interrupciones (IF).", src: "T1 diap. 16" },
  { t: "popek", q: "Una CPU tiene 10 instrucciones sensibles y 12 privilegiadas, y 9 de las sensibles son privilegiadas. Según Popek y Goldberg, esta CPU…", o: ["cumple el teorema 1, porque hay más privilegiadas que sensibles", "no cumple el teorema 1: la sensible que no es privilegiada no daría trap en modo usuario", "no cumple el teorema 1, porque hay 3 privilegiadas que no son sensibles", "cumple el teorema 1: el 90 % de las sensibles son privilegiadas y la eficiencia solo pide una fracción importante"], a: 1, why: "El teorema 1 pide que las sensibles sean un subconjunto de las privilegiadas: importa la inclusión, no cuántas haya, y basta una sensible fuera para que no dé trap y el hipervisor no se entere. Las privilegiadas que no son sensibles dan igual.", src: "T1 diap. 18" },
  { t: "popek", q: "En un hipervisor de trap & emulate construido según el teorema 1, el kernel del guest se ejecuta en modo no privilegiado. ¿Por qué?", o: ["No siempre: solo hace falta si la CPU no tiene soporte hardware como VT-x", "Para que el guest sepa que está virtualizado y use hipercalls", "Porque las privilegiadas solo generan trap en modo usuario: en modo privilegiado se ejecutarían directamente y el hipervisor perdería el control", "Para que las instrucciones sensibles no privilegiadas también generen trap"], a: 2, why: "Una privilegiada solo da trap en modo usuario; si el kernel del guest fuera privilegiado, la ejecutaría directamente y nunca saltaría al hipervisor, así que trap & emulate deprivilegia siempre al guest (T2 diap. 18: «El SO de la MV se deprivilegia»). Y una sensible no privilegiada no da trap en ningún modo: ese es justo el problema del IA-32.", src: "T1 diap. 17" },
  { t: "popek", q: "En una CPU que cumple el teorema 1, con un hipervisor de trap & emulate, el kernel de un guest ejecuta una instrucción que cambia su tabla de páginas. ¿Qué afirmación(es) describe(n) lo que ocurre?", o: ["Se ejecuta directamente sobre la MMU real, porque es sensible de control", "La instrucción genera un trap y cede el control al hipervisor", "El traductor binario ya la había sustituido por una llamada al hipervisor", "El hipervisor emula su efecto sobre los recursos virtuales de esa MV"], a: [1, 3], why: "Con el teorema 1, toda sensible es privilegiada: el guest deprivilegiado provoca un trap y el hipervisor emula el efecto sin soltar el control de la MMU real. La traducción binaria no hace falta aquí: es para CPUs con sensibles no privilegiadas.", src: "T1 diap. 18" },
  { t: "popek", q: "La CPU virtual es idéntica a la real (V = R) y esta cumple el teorema 1. Según el resumen de la vCPU, ¿qué técnica de full virtualization le corresponde y qué características conserva?", o: ["Traducción binaria: equivalencia y control de recursos, pero no eficiencia", "Emulación: equivalencia y control de recursos, pero no eficiencia", "Paravirtualización: control de recursos y eficiencia, pero no equivalencia", "Trap & emulate: equivalencia, control de recursos y eficiencia"], a: 3, why: "En la vCPU, la fila del teorema 1 (sensibles dentro de privilegiadas) es trap & emulate, con ❶ + ❷ + ❸. La traducción binaria es la fila del teorema 3, la emulación es para V ≠ R y la paravirtualización no es full virtualization.", src: "vCPU" },
  { t: "popek", q: "En el IA-32 clásico (sin soporte hardware), PUSHF y POPF son sensibles pero no privilegiadas. ¿Qué consecuencia(s) tiene?", o: ["Trap & emulate puro no basta: esas instrucciones no avisan al hipervisor", "La arquitectura no se puede virtualizar de ninguna manera", "Se puede virtualizar con traducción binaria, que analiza el código del guest en tiempo de ejecución y sustituye lo problemático", "La arquitectura no cumple la condición del teorema 1"], a: [0, 2, 3], why: "Una sensible no privilegiada no da trap en modo usuario, así que no se cumple el teorema 1 y trap & emulate solo no basta. Pero el teorema 1 es solo una condición suficiente: VMware lo resolvió con traducción binaria (implementación híbrida, T2 diap. 26), y siempre queda la emulación.", src: "T2 diap. 25" },
  { t: "popek", q: "El teorema 2 exige, además de que la máquina sea virtualizable, que se pueda construir para ella un VMM sin dependencias de temporización (timing dependencies). ¿Por qué tiene sentido esta segunda condición?", o: ["Porque una MV solo garantiza la equivalencia salvo en las temporizaciones, y el VMM de dentro vería tiempos atípicos", "Porque el VMM de dentro tiene que ejecutarse en modo privilegiado real", "Porque la virtualización recursiva solo es posible con soporte hardware como VT-x", "Porque un VMM que dependa de los tiempos incumpliría la eficiencia"], a: 0, why: "Un VMM que corre dentro de una MV solo tiene garantizado un comportamiento idéntico salvo en las temporizaciones, así que no puede depender de ellas; por eso la recursiva no siempre es posible. La diapositiva da la condición pero no la explica: esto se deduce de la excepción de la equivalencia (T1 diap. 16).", src: "T1 diap. 19" },
  { t: "popek", q: "Si una máquina cumple el teorema 1, también es recursivamente virtualizable.", o: ["Verdadero", "Falso"], a: 1, why: "El teorema 2 pide dos cosas: que la máquina sea virtualizable y que se pueda construir un VMM sin dependencias de temporización. El teorema 1 solo da la primera, y la diapositiva avisa de que la virtualización recursiva no siempre es posible.", src: "T1 diap. 19" },
  { t: "popek", q: "Toda máquina que cumple la condición del teorema 1 cumple también la del teorema 3.", o: ["Verdadero", "Falso"], a: 0, why: "Las sensibles de modo usuario son una parte de las sensibles: si todas las sensibles son privilegiadas, también lo son las de usuario. Al revés no ocurre: el teorema 3 pide menos y, a cambio, relaja la eficiencia.", src: "T1 diap. 20" },
  { t: "popek", q: "En una CPU, todas las instrucciones sensibles en modo usuario son privilegiadas, pero hay alguna que solo es sensible en modo supervisor y no es privilegiada. Según Popek y Goldberg…", o: ["se puede construir un VMM híbrido (teorema 3), aunque menos eficiente", "cumple el teorema 1: basta con trap & emulate puro", "solo se puede virtualizar con emulación", "es recursivamente virtualizable (teorema 2)"], a: 0, why: "El teorema 3 solo pide que las sensibles de modo usuario sean privilegiadas, a costa de la eficiencia: el VMM interpreta todo mientras la MV está en modo kernel. No cumple el teorema 1, porque hay una sensible fuera de las privilegiadas, y la emulación no es la única salida.", src: "T1 diap. 20" },
  { t: "popek", q: "Con un VMM híbrido (teorema 3), una MV ejecuta (1) un bucle de cálculo de una aplicación de usuario y (2) la rutina del kernel del guest que cambia la tabla de páginas. ¿Cómo se ejecuta cada parte?", o: ["Las dos directamente en la CPU real; solo las instrucciones sensibles generan trap", "(1) directamente en la CPU real; (2) interpretada por el VMM", "(1) interpretado por el VMM; (2) directamente en la CPU real, con un trap en cada instrucción sensible", "Las dos interpretadas por el VMM, instrucción a instrucción"], a: 1, why: "El VMM híbrido interpreta todas las instrucciones mientras la MV está en modo kernel; en modo usuario las sensibles son privilegiadas, así que basta trap & emulate y el resto va directo (VMware lo hace con traducción binaria en modo kernel, T2 diap. 26). «Las dos directas con trap» es el teorema 1, y «todo interpretado», emulación.", src: "T1 diap. 20" },
  { t: "popek", q: "En el resumen de la vCPU, ¿qué técnica ocupa la casilla de FULL VIRTUALIZATION en la fila del teorema 3, en la que V = R pero no todas las instrucciones críticas (sensitive) son privilegiadas? (dos palabras)", s: ["traduccion binaria", "binary translation", "bt", "traducción binaria (bt)", "binary translation (bt)", "traducción binaria en tiempo de ejecución", "runtime binary translation"], why: "En la fila del teorema 3 (las sensibles se salen en parte de las privilegiadas), la vCPU pone Binary Translation (BT): el código del guest se analiza en tiempo de ejecución y lo problemático se sustituye por código seguro. Ojo: «virt. híbrida» es la etiqueta de la fila (el teorema 3), no lo que pone en la casilla. Trap & emulate es la fila del teorema 1, y la emulación, la de V ≠ R.", src: "vCPU" },
  { t: "popek", q: "En una CPU, algunas instrucciones que son sensibles en modo usuario no son privilegiadas. Según el tema 1, ¿cuál de estas opciones sigue sirviendo para virtualizarla?", o: ["Trap & emulate, porque las privilegiadas siguen generando trap", "Un VMM híbrido, según el teorema 3", "Ninguna: sin el teorema 1 no se puede construir un VMM", "La emulación, aunque se pierda la eficiencia"], a: 3, why: "No cumple ni el teorema 1 ni el 3 (hay sensibles de usuario no privilegiadas), pero «siempre nos quedará la emulación»: el emulador simula todas las instrucciones, interrupciones y traps, así que no depende de qué genere trap. El precio es la eficiencia.", src: "T1 diap. 20" },

  // ---------- 03 tipos
  { t: "tipos", q: "En un hipervisor tipo 1 (bare metal)…", o: ["Hay un SO host debajo", "El hipervisor es un kernel propio sin SO debajo", "La E/S la hace el Dom0", "El guest se modifica"], a: 1, why: "Ejemplo: VMware ESXi." },
  { t: "tipos", q: "En un hipervisor tipo 2 (hosted) las instrucciones privilegiadas las intercepta…", o: ["Un módulo insertado en el núcleo del SO host", "El Dom0", "El guest", "La BIOS"], a: 0, why: "Y la E/S se emula con servicios del SO real." },
  { t: "tipos", q: "¿Cuál de estos es un hipervisor hosted?", o: ["VMware ESXi", "Xen", "VirtualBox", "Hyper-V"], a: 2, why: "También VMware Workstation, Player, Fusion, Parallels y QEMU/KVM." },
  { t: "tipos", q: "Xen e Hyper-V son…", o: ["Tipo 2", "Tipo 1 con dominio 0 (MV privilegiada con los drivers)", "Emuladores", "Contenedores"], a: 1, why: "La E/S se hace a través de una MV privilegiada con drivers de un SO existente." },
  { t: "tipos", q: "La paravirtualización…", o: ["No requiere modificar el guest", "Modifica el kernel del guest y sustituye las instrucciones no virtualizables por hypercalls", "Solo funciona con V ≠ R", "Es lo mismo que la emulación"], a: 1, why: "Hay comunicación explícita guest-hipervisor." },
  { t: "tipos", q: "En full virtualization el SO guest…", o: ["Sabe que está virtualizado", "No es consciente de estar virtualizado y no se modifica", "Usa hypercalls", "Corre en el Dom0"], a: 1, why: "Está completamente desacoplado del hardware por el hipervisor." },
  { t: "tipos", q: "Los contenedores, según la taxonomía del tema, son…", o: ["Hipervisores tipo 1", "Virtualización a nivel de sistema operativo (Kind III), no realmente MVs", "Paravirtualización", "Emulación"], a: 1, why: "Igual que los runtimes de lenguajes como la JVM." },
  { t: "tipos", q: "Según la asignatura, QEMU/KVM es…", o: ["Tipo 1", "Tipo 2 (hosted)", "Tipo 1 con Dom0", "Un contenedor"], a: 1, why: "Aparece en la lista de hosted: QEMU es un proceso del host y KVM su módulo del kernel." },
  // del profesor: cuestionario
  { t: "tipos", q: "En un sistema virtualizado mediante el uso de un \"hosted hypervisor\", los procesos de una máquina virtual podrían listarse con un comando tipo ps:", o: ["Sólo en la máquina virtual a la que pertenece", "Desde cualquiera de las máquinas virtuales gestionadas por ese hipervisor", "Sólo pueden listarse desde el hipervisor en sí", "Desde el sistema operativo host"], a: 0, why: "En un hosted, el SO host solo ve el proceso del hipervisor (p. ej., QEMU). Los procesos del guest solo se ven dentro de su MV.", src: "Cuestionario, pregunta 3", prof: true },
  { t: "tipos", q: "¿En qué esquema de virtualización el Sistema Operativo guest es consciente de la existencia del hipervisor?", o: ["Virtualización nativa", "Hosted virtualization", "Paravirtualización", "Full virtualization"], a: 2, why: "En la paravirtualización se modifica el kernel del guest, que llama al hipervisor con hypercalls: sabe que está virtualizado. En full virtualization (nativa u hosted) el guest no lo sabe.", src: "Cuestionario, pregunta 6", prof: true },
  { t: "tipos", q: "KVM (Kernel-based Virtual Machine), como módulo instalable en Linux, nos proporciona un mecanismo de virtualización ...", o: ["paravirtualized", "native", "bare-metal", "hosted"], a: 3, why: "En las diapositivas QEMU/KVM es tipo 2 (hosted): KVM es un módulo del kernel Linux del host e «implementa virtualización hardware en Linux para la construcción de hipervisores tipo 2», aunque en Internet a veces lo llamen tipo 1.", src: "Cuestionario, pregunta 10 · T1 diaps. 24–25 y T3 diap. 23", prof: true },
  // del profesor: cajitas
  { t: "tipos", q: "¿En qué caja va: “Se comunica directamente con el HW, sin intermediarios”?", o: ["Tipo 1: native o bare-metal", "Tipo 1 + dominio 0", "Tipo 2: hosted"], a: 0, why: "El tipo 1 (bare-metal) es un kernel propio instalado sobre el hardware, sin SO debajo (p. ej., VMware ESXi).", src: "Cajitas del profesor: tipos de hipervisores", prof: true },
  { t: "tipos", q: "¿En qué caja va: “Se utiliza para sistemas en producción porque es más eficiente”?", o: ["Tipo 1: native o bare-metal", "Tipo 1 + dominio 0", "Tipo 2: hosted"], a: 0, why: "Sin capas intermedias, el tipo 1 es el más eficiente: por eso es el de producción.", src: "Cajitas del profesor: tipos de hipervisores", prof: true },
  { t: "tipos", q: "¿En qué caja va: “Se consideran más seguros”?", o: ["Tipo 1: native o bare-metal", "Tipo 1 + dominio 0", "Tipo 2: hosted"], a: 0, why: "El tipo 1 es un kernel mínimo dedicado solo a virtualizar: menos superficie de ataque. El tipo 2 tiene debajo un SO de propósito general entero. El tipo 1 es el dueño del edificio; el tipo 2, un inquilino.", src: "Cajitas del profesor: tipos de hipervisores", prof: true },
  { t: "tipos", q: "¿En qué caja va: “Usa los drivers de una MV para acceder al HW, lo que ofrece mayor disponibilidad y actualización de drivers”?", o: ["Tipo 1: native o bare-metal", "Tipo 1 + dominio 0", "Tipo 2: hosted"], a: 1, why: "El dominio 0 (Xen, Hyper-V) es una MV privilegiada con los drivers de un SO existente: el hipervisor los reutiliza en vez de tener los suyos.", src: "Cajitas del profesor: tipos de hipervisores", prof: true },
  { t: "tipos", q: "¿En qué caja va: “Puede afectar al rendimiento del sistema y a la disponibilidad (availability) de los guests en caso de actualización del SO de la MV privilegiada”?", o: ["Tipo 1: native o bare-metal", "Tipo 1 + dominio 0", "Tipo 2: hosted"], a: 1, why: "Toda la E/S de los guests pasa por el dominio 0: si su SO se actualiza o se reinicia, los guests lo notan.", src: "Cajitas del profesor: tipos de hipervisores", prof: true },
  { t: "tipos", q: "¿En qué caja va: “Implementa la E/S de los guests a través de una MV”?", o: ["Tipo 1: native o bare-metal", "Tipo 1 + dominio 0", "Tipo 2: hosted"], a: 1, why: "Es la definición del tipo 1 + dominio 0: la E/S de los guests se hace a través de la MV privilegiada.", src: "Cajitas del profesor: tipos de hipervisores", prof: true },
  { t: "tipos", q: "¿En qué caja va: “Es una aplicación que corre encima de un SO y se suele utilizar en desarrollo de sistemas y aplicaciones”?", o: ["Tipo 1: native o bare-metal", "Tipo 1 + dominio 0", "Tipo 2: hosted"], a: 2, why: "El tipo 2 (hosted) es una aplicación sobre un SO host, como VirtualBox, VMware Workstation o QEMU/KVM.", src: "Cajitas del profesor: tipos de hipervisores", prof: true },
  { t: "tipos", q: "¿En qué caja va: “No son tan eficientes debido a que hay una capa extra entre el hipervisor y el HW, además de procesos ajenos a los guests”?", o: ["Tipo 1: native o bare-metal", "Tipo 1 + dominio 0", "Tipo 2: hosted"], a: 2, why: "En el hosted, el SO host es una capa más entre el hipervisor y el HW, y sus procesos compiten con los guests.", src: "Cajitas del profesor: tipos de hipervisores", prof: true },
  { t: "tipos", q: "¿En qué caja va: “Son menos seguros y pueden afectar a la disponibilidad de los guests hasta el punto de reiniciarlos”?", o: ["Tipo 1: native o bare-metal", "Tipo 1 + dominio 0", "Tipo 2: hosted"], a: 2, why: "En el tipo 2, si el SO host se actualiza o se reinicia, caen todas sus MVs; y un SO de propósito general tiene más superficie de ataque.", src: "Cajitas del profesor: tipos de hipervisores", prof: true },
  // nuevas
  { t: "tipos", q: "Un compañero dice: «VirtualBox es un hipervisor tipo 2, así que pertenece a Kind II». ¿Qué es lo correcto?", o: ["Tiene razón: Kind II agrupa a los hipervisores hosted", "Se equivoca: VirtualBox es Kind I (full machine virtualization), dentro de los hipervisores tipo 2", "Se equivoca: VirtualBox es Kind III, porque se ejecuta como una aplicación más del SO host", "Se equivoca: VirtualBox es Kind I, pero tipo 1, porque inserta un módulo en el núcleo del SO"], a: 1, why: "Los tipos 1 y 2 son las dos variantes de Kind I (full machine virtualization), y Kind II es la paravirtualización: el número coincide, pero no es lo mismo. VirtualBox está entre los ejemplos de hosted, y ser una aplicación del SO host con un módulo en su núcleo es justo lo que define al tipo 2, no a Kind III ni al tipo 1.", src: "T1 diaps. 22 y 24" },
  { t: "tipos", q: "Según la taxonomía del tema (Kind I, II y III), ¿qué clasificaciones son correctas?", o: ["Un VMM que corre directamente sobre el HW, pero no emula con precisión la máquina y obliga a adaptar los SSOO guest a su interfaz → Kind II", "VMware ESXi → Kind II, porque corre directamente sobre el HW", "La Java Virtual Machine → Kind III", "Un contenedor → Kind I, porque es una máquina virtual completa"], a: [0, 2], why: "Kind II es el VMM que va sobre el HW sin emular con precisión la máquina, y Kind III agrupa los runtimes de lenguajes (como la JVM) y los contenedores, que según la diapositiva no son realmente una MV, sino virtualización a nivel de SO. ESXi también va sobre el HW, pero hace full machine virtualization: es Kind I, tipo 1.", src: "T1 diaps. 22 y 24" },
  { t: "tipos", q: "¿Qué afirmación(es) es(son) aplicable(s) a la paravirtualización?", o: ["Las instrucciones problemáticas se traducen en tiempo de ejecución a código seguro, sin modificar el kernel del guest", "Existe una comunicación explícita entre el SO guest y el hipervisor, con el objetivo de ser más eficaz", "El SO guest está completamente desacoplado del HW y no es consciente de que está siendo virtualizado", "El hipervisor ofrece hipercalls también para otras operaciones críticas del kernel: manejo de memoria, de interrupciones o información de reloj"], a: [1, 3], why: "La paravirtualización comunica explícitamente guest e hipervisor para ser más eficaz, y sus hipercalls cubren también memoria, interrupciones y reloj. Traducir en tiempo de ejecución sin tocar el kernel es traducción binaria, y el guest que no sabe que está virtualizado es el de full virtualization.", src: "T1 diap. 23" },
  { t: "tipos", q: "Hay que virtualizar un SO propietario cuyo kernel no se puede modificar. ¿Qué esquema queda descartado?", o: ["Full virtualization con traducción binaria, porque traduce en tiempo de ejecución el código del kernel del guest", "Full virtualization sobre un hipervisor bare-metal, como VMware ESXi", "Paravirtualización, sea cual sea el tipo de hipervisor", "Full virtualization sobre un hipervisor hosted, como VMware Workstation"], a: 2, why: "La paravirtualización implica modificar el kernel del guest (cambiar las instrucciones no virtualizables por hipercalls), así que sin acceso al kernel queda descartada, sea cual sea el hipervisor. La traducción binaria es full virtualization: traduce el código del guest en tiempo de ejecución, sin modificar ni recompilar su kernel.", src: "T1 diap. 23 y vCPU" },
  { t: "tipos", q: "En paravirtualización se modifica el kernel del guest para sustituir las instrucciones no virtualizables por llamadas que van directamente al hipervisor. ¿Cómo se llaman esas llamadas?", s: ["hipercalls", "hypercalls", "hipercall", "hypercall", "hiperllamadas", "hiperllamada", "hiper-calls", "hyper-calls"], why: "La diapositiva las llama «hipercalls» (hypercalls): son al hipervisor lo que una llamada al sistema es al kernel. Moodle compara el texto, así que escribe solo esa palabra.", src: "T1 diap. 23" },
  { t: "tipos", q: "En VirtualBox (hosted), el guest escribe un bloque en su disco virtual. ¿Cómo se implementa esa E/S?", o: ["El hipervisor la simula directamente sobre sus propios drivers, que controlan el disco real", "El hipervisor la reenvía a una MV privilegiada, que la ejecuta con los drivers de su SO", "El driver del SO guest accede directamente al disco real, porque el hipervisor solo virtualiza la CPU", "El módulo de kernel del hipervisor la intercepta y se emula con servicios del SO host, como un fichero"], a: 3, why: "En un hosted, el módulo de kernel intercepta la E/S, la emulación de dispositivos del hipervisor la traduce a servicios del SO real (ficheros) y los drivers nativos del SO host acceden al disco. Simularla sobre drivers propios es lo del tipo 1 (ESXi), y reenviarla a una MV privilegiada, lo del dominio 0.", src: "T1 diaps. 24–25" },
  { t: "tipos", q: "En un portátil con VMware Workstation, la MV va mucho más lenta mientras el usuario compila un proyecto grande en el IDE del host. ¿Qué lo explica?", o: ["El scheduler del SO host reparte la CPU real entre las MVs y el resto de procesos del host, como el IDE", "Al detectar carga en el host, el hipervisor pasa a emular por software todas las instrucciones del guest", "El módulo de scheduling de MVs del hipervisor da prioridad a los procesos del host frente a las MVs", "El guest tiene que pedir la CPU al SO host mediante hipercalls, que se encolan detrás de las del IDE"], a: 0, why: "En un hosted, cada MV es un proceso normal del SO host y es su scheduler el que reparte la CPU con el resto de aplicaciones: por eso el tipo 2 no es tan eficiente (capa extra y procesos ajenos a los guests). Un módulo «Scheduling MVs» propio solo lo tienen los hipervisores tipo 1 y tipo 1 con dominio 0.", src: "T1 diaps. 24–25 y ejercicio «Tipos de hipervisores»" },
  { t: "tipos", q: "En los diagramas del tema, ¿en qué esquemas los «Native Drivers», los que controlan el hardware real, quedan fuera del bloque del hipervisor?", o: ["Native (tipo 1), como VMware ESXi", "Hosted (tipo 2), como VirtualBox", "Native con dominio 0, como Xen o Hyper-V", "En ninguno: los drivers nativos son los «device drivers» que instala cada SO guest"], a: [1, 2], why: "En el hosted los drivers nativos son del SO host y, con dominio 0, de la MV privilegiada; solo el tipo 1 puro (ESXi) los lleva dentro del hipervisor. Los «device drivers» del SO guest manejan el hardware virtual de la MV, no el real.", src: "T1 diaps. 25–27" },
  { t: "tipos", q: "Un CPD quiere instalar el hipervisor directamente sobre el hardware de sus servidores, sin un SO debajo. Según los ejemplos del tema, ¿qué productos le sirven?", o: ["VMware ESXi", "Microsoft Hyper-V", "VMware Player", "Parallels Desktop for Mac"], a: [0, 1], why: "ESXi es el ejemplo de native puro, y Hyper-V (como Xen), el de native con dominio 0: en ambos el hipervisor va directamente sobre el HW, y en el segundo el SO con los drivers corre en una MV privilegiada (la partición padre) por encima del hipervisor, no debajo. VMware Player y Parallels Desktop for Mac están en la lista de hosted: son aplicaciones de un SO host.", src: "T1 diaps. 24–27" },
  { t: "tipos", q: "Tanto el Dom0 de Xen como el SO host sobre el que corre VirtualBox contienen los drivers nativos del hardware real. ¿Qué los diferencia?", o: ["El Dom0 es una MV que corre encima del hipervisor; el SO host está debajo del hipervisor tipo 2", "Nada: «Dom0» es el nombre que da Xen a su SO host", "El Dom0 se instala directamente sobre el HW y el hipervisor de Xen corre encima de él, como en un hosted", "El Dom0 es un proceso del hipervisor en modo usuario; el SO host, en cambio, es un kernel completo"], a: 0, why: "Con dominio 0, el hipervisor va directamente sobre el HW y el Dom0 es una MV más (en el dibujo, un guest paravirtualizado), privilegiada porque tiene acceso al hardware real. En el hosted es al revés: el SO host va sobre el HW y el hipervisor es una aplicación suya.", src: "T1 diaps. 24, 25 y 27" },
  { t: "tipos", q: "En un hipervisor hosted, el código de la CPU virtual se ejecuta dentro del módulo que el hipervisor inserta en el núcleo del SO host, no en un proceso de usuario.", o: ["Verdadero", "Falso"], a: 1, why: "Falso: el hosted ejecuta el código de la CPU virtual dentro de un proceso normal del SO host, en modo usuario. El módulo insertado en el núcleo es el que intercepta las instrucciones privilegiadas.", src: "T1 diap. 24" },
  { t: "tipos", q: "En un servidor con Xen hay que actualizar y reiniciar el SO Linux del Dom0. ¿Qué cabe esperar en los guests (DomU)?", o: ["Nada: el Dom0 es una MV aislada como las demás y los DomU no dependen de ella", "Nada: en Xen la E/S la simula el propio hipervisor sobre sus drivers, como en ESXi", "Puede afectar al rendimiento y a la disponibilidad de los guests, porque su E/S pasa por esa MV", "Los DomU pasan a usar sus propios drivers nativos hasta que el Dom0 vuelve a arrancar"], a: 2, why: "Con dominio 0, la E/S de los guests se implementa a través de la MV privilegiada, así que actualizar su SO puede afectar al rendimiento y a la disponibilidad de los guests. Que las MVs estén aisladas no evita esa dependencia, y los DomU no tienen drivers nativos propios.", src: "T1 diaps. 24 y 27; ejercicio «Tipos de hipervisores»" },
  { t: "tipos", q: "En un hipervisor hosted, la memoria de las MVs se gestiona a través de la memoria virtual del SO host, mientras que en un tipo 1 la gestiona el propio hipervisor.", o: ["Verdadero", "Falso"], a: 0, why: "Verdadero: en el dibujo del hosted, el acceso a memoria de la MV pasa por el módulo de kernel del hipervisor y por la memoria virtual del SO host antes de llegar a la RAM. El tipo 1 no tiene SO debajo, así que la gestión de memoria es un módulo del propio hipervisor.", src: "T1 diaps. 25–26" },
  { t: "tipos", q: "¿Qué afirmaciones describen a un hipervisor hosted (tipo 2)?", o: ["Es menos seguro y puede afectar a la disponibilidad de los guests hasta el punto de reiniciarlos", "Es una aplicación que corre encima de un SO y se suele usar para desarrollar sistemas y aplicaciones", "Se usa en sistemas en producción porque es más eficiente", "Usa los drivers de una MV para acceder al HW, lo que ofrece mayor disponibilidad y actualización de drivers"], a: [0, 1], why: "Las dos primeras son las tarjetas del tipo 2 en el ejercicio «Tipos de hipervisores»: depende del SO host que tiene debajo, así que si ese SO se actualiza o se reinicia, caen todas sus MVs. Producción y eficiencia son del tipo 1, y usar los drivers de una MV, del dominio 0. La comparación de seguridad sale del ejercicio: las diapositivas no la hacen.", src: "Ejercicio «Tipos de hipervisores» y T1 diap. 22" },
  { t: "tipos", q: "Un hipervisor hosted se considera más seguro que uno bare-metal, porque el SO host añade una capa más entre los guests y el hardware.", o: ["Verdadero", "Falso"], a: 1, why: "Falso: el que se considera más seguro es el tipo 1, y el tipo 2, menos (lo dice el ejercicio «Tipos de hipervisores»; las diapositivas no comparan su seguridad). La capa extra del SO host no lo hace más seguro: según el mismo ejercicio, le resta eficiencia y puede afectar a la disponibilidad de los guests hasta el punto de reiniciarlos.", src: "Ejercicio «Tipos de hipervisores» y T1 diap. 24" },
  { t: "tipos", q: "Una empresa duda entre VMware ESXi y VMware Workstation para sus servidores de producción. ¿Qué afirmaciones sobre ESXi son correctas?", o: ["Es más eficiente: no hay un SO host entre el hipervisor y el HW, ni procesos ajenos a los guests", "Aprovecha los drivers de un SO existente instalado en una MV privilegiada", "Se considera más seguro", "Simula la E/S directamente sobre sus propios drivers, sin pasar por los servicios de un SO host"], a: [0, 2, 3], why: "ESXi es tipo 1: se usa en producción porque es más eficiente, se considera más seguro (estas dos cosas salen del ejercicio «Tipos de hipervisores») y simula la E/S sobre sus propios drivers. Aprovechar los drivers de un SO instalado en una MV privilegiada es lo del dominio 0 (Xen, Hyper-V).", src: "T1 diaps. 24 y 26 y ejercicio «Tipos de hipervisores»" },
  { t: "tipos", q: "Una MV que en VirtualBox salía a Internet por NAT se migra a VMware ESXi. ¿Qué le ofrece ahora el hipervisor para conectarla?", o: ["Solo switches virtuales (con sus VLANs): no trae un modo NAT preconfigurado", "Los mismos modos que VirtualBox: bridged, NAT y host-only", "Switches y routers virtuales, con un router NAT ya preconfigurado", "Ninguna red propia: en un hipervisor native las MVs salen al exterior a través del Dom0"], a: 0, why: "En native, el hipervisor solo emula switches virtuales Ethernet, con sus VLANs (diap. 64); bridged, NAT y host-only son los modos de los hosted (diap. 63). Si hace falta NAT, el router hay que construirlo con una MV, como el «NAT» que aparece dentro del servidor en los dibujos de las diaps. 66–69 (es la respuesta de la P26 del cuestionario).", src: "T2 diaps. 63–64 y 66–69" },

  // ---------- 04 cpu
  { t: "cpu", q: "La emulación consiste en…", o: ["Ejecutar el guest directamente en la CPU", "Un intérprete que decodifica y simula una a una las instrucciones de la CPU virtual", "Reescribir bloques básicos", "Usar el modo guest"], a: 1, why: "Es lo más lento pero permite CPU virtual ≠ real." },
  { t: "cpu", q: "En el intérprete, si el guest ejecuta IN/OUT en modo usuario…", o: ["Se ejecuta en el hardware real", "Se emula el puerto", "Se provoca ILLEGAL_INSTRUCTION en la CPU virtual", "Se ignora"], a: 2, why: "El intérprete comprueba el modo VIRTUAL; en kernel sí emularía el puerto." },
  { t: "cpu", q: "En la traducción binaria, el código traducido se ejecuta…", o: ["En modo kernel real", "En modo usuario, emulando por software el modo privilegiado de la vCPU", "En el Dom0", "En el modo guest de VT-x"], a: 1, why: "Las privilegiadas se sustituyen por código seguro y callouts." },
  { t: "cpu", q: "¿Qué unidad traduce la traducción binaria?", o: ["Instrucciones sueltas", "Bloques básicos (código secuencial hasta un salto)", "Páginas de 4 KB", "Procesos completos"], a: 1, why: "Y los guarda en la Translation Cache." },
  { t: "cpu", q: "¿Cuál NO hay que traducir en la traducción binaria?", o: ["Instrucciones privilegiadas", "Control de flujo (call, ret, jmp)", "Direccionamientos relativos al PC", "Sumas entre registros"], a: 3, why: "Las inocuas se copian tal cual (IDENT)." },
  { t: "cpu", q: "Un problema de la traducción binaria es…", o: ["El código que se automodifica", "La falta de MMU", "Que el guest debe modificarse", "Que no admite E/S"], a: 0, why: "También el código autorreferente y sincronizar el vPC con las interrupciones." },
  { t: "cpu", q: "En trap & emulate, el SO guest…", o: ["Corre en modo kernel real", "Se desprivilegia: corre en modo no privilegiado y sus instrucciones privilegiadas provocan traps", "Se recompila", "Usa hypercalls"], a: 1, why: "Guest OS deprivileging." },
  { t: "cpu", q: "Con trap & emulate, una llamada al sistema que hace una E/S provoca aproximadamente…", o: ["0 traps", "1 trap", "3 traps (INT, IN/OUT, IRET)", "Un trap por instrucción"], a: 2, why: "Emular el paso a kernel, la E/S y la vuelta a usuario." },
  { t: "cpu", q: "Los shadow registers en trap & emulate son…", o: ["Registros de la GPU", "Copias por software del estado privilegiado de la CPU y el chipset (control, MMU, PIC, timers…)", "Registros de la TLB", "Puertos de E/S"], a: 1, why: "Es uno de los inconvenientes: hay que emular todo ese estado." },
  { t: "cpu", q: "La implementación híbrida usa…", o: ["BT en modo usuario y trap & emulate en kernel", "Trap & emulate en modo usuario y traducción binaria en modo kernel", "Solo emulación", "Solo hardware"], a: 1, why: "Patente de VMware (2002) para x86 sin soporte hardware." },
  { t: "cpu", q: "En la virtualización asistida por hardware, ¿qué es el VMCB?", o: ["Una caché de traducción", "Una estructura en memoria con el estado de la MV, la máscara de instrucciones que provocan exit y el diagnóstico del exit", "Un driver de red", "Un tipo de snapshot"], a: 1, why: "Virtual Machine Control Block." },
  { t: "cpu", q: "La instrucción que pasa de modo kernel (hipervisor) a modo guest es…", o: ["iret", "vmrun", "sysenter", "hlt"], a: 1, why: "Carga el estado del procesador desde el VMCB." },
  { t: "cpu", q: "Con soporte hardware, ¿qué provoca un exit?", o: ["Una llamada al sistema del guest", "Una suma", "Una instrucción IN/OUT del guest", "Un IRET del guest"], a: 2, why: "El guest ejecuta sus syscalls en modo pseudoprivilegiado sin salir; la E/S sí sale." },
  { t: "cpu", q: "Según el resumen del tema, el hardware de virtualización…", o: ["Emula todos los dispositivos", "Solo ayuda a mejorar el rendimiento interceptando instrucciones privilegiadas", "Elimina el hipervisor", "Hace innecesaria la MMU"], a: 1, why: "La emulación de los recursos sigue siendo software." },
  { t: "cpu", q: "¿Qué planificación aplica el hipervisor entre MVs?", o: ["FIFO sin expulsión", "Round-robin", "Prioridades estáticas sin expulsión", "Ninguna"], a: 1, why: "Con políticas configurables de reparto." },
  { t: "cpu", q: "¿Cuándo expulsa el hipervisor a una MV de la CPU real?", o: ["Solo cuando termina", "Cuando ejecuta HALT o cuando se le acaba el cuanto (timeout)", "Cuando hace una suma", "Nunca"], a: 1, why: "HALT es privilegiada: el hipervisor la detecta y planifica otra MV." },
  { t: "cpu", q: "Emular una CPU más antigua que la real…", o: ["Da más rendimiento", "Mejora la portabilidad (migración) y evita incompatibilidades, pero no aprovecha las mejoras", "Es obligatorio", "Impide usar KVM"], a: 1, why: "La visibilidad total aprovecha todo pero ata al modelo exacto de CPU." },
  { t: "cpu", q: "Los «tiempos de espera inexplicables» dentro de una MV se deben a…", o: ["Errores del guest", "Que el hipervisor está ejecutando otra MV", "La TLB", "El ballooning"], a: 1, why: "Es la única diferencia que admite la equivalencia." },
  { t: "cpu", q: "Las tecnologías hardware de virtualización de Intel y AMD son…", o: ["EPT y NPT", "VT-x y AMD-V", "SSE y AVX", "PCID y ASID"], a: 1, why: "EPT/NPT son las de memoria (nested paging)." },
  // del profesor: cuestionario
  { t: "cpu", q: "¿Qué afirmación(es) de las siguientes es(son) aplicable(s) al mecanismo de virtualización \"trap & emulate\"?", o: ["Las instrucciones más problemáticas del programa se traducen en run-time a fragmentos de código más inocuos", "La máquina virtual se ejecuta en un modo no-privilegiado del procesador", "Las instrucciones tipo IN y OUT, provocan excepciones que llaman a rutinas del hipervisor que simula el funcionamiento de los controladores de entrada/salida", "La ejecución de una instrucción privilegiada genera una execpción por falta de privilegio, dando lugar a la ejecución de una rutina del hipervisor"], a: [1, 2, 3], why: "La a (traducir en tiempo de ejecución las instrucciones problemáticas a fragmentos inocuos) es traducción binaria. Las b, c y d son trap & emulate: la MV corre en modo no privilegiado y cada instrucción privilegiada, también IN y OUT, provoca una excepción que atiende el hipervisor.", src: "Cuestionario, pregunta 1 · T2 diap. 19", prof: true },
  { t: "cpu", q: "El soporte hardware optimizado para trap & emulate, permite un hipervisor más eficiente porque ...", o: ["simplifica la emulación del paso a modo kernel del guest mediante un modo pseudoprivilegiado", "convierte las instrucciones de entrada/salida en instrucciones inocuas (no críticas)", "proporciona las conocidas como fast hypercalls", "no requiere un dom0"], a: 0, why: "El modo pseudoprivilegiado deja que el guest ejecute sus SYSCALL sin exit: no hay que emular el paso a modo kernel. La E/S sí sigue provocando exit.", src: "Cuestionario, pregunta 4 · T2 diap. 27", prof: true },
  { t: "cpu", q: "Es cierto que el mecanismo \"trap & emulate\" implica una pérdida efectiva de privilegios (de-privileging) del kernel del sistema operativo invitado (guest)?", o: ["Sólo si no está disponible un soporte específico en la CPU, como el VT-x", "Sólo si la CPU no es virtualizable", "No, por ejemplo esto no ocurre en los modernos procesadores multicore", "Sí, es parte de su funcionamiento"], a: 3, why: "Deprivilegiar al guest es justo lo que define trap & emulate: «El SO de la MV se deprivilegia (guest OS de-privileging)» y la MV corre en modo usuario del procesador. Con VT-x el guest tampoco tiene los privilegios reales: su kernel corre en el anillo 0 de VMX non-root, un modo pseudoprivilegiado en el que lo sensible provoca un VM exit (el tema 3 lo llama «virtualización clásica por trap & emulate»).", src: "Cuestionario, pregunta 8 · T2 diaps. 18–19 y 27", prof: true },
  { t: "cpu", q: "Un intérprete de CPU software, que trata de emular una arquitectura, debería emular:", o: ["Sólo las instrucciones privilegiadas", "De las instrucciones, sólo las privilegiadas; y además cualquier interrupción", "Todas las instrucciones, junto con cualquiera de las interrupciones y los traps", "Sólo las instrucciones críticas (sensitive)"], a: 2, why: "El emulador «decodifica y simula la ejecución una a una de las instrucciones de la CPU virtual», y su código también emula el salto a la rutina de interrupción (IRQ) y la entrada al kernel con INT (trap). «Solo las críticas» es la idea de trap & emulate y de la traducción binaria: un emulador no ejecuta nada directamente en la CPU real.", src: "Cuestionario, pregunta 22 · T2 diaps. 5–8", prof: true },
  { t: "cpu", q: "En una arquitectura con soporte de virtualización hardware, se implementa una CPU virtual cuyo ISA (instruction set architecture) no es estrictamente virtualizable. ¿Cómo se podría ejecutar un hipervisor en esta máquina virtual?", o: ["Mediante BT (binary translation) que es aplicable a las CPUs sin soporte hardware de virtualización", "Con CPUs que no tengan las restricciones de los procesadores x86 de Intel", "Es imposible, ya que no cumple los criterios de Popek y Goldberg sobre virtualización recursiva", "Mediante Trap and Emulate"], a: 0, why: "Si la vCPU no es estrictamente virtualizable, el hipervisor que corre dentro no puede usar trap & emulate: tiene que usar traducción binaria, que no necesita soporte hardware.", src: "Cuestionario, pregunta 23", prof: true },
  { t: "cpu", q: "Sobre el rendimiento de la traducción binaria en run-time, como mecanismo de virtualización, podría afirmarse que:", o: ["En la mayoría de los casos es mucho mejor que el del mecanismo de \"trap & emulate\"", "Es siempre extremadamente malo, comparable al de la emulación software", "Generalmente es muy malo, sobre todo si abundan las instrucciones inocuas en el programa", "Se puede optimizar bastante con el uso de cachés de traducción y reuso de los fragmentos de código"], a: 3, why: "«La traducción lleva cierto tiempo adicional, aunque el código una vez traducido puede ejecutarse indefinidamente»: lo traducido se guarda en la Translation Cache. La c es al revés: las instrucciones inocuas se copian tal cual (IDENT) y no cuestan nada; lo caro son las privilegiadas y los saltos.", src: "Cuestionario, pregunta 24 · T2 diaps. 5, 9 y 11", prof: true },
  { t: "cpu", q: "¿Cuál es la técnica de virtualización que fue empleada por VMWare en el software de virtualización del que fueron pioneros?", s: ["traducción binaria", "binary translation"], why: "Hacia 1999 VMware fue pionera en virtualizar el x86 con una «virtualización híbrida trap & emulate más traducción binaria just-in-time», traduciendo cuando el guest pasa a modo kernel (del anillo 3 al 0); es su patente 6,397,242. «Virtualización binaria» no existe como término.", src: "Cuestionario, pregunta 30 · T3 diap. 10 y T2 diap. 26", prof: true },
  // del profesor: cajitas
  { t: "cpu", q: "¿En qué caja va: “El intérprete tiene que analizar el código del guest en tiempo de ejecución (JIT)”?", o: ["Emulación", "Traducción binaria", "Trap & emulate"], a: 1, why: "Analizar y traducir el código del guest en tiempo de ejecución es traducción binaria: bloques básicos a código seguro, guardados en la caché de traducciones. La emulación no traduce nada: decodifica y simula las instrucciones una a una. La palabra «intérprete» es la trampa.", src: "Cajitas del profesor: virtualización de la CPU", prof: true },
  { t: "cpu", q: "¿En qué caja va: “Suele ralentizar mucho la ejecución de la VM”?", o: ["Emulación", "Traducción binaria", "Trap & emulate"], a: 0, why: "La emulación interpreta por software todas las instrucciones: es la técnica más lenta.", src: "Cajitas del profesor: virtualización de la CPU", prof: true },
  { t: "cpu", q: "¿En qué caja va: “Se utiliza cuando la CPU real es distinta a la virtual”?", o: ["Emulación", "Traducción binaria", "Trap & emulate"], a: 0, why: "Con V ≠ R solo cabe la emulación.", src: "Cajitas del profesor: virtualización de la CPU", prof: true },
  { t: "cpu", q: "¿En qué caja va: “El intérprete del hipervisor decodifica y simula cada instrucción del guest”?", o: ["Emulación", "Traducción binaria", "Trap & emulate"], a: 0, why: "Es la definición de emulación: todas las instrucciones, una a una.", src: "Cajitas del profesor: virtualización de la CPU", prof: true },
  { t: "cpu", q: "¿En qué caja va: “Se puede acelerar con una caché de traducciones”?", o: ["Emulación", "Traducción binaria", "Trap & emulate"], a: 1, why: "Lo traducido se guarda en la Translation Cache y se reutiliza: la traducción se paga una vez.", src: "Cajitas del profesor: virtualización de la CPU", prof: true },
  { t: "cpu", q: "¿En qué caja va: “La CPU real es igual a la virtual, pero hay instrucciones que impiden la virtualización clásica”?", o: ["Emulación", "Traducción binaria", "Trap & emulate"], a: 1, why: "Con V = R pero con sensibles no privilegiadas (como el x86 clásico) no vale trap & emulate: esas instrucciones se traducen.", src: "Cajitas del profesor: virtualización de la CPU", prof: true },
  { t: "cpu", q: "¿En qué caja va: “La CPU real es igual a la virtual y el guest se ejecuta deprivilegiado en la CPU real”?", o: ["Emulación", "Traducción binaria", "Trap & emulate"], a: 2, why: "Trap & emulate: el guest corre deprivilegiado y cada instrucción privilegiada provoca un trap que emula el hipervisor.", src: "Cajitas del profesor: virtualización de la CPU", prof: true },
  { t: "cpu", q: "¿En qué caja va: “Ofrece un rendimiento óptimo”?", o: ["Emulación", "Traducción binaria", "Trap & emulate"], a: 2, why: "Casi todo se ejecuta directamente en la CPU real; solo las privilegiadas pasan por el hipervisor.", src: "Cajitas del profesor: virtualización de la CPU", prof: true },
  { t: "cpu", q: "¿En qué caja va: “Arquitecturas x86 ofrecen soporte hardware para permitir este tipo de virtualización”?", o: ["Emulación", "Traducción binaria", "Trap & emulate"], a: 2, why: "VT-x (Intel) y AMD-V dan soporte hardware a trap & emulate, con un modo guest pseudoprivilegiado.", src: "Cajitas del profesor: virtualización de la CPU", prof: true },
  // nuevas
  { t: "cpu", q: "Un hipervisor ejecuta una MV con CPU virtual ARM sobre un servidor x86. El guest hace una simple suma entre registros (ADD). ¿Qué hace el hipervisor?", o: ["La deja ejecutarse directamente en la CPU real, porque es una instrucción inocua", "La decodifica y simula su efecto sobre los registros de la vCPU guardados en las estructuras de control", "La copia tal cual (IDENT) a la caché de traducciones", "Nada hasta que provoque un exit; entonces la emula"], a: 1, why: "Con V ≠ R solo cabe la emulación: el intérprete decodifica y simula una a una todas las instrucciones, también las inocuas (case ADD: …emulate add…), sobre los registros (GPRs) de la estructura de control de la vCPU. Ejecutarla en la CPU real, copiarla con IDENT o esperar un exit solo es posible si la CPU real es idéntica a la virtual.", src: "T2 diaps. 5–7" },
  { t: "cpu", q: "Un hipervisor emula (V ≠ R) una MV con 4 cores virtuales. Según el esquema de la implementación por emulación, ¿cómo se organiza?", o: ["4 procesos del hipervisor, uno por core, cada uno con su propia copia de la memoria física de la MV", "Un proceso con 1 thread intérprete que va alternando los 4 cores, y 4 estructuras de control de CPU virtual", "Un proceso con 4 threads intérpretes, 4 estructuras de control de CPU virtual y varios threads de emulación de E/S", "Un proceso con 4 threads intérpretes que comparten una única estructura de control de CPU virtual"], a: 2, why: "El esquema tiene un proceso del hipervisor por MV, con un thread intérprete y una estructura de control de CPU virtual por core (GPRs, status, control, PIC, PC, SP), más varios threads de emulación del hardware de E/S. La memoria física de la MV es una sola y la comparten todos sus cores: en el código, struct VM tiene cores[MAX_CORES] y un único mem.", src: "T2 diaps. 6 y 8" },
  { t: "cpu", q: "En el intérprete de CPU de las diapositivas, ¿cómo se emula la llegada de una interrupción externa (IRQ) a la MV?", o: ["En cada vuelta del bucle se mira si el PIC virtual tiene una IRQ pendiente y la vCPU las tiene habilitadas; si es así, se apilan PC y SR, se pasa a modo KERNEL y se salta al vector", "La atiende directamente el SO host, porque el intérprete solo emula instrucciones y deja las interrupciones al hardware real", "La CPU real provoca un exit, el hipervisor guarda el estado en el VMCB y la reinyecta en el guest con vmrun", "Se sustituye por un callout a HANDLE_INTS en la caché de traducciones, que comprueba el flag CPU_IRQ"], a: 0, why: "El bucle comprueba core.PIC.IRQ_pending && core.SR.IRQ_enabled antes de emular cada instrucción y, si se cumple, hace lo mismo que haría el hardware: apilar PC y SR, pasar a KERNEL y saltar a la rutina del vector (en la tabla a la que apunta IVTBR). El emulador emula también las interrupciones; los exits y los callouts son de otras técnicas.", src: "T2 diap. 7" },
  { t: "cpu", q: "En el intérprete de CPU de las diapositivas, si el guest ejecuta INT con la vCPU en modo usuario se produce una excepción ILLEGAL_INSTRUCTION, igual que con IRET o IN/OUT.", o: ["Verdadero", "Falso"], a: 1, why: "INT es la forma normal de entrar al kernel: el intérprete emula ese trap apilando PC y SR, pasando a modo KERNEL y saltando a la rutina de la tabla de vectores. Solo IRET e IN/OUT en modo USER provocan ILLEGAL_INSTRUCTION.", src: "T2 diap. 7" },
  { t: "cpu", q: "¿Cómo se llama la técnica en la que el hipervisor revisa en tiempo de ejecución el código de la MV, sustituye las instrucciones privilegiadas por código de emulación y llamadas a rutinas de emulación, y ejecuta el código resultante en modo usuario?", s: ["traduccion binaria", "traduccion binaria en tiempo de ejecucion", "traduccion binaria en run-time", "binary translation", "runtime binary translation", "run-time binary translation", "bt"], why: "Es la traducción binaria (runtime binary translation): analiza el código mientras se ejecuta, como un JIT, y reutiliza lo traducido desde la caché de traducciones (Translation Cache). La emulación no traduce nada: interpreta cada instrucción cada vez que se ejecuta. «Virtualización binaria» no existe como término.", src: "T2 diaps. 5 y 9" },
  { t: "cpu", q: "Con traducción binaria, el kernel del guest ejecuta OUT para escribir en un registro de su controlador de red virtual. ¿Qué hay en su lugar en la caché de traducciones?", o: ["La propia instrucción OUT, que al ejecutarse en modo usuario provocará una excepción", "La instrucción OUT tal cual (IDENT), porque la E/S no es una operación sensible", "Una instrucción que provoca un exit y deja el puerto en el VMCB", "Una llamada a una rutina de emulación que hace la E/S por medio del sistema subyacente"], a: 3, why: "La traducción binaria sustituye IN/OUT por llamadas a rutinas de emulación que hacen la E/S a través del sistema subyacente, así que el código traducido no lleva instrucciones privilegiadas. La excepción es lo que pasaría con trap & emulate, y el exit con VMCB, con soporte hardware.", src: "T2 diaps. 5 y 9" },
  { t: "cpu", q: "En el ejemplo de traducción binaria de la función que instancia el PTBR (cr3), ¿qué afirmaciones son correctas?", o: ["mov ebx, eax y and ebx, ~0xfff se copian tal cual (IDENT)", "mov ebx, cr3 se copia tal cual (IDENT), porque solo mueve datos entre registros", "cli se traduce INLINE por mov [CPU_IE], 0, que pone a 0 el flag de interrupciones de la vCPU", "ret se traduce por un salto al traductor (HANDLE_RET), aunque no sea privilegiada"], a: [0, 2, 3], why: "mov ebx, cr3 toca un registro de control y va INLINE + CALLOUT (mov [CO_ARG], ebx y call HANDLE_CR3). Las demás son como dicen: las inocuas, IDENT; cli, INLINE; y ret, que es control de flujo, CALLOUT al traductor.", src: "T2 diap. 11" },
  { t: "cpu", q: "En la traducción binaria, cli se traduce solo INLINE, pero sti lleva además test [CPU_IRQ], 1 y un CALLOUT a HANDLE_INTS. ¿Por qué?", o: ["Porque sti es una instrucción de control de flujo", "Porque al rehabilitar las interrupciones de la vCPU puede haber una IRQ virtual pendiente que hay que atender con una rutina de emulación", "Porque sti se deja tal cual en el código traducido y, al ejecutarse en modo usuario, provoca una excepción que atiende HANDLE_INTS", "Porque sti es una instrucción sensible y cli no"], a: 1, why: "Deshabilitar solo cambia un flag de la vCPU en memoria (mov [CPU_IE], 0); al habilitarlas puede haber una IRQ esperando (como en el intérprete: IRQ pendiente e IRQ habilitadas), así que se mira CPU_IRQ y se llama a HANDLE_INTS. La diapositiva no lo explica con palabras, se deduce del código traducido. sti no queda en la caché (se traduce por mov [CPU_IE], 1), y cli también es sensible: por eso tampoco va IDENT.", src: "T2 diap. 11" },
  { t: "cpu", q: "Con traducción binaria, un bloque básico ya traducido acaba en un salto condicional y uno de sus destinos no se ha ejecutado nunca. ¿Qué hay en la caché de traducciones para esa salida?", o: ["Una llamada al traductor (call END_BB), que se cambia por un jmp directo cuando se traduce el bloque destino", "El bloque destino ya traducido, porque el traductor traduce todo el código del guest antes de ejecutarlo", "Un salto a la dirección original del guest, que se ejecuta sin traducir", "Una instrucción privilegiada que provoca un trap para que el hipervisor elija el destino"], a: 0, why: "Solo se traducen los bloques básicos que se alcanzan: la salida a uno sin traducir salta al traductor (END_BB) y, cuando ya está traducido, se enlaza con un jmp directo y no se vuelve a pasar por el traductor. Nunca se ejecuta código del guest sin traducir ni se traduce todo de antemano.", src: "T2 diaps. 12–16" },
  { t: "cpu", q: "Con traducción binaria, un bucle del kernel del guest sin instrucciones privilegiadas se ejecuta un millón de veces. ¿Cuántas veces lo traduce el traductor?", o: ["Un millón: el traductor analiza cada instrucción cada vez que se ejecuta", "Ninguna: como no tiene instrucciones privilegiadas, se ejecuta directamente desde el código del guest", "Una por cada interrupción que llega, para resincronizar el vPC", "Una: la primera vez que se alcanza; después se ejecuta desde la caché de traducciones"], a: 3, why: "«El código una vez traducido puede ejecutarse indefinidamente»: se traduce la primera vez y se reutiliza desde la caché de traducciones. Analizar cada instrucción en cada ejecución es lo que hace el intérprete de la emulación, y ni un bucle de inocuas se ejecuta desde el código original, porque su salto hay que traducirlo.", src: "T2 diaps. 5 y 9" },
  { t: "cpu", q: "La diapositiva «Traducción binaria: a considerar» enumera los problemas que tiene que resolver el traductor. ¿Cuáles de estas situaciones están en esa lista?", o: ["Un programa con muchas instrucciones inocuas (sumas, movimientos entre registros)", "Un programa que lee su propia sección de código como si fueran datos", "Un guest sin modificar, que no usa hypercalls", "Una interrupción mientras se ejecuta código traducido: hay que saber en qué vPC del guest se produjo"], a: [1, 3], why: "La diapositiva enumera el código que se automodifica, el que se autorreferencia (usa su sección de código como datos) y la sincronización del vPC con las interrupciones, porque una instrucción del guest se convierte en varias. Las inocuas se copian tal cual (IDENT) y no plantean ningún problema, y no modificar el guest es justo lo que permite la traducción binaria.", src: "T2 diap. 17" },
  { t: "cpu", q: "Con trap & emulate, mientras el SO guest cree que se está ejecutando en modo kernel, la CPU real está en modo usuario.", o: ["Verdadero", "Falso"], a: 0, why: "El SO guest se deprivilegia siempre: la MV se ejecuta en modo usuario del procesador y su modo privilegiado se emula por software. Por eso cada instrucción privilegiada de su kernel provoca una excepción que atiende el hipervisor.", src: "T2 diaps. 18–19" },
  { t: "cpu", q: "Con trap & emulate, el kernel del guest ejecuta la instrucción privilegiada que carga el registro base de la tabla de vectores de interrupción. ¿Qué ocurre?", o: ["Se ejecuta directamente en la CPU real, porque el kernel del guest corre en modo privilegiado", "Se ignora sin generar excepción, porque el guest está en modo usuario", "Provoca una excepción por falta de privilegio y el hipervisor emula su efecto sobre su copia oculta del registro (shadow register)", "El traductor la sustituye por un CALLOUT a una rutina de emulación"], a: 2, why: "El kernel del guest corre en modo usuario, así que la privilegiada salta a una rutina del hipervisor, que actualiza el shadow register sin tocar el registro real. Ignorarse sin excepción solo les pasa a las sensibles no privilegiadas (como POPF en x86), y el CALLOUT es de traducción binaria.", src: "T2 diaps. 19 y 25" },
  { t: "cpu", q: "Una aplicación del guest hace una llamada al sistema (INT) que el kernel resuelve sin E/S ni ninguna otra instrucción privilegiada, y vuelve con IRET. ¿Cuántas veces interviene el hipervisor con trap & emulate y con soporte hardware?", o: ["3 con trap & emulate y 1 con soporte hardware", "2 con trap & emulate (INT e IRET) y ninguna con soporte hardware", "Ninguna en los dos casos, porque una llamada al sistema no usa instrucciones privilegiadas", "2 en los dos casos, porque el soporte hardware solo hace más rápido cada trap"], a: 1, why: "Con trap & emulate el guest está deprivilegiado y el hipervisor emula el paso a modo kernel (INT) y el retorno a modo usuario (IRET). Con el modo pseudoprivilegiado el guest ejecuta la SYSCALL sin exit (diap. 27) y, en el diagrama, también el IRET (diap. 33); solo saldría con IN/OUT. El «3 y 1» es el caso con E/S.", src: "T2 diaps. 24, 27 y 33" },
  { t: "cpu", q: "¿Qué afirmaciones son desventajas de trap & emulate según las diapositivas?", o: ["El proceso de las excepciones puede añadir mucho overhead", "Hay que modificar el kernel del guest para sustituir sus instrucciones privilegiadas por hypercalls", "El hipervisor debe emular por software todo el estado de CPU y chipset reservado al modo privilegiado (shadow registers)", "No sirve en CPUs con instrucciones que hacen cosas distintas en modo usuario y supervisor sin generar excepción, como el Intel x86 (IA-32)"], a: [0, 2, 3], why: "Son las tres desventajas de la diapositiva: overhead de las excepciones, shadow registers y CPUs no virtualizables en sentido clásico. Las hypercalls son de la paravirtualización: trap & emulate no modifica el guest.", src: "T2 diap. 25" },
  { t: "cpu", q: "De más lenta a más rápida, ¿qué orden de rendimiento es coherente con las diapositivas?", o: ["Traducción binaria → emulación → trap & emulate", "Emulación → trap & emulate → traducción binaria", "Emulación → traducción binaria → trap & emulate", "Trap & emulate → traducción binaria → emulación"], a: 2, why: "Trap & emulate es el «más rápido» (diap. 5) y la diap. 35 da el «mejor rendimiento» a la híbrida o a trap & emulate. La emulación interpreta cada instrucción cada vez; la traducción binaria paga el tiempo de traducir, pero reutiliza lo traducido. Las diapositivas no ordenan esas dos con palabras: se deduce de eso. La trampa típica es creer que la traducción binaria supera a trap & emulate.", src: "T2 diaps. 5 y 35" },
  { t: "cpu", q: "En el resumen vCPU, la traducción binaria está en la fila del teorema 3 y trap & emulate en la del teorema 1. ¿Qué distingue esas filas?", o: ["En la del teorema 3 la CPU virtual es distinta de la real (V ≠ R)", "En la del teorema 1 todas las instrucciones críticas (sensitive) son privilegiadas; en la del teorema 3 hay críticas que no lo son", "En la del teorema 3 el kernel del guest se modifica para usar hypercalls", "En la del teorema 1 todas las privilegiadas son críticas, pero hay críticas que no son privilegiadas"], a: 1, why: "Las dos filas son V = R. En la del teorema 1 el óvalo de las críticas cabe dentro del de las privilegiadas, así que toda crítica da trap y basta trap & emulate. En la del teorema 3 se sale: hay críticas que no dan trap, y el código del kernel hay que interpretarlo o traducirlo. V ≠ R es la fila de la emulación y las hypercalls son la columna de la paravirtualización.", src: "vCPU; T1 diaps. 18 y 20" },
  { t: "cpu", q: "Sobre la implementación híbrida (patente de VMware, 2002), ¿qué afirmaciones son correctas?", o: ["Necesita soporte hardware VT-x o AMD-V", "Ejecuta directamente el código de usuario del guest (trap & emulate) y traduce solo el del kernel, que se ejecuta en la caché de traducciones", "Traduce el código de usuario del guest y deja el del kernel para trap & emulate", "Las instrucciones privilegiadas del código traducido llegan al hipervisor por trap, igual que las del código de usuario"], a: [1], why: "«Trap & emulate para modo usuario» y «Binary Translation solo para modo kernel». En el diagrama, si trap & emulate vale se salta al PC del guest y las privilegiadas llegan por trap; si no, se traduce, se ejecuta en la TC y se llega por callout, porque el código traducido no tiene privilegiadas. No necesita soporte hardware: es la solución para el x86 antes de VT-x / AMD-V.", src: "T2 diap. 26" },
  { t: "cpu", q: "Según las diapositivas, ¿qué tienen en común trap & emulate, la implementación híbrida y el soporte hardware (VT-x / AMD-V)?", o: ["En todos, el kernel del guest se ejecuta en el modo privilegiado de la CPU real", "En todos, el código del kernel del guest se traduce antes de ejecutarse", "En todos, el kernel del guest se modifica para usar hypercalls", "En todos se construye un modo pseudoprivilegiado para la MV"], a: 3, why: "«En todos los casos se construye un modo pseudoprivilegiado para la MV»: por software en trap & emulate y en la híbrida, y por hardware con VT-x / AMD-V. El kernel del guest nunca tiene el modo privilegiado real; solo la híbrida traduce (y solo el kernel) y las hypercalls son de la paravirtualización.", src: "T2 diap. 35" },
  { t: "cpu", q: "Con soporte hardware, el guest ejecuta OUT y se produce un exit. ¿Dónde encuentra el hipervisor el puerto, el tamaño y la dirección de esa E/S?", o: ["En los campos de diagnóstico del exit, dentro del VMCB", "En la máscara de instrucciones que provocan exit, dentro del VMCB", "En la caché de traducciones, junto al bloque básico que contiene la OUT", "En una hypercall que el SO guest hace justo antes de la E/S"], a: 0, why: "El VMCB guarda shadow registers, la máscara de instrucciones que provocan exit y campos de diagnóstico del exit, y en una E/S esos campos llevan el puerto, el tamaño y la dirección. La máscara solo dice qué instrucciones salen, no los datos de cada exit.", src: "T2 diap. 28" },
  { t: "cpu", q: "Con soporte hardware (VT-x / AMD-V), si llega una interrupción mientras el guest se ejecuta en modo guest, se produce un exit y el control vuelve al hipervisor.", o: ["Verdadero", "Falso"], a: 0, why: "La diapositiva lo dice tal cual: «Las interrupciones provocan exits». Así el hipervisor recupera el control aunque el guest se esté ejecutando directamente en la CPU.", src: "T2 diap. 28" },
  { t: "cpu", q: "Una MV ejecuta un programa científico que detecta las instrucciones avanzadas de la CPU para ir más rápido, y nunca se va a migrar. ¿Qué le conviene?", o: ["Emular una CPU más antigua, que ofrece un modelo más sencillo y portable", "Visibilidad total de la CPU real, para que detecte y aproveche todas sus mejoras", "Trap & emulate, para que cada instrucción avanzada provoque un trap y la emule el hipervisor", "Cualquiera: el guest nunca puede detectar qué instrucciones avanzadas tiene la CPU real"], a: 1, why: "Con visibilidad total el software detecta las instrucciones avanzadas y aprovecha todas las mejoras; a cambio debe ser compatible con el modelo exacto de CPU, que aquí no importa porque no se migra. Emular una CPU más antigua da portabilidad, pero esconde esas instrucciones.", src: "T2 diap. 35" },
  { t: "cpu", q: "Sobre la multiplexación de la CPU entre MVs, ¿qué afirmaciones son correctas?", o: ["El proceso idle del SO guest suele ejecutar HALT, y el hipervisor aprovecha para planificar otra MV", "El hipervisor planifica las MVs por prioridades fijas y sin expulsión, para no romper la equivalencia", "Si una MV no ejecuta HALT durante su cuanto, el hipervisor interrumpe su ejecución (timeout)", "El guest no nota que lo han expulsado: no observa ningún efecto en los tiempos"], a: [0, 2], why: "La planificación es round-robin, con expulsión por HALT (es privilegiada, así que el hipervisor la detecta) y por timeout. El guest sí lo nota: ve tiempos de espera inexplicables.", src: "T2 diap. 36" },

  // ---------- 05 memoria
  { t: "memoria", q: "32 bits de dirección lógica, 1 GB de RAM y páginas de 4 KB. ¿Cuántas entradas tiene la tabla de páginas?", o: ["256 K", "1 M", "4 K", "18"], a: 1, why: "4 GB / 4 KB = 2^20 = 1 M entradas (una por página)." },
  { t: "memoria", q: "Mismo ejemplo: ¿cuántos bits hacen falta para el número de marco?", o: ["12", "20", "18", "30"], a: 2, why: "1 GB / 4 KB = 256 K marcos = 2^18." },
  { t: "memoria", q: "Mismo ejemplo: ¿cuánto ocupa la tabla de páginas de un nivel?", o: ["1 MB", "4 MB", "20 KB", "4 KB"], a: 1, why: "Entrada de 18 + 1 bits → 4 B; 1 M × 4 B = 4 MB." },
  { t: "memoria", q: "Con paginación de N niveles, cada acceso a un dato cuesta…", o: ["1 acceso", "N accesos", "N + 1 accesos", "2N accesos"], a: 2, why: "N para recorrer la tabla y 1 para el dato (sin acierto de TLB)." },
  { t: "memoria", q: "La TLB es…", o: ["Una tabla en disco", "Una caché de pares (página, marco)", "El registro base de la tabla", "Una zona de swap"], a: 1, why: "Soluciona el tiempo de traducción." },
  { t: "memoria", q: "Un fallo de página ocurre cuando…", o: ["V = 0", "La página es válida pero no está presente (P = 0)", "Hay acierto de TLB", "Se escribe en una página COW"], a: 1, why: "Con V = 0 es un fallo de segmentación." },
  { t: "memoria", q: "Tras atender un fallo de página, el SO…", o: ["Mata el proceso", "Reintenta la instrucción que provocó el fallo", "Reinicia la máquina", "Vacía la caché"], a: 1, why: "Trae la página, actualiza la tabla y reintenta." },
  { t: "memoria", q: "fork() con copy-on-write…", o: ["Copia toda la memoria del padre", "Crea la tabla del hijo apuntando a los mismos marcos y solo copia una página cuando alguien escribe", "Comparte la pila", "Usa el swap"], a: 1, why: "Es la misma idea que un snapshot de disco CoW." },
  { t: "memoria", q: "Con virtualización, ¿cuántos espacios de direcciones intervienen?", o: ["Uno", "Dos", "Tres: lógico del guest, físico del guest y físico real", "Cuatro"], a: 2, why: "ELV → EFV → EFR." },
  { t: "memoria", q: "¿Cuántas MMUs hacen falta conceptualmente?", o: ["Una", "Dos: una privada por MV y la real del hipervisor", "Una por proceso", "Ninguna"], a: 1, why: "La MV necesita su MMU emulada." },
  { t: "memoria", q: "Las shadow page tables traducen…", o: ["ELV → EFV", "EFV → EFR", "Directamente ELV → EFR", "EFR → disco"], a: 2, why: "El hipervisor programa la MMU real con la traducción directa." },
  { t: "memoria", q: "¿Cuántas shadow page tables hay?", o: ["Una por MV", "Una por proceso de cada MV", "Una por servidor", "Una por CPU"], a: 1, why: "Es parte de su overhead de memoria." },
  { t: "memoria", q: "Para enterarse de que el guest escribe en su tabla de páginas, el hipervisor (shadow)…", o: ["Lee la tabla cada segundo", "Marca esas páginas como solo lectura para que la escritura provoque un trap", "Usa la TLB", "No necesita enterarse"], a: 1, why: "Así mantiene la sombra coherente." },
  { t: "memoria", q: "Un hidden page fault es…", o: ["Un fallo en una página que el guest cree presente pero que el hipervisor ha sacado de la RAM real", "Un fallo de segmentación", "Un acierto de TLB", "Un fallo en el Dom0"], a: 0, why: "Ocurre porque el hipervisor puede quitar marcos a una MV." },
  { t: "memoria", q: "Intel EPT y AMD NPT/RVI son…", o: ["Tecnologías de red", "Implementaciones hardware de nested paging", "Formatos de disco", "Tipos de snapshot"], a: 1, why: "Dos juegos de tablas y dos punteros base (gCR3, nCR3)." },
  { t: "memoria", q: "Con nested paging de 4 niveles en el guest y 4 en las tablas nested, un acceso sin acierto de TLB cuesta…", o: ["5 accesos", "8 accesos", "16 accesos", "25 accesos"], a: 3, why: "(G + 1) × (N + 1) = 5 × 5 = 25." },
  { t: "memoria", q: "Con nested paging, ¿cuántas tablas nested hay?", o: ["Una por proceso", "Una por MV", "Una por CPU", "Ninguna"], a: 1, why: "Por eso ocupan menos que las shadow." },
  { t: "memoria", q: "¿Qué es el overcommitting de memoria?", o: ["Que la suma de RAM virtual en uso de las MVs supere la RAM física", "Usar páginas de 1 GB", "Desactivar el swap", "Dar más CPUs que núcleos"], a: 0, why: "El hipervisor recupera memoria con ballooning o swap privado." },
  { t: "memoria", q: "El fichero de swap que usa el hipervisor para una MV…", o: ["Es visible para el guest", "Es privado de cada MV e invisible para el guest", "Es el mismo que el del guest", "No existe"], a: 1, why: "El guest sigue creyendo que sus páginas están en RAM." },
  // del profesor: cuestionario
  { t: "memoria", q: "De alguna manera, al virtualizar la RAM, ¿son necesarias dos MMUs, una privada a cada máquina virtual y otra MMU real en el hipervisor?", o: ["Verdadero", "Falso"], a: 0, why: "Verdadero. T2, diap. 38: «Son necesarias dos MMUs: una MMU privada a cada MV y una MMU real en el hipervisor». La de la MV traduce ELV → EFV y la real EFV → EFR. La de la MV se implementa por software (shadow page tables) o por hardware (nested paging, EPT): por eso dice «de alguna manera».", src: "Cuestionario, pregunta 2 · T2 diap. 38", prof: true },
  // nuevas
  { t: "memoria", q: "Páginas de 4 KB (12 bits de desplazamiento). La CPU emite la dirección lógica 0x00005ABC y la TP asigna la página 0x5 al marco 0x12. ¿Qué dirección física genera la MMU?", o: ["0x00012ABC", "0x00017ABC", "0x00005ABC", "0x00012000"], a: 0, why: "La MMU cambia el número de página (0x5) por el de marco (0x12) y concatena f y d: 0x12 seguido de 0xABC. 0x00017ABC sale de sumar página y marco, 0x00005ABC es la dirección lógica sin traducir y 0x00012000 olvida que el desplazamiento pasa tal cual.", src: "Memoria diaps. 10 y 11" },
  { t: "memoria", q: "El SO pasa del proceso A al proceso B. ¿Qué hace con el PTBR?", o: ["Guarda el PTBR de A en su PCB y carga el de B, para que la MMU use la TP de B", "Lo deja como está y solo vacía (flush) la TLB: con eso la MMU ya traduce con la TP de B", "Copia la TP de B a la dirección fija a la que apunta siempre el PTBR", "Lo guarda en la TLB junto con los pares (página, marco) de A"], a: 0, why: "El PTBR apunta al marco donde empieza la TP del proceso en curso: se guarda en el PCB y se carga en el cambio de contexto. Vaciar la TLB no basta, porque la MMU seguiría recorriendo la TP de A; la TLB es una caché de pares (página, marco), no un sitio donde guardar registros, y copiar la TP entera sería carísimo.", src: "Memoria diaps. 10 y 19" },
  { t: "memoria", q: "Al cambiar de contexto, la TLB aún tiene pares (página, marco) del proceso que sale. ¿Qué puede hacerse para que el proceso que entra no traduzca con ellos?", o: ["Vaciar (flush) la TLB por completo", "Que cada entrada de la TLB lleve asociado el (P)ID del proceso", "Guardar la TLB en el PCB del proceso que sale", "Nada: la TLB guarda marcos físicos, que valen para cualquier proceso"], a: [0, 1], why: "La misma página lógica de dos procesos va a marcos distintos, así que hay que limpiar la TLB entera o etiquetar cada entrada con el (P)ID. Lo que se guarda en el PCB es el PTBR, no la TLB.", src: "Memoria diap. 19" },
  { t: "memoria", q: "En memoria virtual paginada, ¿qué guarda una entrada de la tabla de páginas?", o: ["El número de marco", "El bit de presencia (P)", "El desplazamiento (offset) dentro de la página", "El bit de modificado (dirty)"], a: [0, 1, 3], why: "Cada entrada lleva el número de marco, los bits V y P y otros bits de control (dirty, acceso, permisos). El desplazamiento no se guarda: pasa tal cual de la dirección lógica a la física.", src: "Memoria diaps. 10 y 20" },
  { t: "memoria", q: "Varios usuarios ejecutan a la vez el mismo compilador y sus procesos comparten las páginas de código. ¿Con qué permiso se marcan esas páginas en sus TPs?", o: ["Read-only (reentrant)", "Read-write", "Copy-on-write", "Private"], a: 0, why: "El código compartido entre procesos (editores, compiladores, GUIs) se marca read-only (reentrant). Read-write es para la memoria compartida con la que se comunican procesos, y con COW se crea un marco nuevo en la primera escritura.", src: "Memoria diap. 22" },
  { t: "memoria", q: "¿Para qué traduce el hipervisor por páginas la memoria física que da a las MVs?", o: ["Para poder asignar a cada MV memoria real no contigua y no asignarle las páginas que no usa", "Para que el guest no tenga que mantener sus propias tablas de páginas", "Para eliminar la fragmentación interna de la memoria de cada MV", "Para que el guest acceda directamente a la RAM real sin traducción"], a: 0, why: "La diapositiva lo da como motivo: libertad para asignar memoria no continua a cada MV y no asignar las páginas no usadas. El guest conserva sus TPs (ELV → EFV), y la paginación no elimina la fragmentación interna: es uno de sus inconvenientes.", src: "T2 diap. 38; Memoria diap. 9" },
  { t: "memoria", q: "Con shadow page tables, como la MMU real ya traduce directamente ELV → EFR, la MV no necesita una MMU propia, ni siquiera emulada.", o: ["Verdadero", "Falso"], a: 1, why: "Las shadow page tables son justo la implementación software de la MMU privada de la MV (la «MMU emulada»): el hipervisor intercepta lo que el guest programa en ella y carga en la real la traducción directa ELV → EFR. Por eso, «de alguna manera», siguen haciendo falta dos MMUs: una privada a cada MV y una real en el hipervisor.", src: "T2 diaps. 38 y 39" },
  { t: "memoria", q: "El SO guest anota en la TP de un proceso que su página 7 está en el marco 0x300. ¿En qué espacio de direcciones está ese marco?", o: ["En el EFV: el guest lo cree físico, pero aún hay que traducirlo al EFR", "En el EFR: el guest reparte directamente los marcos de la RAM real", "En el ELV: es una dirección lógica del proceso", "Depende: en el EFR con nested paging y en el EFV con shadow page tables"], a: 0, why: "La TP del guest traduce ELV → EFV, tanto con shadow como con nested; el paso EFV → EFR lo hace el hipervisor con la MMU real. Por eso hay dos niveles de traducción y dos MMUs: el guest nunca maneja marcos reales.", src: "T2 diaps. 39 y 43" },
  { t: "memoria", q: "¿Cómo se llaman las dos implementaciones de la MMU virtual? Escribe primero la software y después la hardware, con los nombres en inglés de la diapositiva, separados por «;».", s: ["shadow page tables; nested paging", "shadow page tables; nested paging/extended page table", "shadow page tables; nested paging / extended page table", "shadow page tables; nested paging/extended page tables", "shadow page tables; nested paging / extended page tables", "shadow page tables; extended page tables", "shadow page tables; extended page table", "shadow page tables; nested page tables", "shadow page tables; npt", "shadow page tables; ept", "shadow page table; nested paging", "shadow page table; extended page tables", "shadow page table; extended page table"], why: "La software (shadow page tables) intercepta lo que el guest programa en la MMU virtual y carga en la real la traducción directa ELV → EFR; la hardware (nested paging, que Intel llama extended page tables) añade a la MMU un segundo nivel EFV → EFR. Moodle compara el texto: escribe los nombres de la diapositiva, en ese orden.", src: "T2 diaps. 39 y 43" },
  { t: "memoria", q: "Con shadow page tables se guardan dos versiones de cada TP: la del guest y la shadow. ¿Qué papel tiene la del guest?", o: ["Solo sirve para interceptar los bits de control que escribe el guest; la que usa la MMU real es la shadow", "La MMU real recorre las dos en cada fallo de TLB: primero la del guest y luego la shadow", "Es la que usa la MMU real; la shadow solo guarda una copia de los bits de control", "Se carga en la MMU real cada vez que el guest cambia de proceso y escribe el PTBR"], a: 0, why: "La TP del guest está solo para interceptar sus bits de control (P, dirty, acceso…); la que está en uso en la MMU es la del hipervisor, con la traducción directa ELV → EFR. Recorrer dos tablas en cada fallo de TLB es lo que hace nested paging, no shadow.", src: "T2 diap. 39" },
  { t: "memoria", q: "Con shadow page tables, el SO guest cambia de proceso y escribe su PTBR. ¿Qué ocurre?", o: ["Se produce un exit: el hipervisor lo intercepta y carga en la MMU real la shadow de ese proceso", "Nada especial: el guest carga su PTBR en la MMU real, que recorre su TP como en una máquina sin virtualizar", "Se ejecuta sin salir al hipervisor, en modo pseudoprivilegiado, igual que una SYSCALL con VT-x", "Se produce un hidden page fault en la primera instrucción del nuevo proceso"], a: 0, why: "Escribir el PTBR (cambio de contexto) es uno de los exits de las shadow: el hipervisor intercepta lo que se programa en la MMU virtual y pone en la real la shadow de ese proceso (hay una por proceso). Si el guest cargara su propia TP en la MMU real, esta daría direcciones del EFV, no reales.", src: "T2 diaps. 40 y 42" },
  { t: "memoria", q: "Con shadow page tables, el kernel del guest escribe una entrada en la TP de uno de sus procesos. Si el hipervisor no hubiera marcado como solo lectura las páginas de esa TP, ¿qué pasaría?", o: ["La escritura pasaría desapercibida para el hipervisor: el guest corre en modo usuario y escribir en su TP es un acceso normal a memoria, sin trap", "Nada grave: el kernel del guest corre en modo kernel real y la MMU real ve el cambio directamente", "Daría trap igualmente, porque escribir en una TP es una instrucción privilegiada", "La TLB detectaría el cambio y actualizaría la shadow por su cuenta"], a: 0, why: "El guest corre deprivilegiado, en modo usuario, y escribir en su TP es un simple acceso a memoria, no una instrucción privilegiada (lo que sí sale al hipervisor es escribir el PTBR): sin trap, la shadow quedaría desfasada. Por eso el hipervisor marca esas páginas como solo lectura en la shadow.", src: "T2 diap. 41" },
  { t: "memoria", q: "Con shadow page tables, ¿cuáles de estas situaciones provocan un exit al hipervisor?", o: ["El guest asigna un marco a un proceso escribiendo P = 1 y el número de marco en su TP", "El guest borra la TP de un proceso que termina", "El guest lee un dato cuya traducción ya está en la TLB", "Un fallo de página"], a: [0, 1, 3], why: "Cada escritura del guest en la TP de un proceso (asignar marco, swap-out, bits dirty y acceso, borrado de la TP) sale al hipervisor, igual que el fallo de página y la escritura del PTBR. Un acierto de TLB no recorre ninguna tabla ni escribe en ella, así que no hay exit: el «bit de acceso» de la lista es una escritura del guest en su TP, no cada lectura.", src: "T2 diap. 42; Memoria diap. 21" },
  { t: "memoria", q: "Con shadow page tables, un proceso del guest accede a una página que no está ni en la máquina virtual ni en la real (true page fault). ¿Qué hace el hipervisor?", o: ["Intercepta el fallo, reserva un marco real, actualiza la shadow y devuelve el control a la RTI de fallo de página del guest (deprivilegiada)", "Lo resuelve entero sin que el guest se entere, igual que un hidden page fault", "Nada: el fallo va directo al guest, porque la shadow es una copia completa de su TP desde que arrancó la MV", "Mata el proceso, porque una página ausente en la TP del guest es un fallo de segmentación"], a: 0, why: "Como la página falta también para el guest, el hipervisor lee la ELV que falló, reserva (o reemplaza) un marco en el EFR, actualiza la shadow y deja que la RTI del guest haga su parte. Las shadow empiezan vacías y se van rellenando bajo demanda, con los fallos de página.", src: "T2 diap. 41" },
  { t: "memoria", q: "Con shadow page tables, el hipervisor ha llevado al swap privado de una MV páginas que su guest estaba usando. ¿Qué ocurre cuando el guest vuelve a acceder a una de ellas?", o: ["Un hidden page fault: en la TP del guest sigue con P = 1 y el hipervisor la trae sin que el guest se entere", "Un true page fault: el hipervisor devuelve el control a la RTI del guest para que la traiga de su swap", "Un fallo de segmentación en el guest, porque esa página ya no es válida en su TP", "Ningún fallo: la TLB conserva la traducción ELV → EFR y el acceso funciona"], a: 0, why: "El swap privado es invisible al guest, que sigue creyendo que la página está en RAM (P = 1): falta en la máquina real pero no en la virtual, y eso es un hidden page fault. En un true page fault falta en las dos, y entonces sí interviene la RTI del guest. Tampoco vale «ningún fallo»: al sacar la página se invalida su traducción en la TLB.", src: "T2 diaps. 41 y 45; Memoria diap. 21" },
  { t: "memoria", q: "Las shadow page tables obligan a modificar el kernel del guest para que avise al hipervisor de cada cambio en sus tablas de páginas.", o: ["Verdadero", "Falso"], a: 1, why: "Su ventaja es justo que el guest no requiere modificación: el hipervisor se entera por traps, porque marca como solo lectura las páginas de la TP del guest. Modificar el guest para que avise sería paravirtualización.", src: "T2 diap. 42; T1 diap. 23" },
  { t: "memoria", q: "En nested paging hay dos punteros base, gCR3 y nCR3. ¿A qué tabla apunta cada uno y quién la mantiene?", o: ["gCR3, a la TP del guest (ELV → EFV), que mantiene el SO guest; nCR3, a la tabla nested (EFV → EFR), que gestiona el hipervisor", "gCR3, a la tabla nested, que gestiona el hipervisor; nCR3, a la TP del guest, que mantiene el SO guest", "Los dos, a tablas del hipervisor: con nested paging el guest ya no mantiene TPs propias", "gCR3, a la shadow del proceso (ELV → EFR); nCR3, a la TP del guest"], a: 0, why: "Hay dos juegos de tablas: el guest mantiene las del primer nivel (ELV → EFV) y el hipervisor las del segundo (EFV → EFR), una por MV. Una tabla ELV → EFR directa es una shadow, y en nested paging no hay shadows.", src: "T2 diaps. 43 y 44" },
  { t: "memoria", q: "En nested paging, para leer cada entrada de la TP del guest, el hardware tiene que traducir antes su dirección con las tablas nested.", o: ["Verdadero", "Falso"], a: 0, why: "La TP del guest está en su memoria física virtual (EFV), y todo acceso de la MV al EFV necesita la traducción anidada, incluidos los accesos a su TP. Por eso el coste de un fallo de TLB es el producto (G + 1) × (N + 1) y no una suma.", src: "T2 diap. 44" },
  { t: "memoria", q: "Un guest de 32 bits con paginación de 2 niveles corre sobre nested paging con tablas nested de 4 niveles. Con fallo de TLB, ¿cuántos accesos a memoria cuesta en total leer un dato?", o: ["15", "25", "8", "3"], a: 0, why: "(G + 1) × (N + 1) = 3 × 5 = 15: las 2 entradas de la TP del guest y el propio dato necesitan cada uno un nested walk de 4 accesos más su propio acceso. 8 sale de sumar (G + 1) + (N + 1), 25 es el caso de 4 y 4 niveles y 3 es lo que costaría sin virtualizar (N + 1 con 2 niveles).", src: "T2 diap. 44; Memoria diap. 17" },
  { t: "memoria", q: "Con nested paging (G = 4, N = 4), el guest lee un dato cuya traducción está en la TLB. ¿Cuántos accesos a memoria hace?", o: ["1", "25", "5", "2"], a: 0, why: "La TLB cachea la traducción final ELV → EFR, así que con acierto no se recorre ninguna tabla: solo se accede al dato. Los 25 accesos de (G + 1) × (N + 1) son el coste de un fallo de TLB, y por eso la TLB es un factor crítico del rendimiento.", src: "T2 diaps. 39 y 44" },
  { t: "memoria", q: "Un servidor con 64 GB de RAM ejecuta 10 MVs configuradas con 8 GB cada una. ¿Qué afirmaciones son correctas?", o: ["Es overcommitting: la suma de RAM virtual en uso de las MVs puede superar la RAM física", "Con working set, cada MV recibe RAM real bajo demanda y el hipervisor mantiene solo las páginas accedidas en una ventana de tiempo", "Si se agota la RAM libre, el hipervisor puede guardar páginas en uso de una MV en un swap privado que el guest no ve", "El hipervisor reserva al arrancar los 8 GB completos de RAM real de cada MV"], a: [0, 1, 2], why: "Por localidad, muchas MVs solo usan una parte de su RAM, así que el hipervisor asigna bajo demanda y ajusta el working set; si aun así falta, reclama memoria no usada (ballooning) o guarda las páginas en uso en el swap privado de cada MV. Reservar 8 GB reales por MV al arrancar pediría 80 GB, más de los 64 que hay: haría imposible el overcommitting.", src: "T2 diap. 45" },
  { t: "memoria", q: "Si se agota la RAM libre del hipervisor, ¿con qué mecanismo (el ejemplo de la diapositiva) reclama la memoria que una MV no está usando?", s: ["ballooning", "memory ballooning"], why: "Es el ejemplo que da la diapositiva para reclamar memoria no usada por una MV. No lo confundas con el swap privado, que es para páginas que sí están en uso.", src: "T2 diap. 45" },

  // ---------- 06 discos, snapshots y clones
  { t: "discos", q: "¿Qué expone SCSI al guest?", o: ["La geometría del disco (cilindros, cabezas)", "Unidades lógicas (LUN) de bloques direccionados por LBA", "Ficheros", "Sectores físicos reales"], a: 1, why: "La geometría no se expone; siempre el mismo modelo de dispositivo." },
  { t: "discos", q: "Una ventaja de implementar el LUN sobre un volumen físico (by-pass) es…", o: ["Más portabilidad", "Menos retardo en cada acceso", "Permite thin provisioning", "Permite linked clones"], a: 1, why: "A cambio está atado a un volumen real." },
  { t: "discos", q: "Una ventaja de los discos virtuales sobre ficheros es…", o: ["Menos latencia", "Portabilidad y flexibilidad (mover el volumen sin tocar la MV)", "Más velocidad de transferencia", "No necesitan hipervisor"], a: 1, why: "Pero tienen más latencia y menos velocidad." },
  { t: "discos", q: "¿Qué tipo de disco da el mejor rendimiento?", o: ["Thin", "Thick lazy-zeroed", "Thick eager-zeroed", "Linked clone"], a: 2, why: "Todo reservado y a cero desde el principio; la creación es lenta." },
  { t: "discos", q: "En un disco thick lazy-zeroed…", o: ["Todo se pone a cero al crear", "Cada bloque se pone a cero en su primera escritura", "No se reserva espacio", "Se comparte con otras MVs"], a: 1, why: "Creación rápida, primera escritura más lenta." },
  { t: "discos", q: "¿Por qué hay que poner a cero los bloques reales?", o: ["Para comprimir", "Por seguridad: un bloque pudo ser de otra MV y no debe filtrarse su información", "Para que arranque", "Por la TLB"], a: 1, why: "Un bloque real puede reasignarse entre MVs." },
  { t: "discos", q: "¿Qué tipo de disco permite over-provisioning?", o: ["Thick", "Thin", "Ambos", "Ninguno"], a: 1, why: "Thin solo ocupa lo escrito; thick nunca hace overcommit." },
  { t: "discos", q: "Un problema de thin en discos duros mecánicos es…", o: ["La fragmentación: bloques consecutivos acaban separados y el acceso se vuelve aleatorio", "Que ocupa todo", "Que no admite snapshots", "Que no se puede borrar"], a: 0, why: "En HDD el acceso aleatorio es más lento que el secuencial." },
  { t: "discos", q: "Un disco flat (raw)…", o: ["Tiene copy-on-write", "No tiene copy-on-write: para clonar hay que duplicarlo todo", "Necesita un índice", "Siempre es thin"], a: 1, why: "El bloque N está en la posición N del fichero." },
  { t: "discos", q: "Un disco index (como qcow2)…", o: ["No admite snapshots", "Tiene un mapa de bloques que permite copy-on-write, backing files y snapshots baratos", "Siempre es thick", "Es más rápido que flat en todo"], a: 1, why: "A cambio, cada acceso consulta el índice." },
  { t: "discos", q: "¿Puede un disco index ser thick?", o: ["No, index implica thin", "Sí: thin/thick (cuándo se reserva) y flat/index (cómo se organiza) son independientes", "Solo en VMware", "Solo si es raw"], a: 1, why: "Por eso la matriz tiene cuatro casillas (p. ej., qcow2 con preallocation=full)." },
  { t: "discos", q: "En un snapshot copy-on-write, las escrituras van…", o: ["Al volumen congelado", "Al volumen delta", "A los dos", "A la RAM"], a: 1, why: "El volumen original queda de solo lectura." },
  { t: "discos", q: "En un snapshot copy-on-write, las lecturas…", o: ["Van siempre al volumen base", "Van primero al delta y, si el bloque no está, al volumen congelado", "Van siempre al delta", "No se permiten"], a: 1, why: "Por eso hay que consultar el índice de bloques modificados del delta." },
  { t: "discos", q: "¿Por qué los snapshots disminuyen el rendimiento?", o: ["Por la gestión de espacio al escribir y la consulta del índice al leer", "Porque comprimen", "Porque desactivan la TLB", "No lo disminuyen"], a: 0, why: "Escrituras con reserva de espacio y lecturas con consulta." },
  { t: "discos", q: "Un snapshot de una MV completa (checkpoint) guarda…", o: ["Solo los discos", "Los discos, la RAM y la configuración hardware", "Solo la RAM", "Solo la configuración"], a: 1, why: "Por eso permite volver exactamente al estado en ejecución." },
  { t: "discos", q: "Volver a un snapshot (revert/rollback)…", o: ["Es muy lento porque copia todo", "Es muy rápido: se elimina el delta actual y se crea uno nuevo sobre el snapshot", "Borra el disco base", "Requiere consolidar"], a: 1, why: "Si es un checkpoint, además se carga la RAM guardada." },
  { t: "discos", q: "Eliminar un snapshot suele implicar…", o: ["Nada", "Una consolidación: incorporar el delta al siguiente o al base", "Reiniciar la MV", "Borrar la plantilla"], a: 1, why: "Si no, puede haber corrupción; tarda según lo que haya que consolidar." },
  { t: "discos", q: "«Delete all»…", o: ["Borra la MV", "Sigue en el estado actual sin snapshots, escribiendo los deltas en el base en orden de creación", "Vuelve al primer snapshot", "Borra solo el último"], a: 1, why: "Caso particular de eliminar." },
  { t: "discos", q: "Un linked clone…", o: ["Es una copia completa", "Guarda solo las diferencias respecto a la plantilla mediante un snapshot de su disco", "No necesita la plantilla", "Es siempre más lento de crear"], a: 1, why: "Por eso se crea casi al instante y ocupa poco." },
  { t: "discos", q: "¿Cuál es un inconveniente de los linked clones?", o: ["Tardan mucho en crearse", "No se puede actualizar la plantilla sin destruir los clones", "Ocupan mucho disco", "No comparten caché"], a: 1, why: "Sus deltas son relativos a esa plantilla." },
  { t: "discos", q: "¿Por qué los linked clones mejoran la concurrencia de E/S?", o: ["Porque no leen del disco", "Porque varias MVs leen los mismos bloques de la plantilla y la caché de disco del hipervisor acierta más", "Porque usan RAID", "No la mejoran"], a: 1, why: "Si arrancan a la vez, el uso de disco no se multiplica por el número de MVs." },
  { t: "discos", q: "Un uso típico de los linked clones es…", o: ["Bases de datos de producción", "Escritorios virtuales (VDI) con un broker que crea y destruye clones", "Copias de seguridad a largo plazo", "Migrar servidores físicos"], a: 1, why: "Ejemplos de brokers: Leostream, Citrix Virtual Apps and Desktops." },
  { t: "discos", q: "Si una base de datos modifica el 90 % de sus bloques entre snapshots…", o: ["El delta será diminuto", "El delta se acercará a una copia completa y el snapshot CoW apenas compensa", "No se puede hacer snapshot", "El base crece"], a: 1, why: "Volatilidad: un bloque se copia al delta la primera vez que cambia." },
  // del profesor: cuestionario
  { t: "discos", q: "¿Cuál de los siguientes términos hace referencia a la operación de revertir a un estado anterior de un snapshot de un disco virtual?", o: ["Playback", "Rollback", "Fallback", "Callback"], a: 1, why: "Volver a un snapshot es deshacer: rollback o revert. Se descarta el delta actual y se crea uno nuevo sobre el snapshot.", src: "Cuestionario, pregunta 9 · T2 diap. 56", prof: true },
  { t: "discos", q: "Después de realizar un snapshot de una imagen de disco, se realizan N escrituras en él. ¿De qué orden es el tiempo requerido para realizar el commit de los cambios realizados?", o: ["O(1)", "O(N ×N)", "O(log2(N))", "O(N)"], a: 3, why: "El tiempo de consolidar depende de la cantidad de información que hay que consolidar: con N escrituras en el delta, O(N).", src: "Cuestionario, pregunta 15 · T2 diap. 56", prof: true },
  { t: "discos", q: "Al revertir a un estado anterior de un un snapshot de un disco virtual ...", o: ["se realiza la intersección del disco base con el disco Δ", "se descarta el disco base del snapshot, quedando en uso sólo el disco Δ", "se descartan completamente los cambios del disco Δ", "se consolidan los cambios del disco Δ"], a: 2, why: "Revertir descarta los cambios del delta actual: se elimina y se crea uno nuevo, vacío, sobre el snapshot. Consolidar los cambios del delta es lo que se hace al eliminar un snapshot.", src: "Cuestionario, pregunta 18 · T2 diap. 56", prof: true },
  { t: "discos", q: "¿Cuál de las siguientes características no es cierta en referencia a un disco virtual implementado como fichero imagen almacenado en un disco real?", o: ["Es posible no asignar el espacio libre en la creación del volumen virtual", "Las imágenes proporcionan más portabilidad y flexibilidad", "El acceso es mucho más rápido que si hubiera sido implementado sobre una partición nativa del disco real", "Es posible cambiar más fácilmente de ubicación el disco virtual sin modificar la MV"], a: 2, why: "Es la falsa: un disco sobre fichero va más lento que sobre una partición nativa del disco real (by-pass), con menos velocidad de transferencia y más latencia. A cambio da portabilidad y flexibilidad, y puede ser thin.", src: "Cuestionario, pregunta 20 · T2 diap. 47", prof: true },
  { t: "discos", q: "Sean A y Δ los discos base e incremental de un snapshot: A = {0: ∅, 1:∅, 2:K, 3:M, 4:N} Δ = {1:X, 2:Y} (nota: b:c indica que el contenido del bloque b-ésimo es c; ∅=bloque vacío) Tras una consolidación (commit), el contenido del volumen resultante, R, será:", o: ["R = {0: ∅, 1:X, 2:Y, 3:M, 4:N}", "R = {0: ∅, 1:∅, 2:∅, 3:∅, 4:∅ }", "R = {0: ∅, 1:X, 2:Y, 3:∅, 4:∅}", "R = {0: ∅, 1:∅, 2:K, 3:M, 4:N}"], a: 0, why: "Consolidar copia los bloques del delta sobre el base: los bloques 1 y 2 pasan a ser X e Y, y el resto (0, 3 y 4) se queda como estaba en A.", src: "Cuestionario, pregunta 21 · T2 diap. 56", prof: true },
  // nuevas
  { t: "discos", q: "El driver SCSI de un guest escribe un comando en la HBA LSI Logic que emula el hipervisor. ¿Cómo lo intercepta el hipervisor?", o: ["Con una hypercall: el driver SCSI del guest está paravirtualizado y avisa al hipervisor", "Con un trap: por IN/OUT si el driver usa PIO, o por la protección de memoria contra escritura si usa MMIO", "No lo intercepta: la HBA real lee el comando de la memoria del guest por DMA", "Por traducción binaria del driver, que cambia cada escritura en la HBA por una llamada al sistema de ficheros del host"], a: 1, why: "El driver de la SCSI Application Layer (SAL) del guest escribe el comando en la HBA emulada por PIO o por MMIO, y el hipervisor hace trap por IN/OUT (PIO) o por protección de memoria contra escritura (MMIO) e intercepta el comando SCSI. Las hypercalls serían paravirtualización, y aquí el guest usa el driver normal de esa HBA.", src: "Disco diap. 1" },
  { t: "discos", q: "Si el administrador pasa el LUN de una MV de un fichero del hipervisor a un volumen físico real (by-pass), el SO guest necesita otro driver SCSI.", o: ["Verdadero", "Falso"], a: 1, why: "El hipervisor siempre ofrece el mismo modelo de dispositivo SCSI, con el mismo driver en el guest para todas las implementaciones; cada LUN se implementa de forma transparente sobre un volumen real o sobre un fichero.", src: "T2 diap. 46" },
  { t: "discos", q: "Vas a convertir en MV un servidor físico que ya existe y que ejecuta una aplicación crítica. Según las diapositivas, ¿sobre qué implementarías su LUN?", o: ["Sobre un fichero thin, que es más portable y no asigna el espacio libre", "Sobre un volumen físico real (by-pass), que añade menos retardo a cada acceso", "Sobre un linked-clone de una plantilla, que se crea casi al instante", "Sobre un fichero thick eager-zeroed, que por ser un fichero tiene menos latencia que un volumen real"], a: 1, why: "El by-pass añade menos retardo a cada acceso y se usa para aplicaciones críticas o para migrar un servidor existente, a cambio de menos portabilidad. Un disco sobre fichero, aunque sea eager-zeroed, tiene más latencia y menos velocidad de transferencia.", src: "T2 diap. 47" },
  { t: "discos", q: "Se escribe por primera vez en un bloque de un disco virtual implementado sobre fichero. ¿Qué afirmaciones son correctas? (Selecciona una o más)", o: ["En thin hay que buscar un bloque libre en el disco real, ponerlo a cero y escribir", "En thick lazy-zeroed el bloque ya está asignado, pero hay que ponerlo a cero antes de escribir", "En thick eager-zeroed la creación es rápida y la puesta a cero se paga en la primera escritura", "En thick lazy-zeroed la primera escritura es igual de rápida que en eager-zeroed, porque el espacio ya está asignado"], a: [0, 1], why: "Thin asigna a demanda: en cada primera escritura busca bloque libre, lo pone a cero y escribe. Thick lo asigna todo al crear; eager-zeroed también lo pone a cero al crear (creación lenta, mejor rendimiento) y lazy-zeroed en el primer write (creación rápida, primer write más lento).", src: "T2 diap. 48" },
  { t: "discos", q: "Un disco virtual es un fichero raw disperso: el bloque con LBA N está en la posición N × tamaño de bloque y el host solo reserva espacio para lo que se ha escrito. ¿En qué casilla de la matriz thin/thick × flat/index está?", o: ["Thin y flat", "Thick y flat", "Thin e index", "Thick e index"], a: 0, why: "Son dos ejes independientes: thin/thick dice cuándo se reserva el espacio (a demanda → thin) y flat/index cómo se localiza el bloque (posición calculada, sin índice → flat). El qcow2 normal de las prácticas sería thin e index.", src: "Clase (nota de prácticas, sec. 18)" },
  { t: "discos", q: "Entre dos snapshots, una base de datos hace un millón de escrituras, todas sobre los mismos 200 bloques (hotspot). ¿Cuántos bloques tendrá el delta copy-on-write?", o: ["Un millón, uno por escritura", "200: la primera escritura de cada bloque le da sitio en el delta y las siguientes sobrescriben esa copia", "200, pero cada uno con todas sus versiones, para poder volver a cualquiera de ellas", "Tantos como tenga el disco base, porque el snapshot copia el disco entero al crearse"], a: 1, why: "En copy-on-write el delta no guarda historial: la primera escritura de un bloque le da sitio y las siguientes lo sobrescriben. Lo que hace crecer el delta es cuántos bloques distintos cambian (volatilidad), no cuántas escrituras hay.", src: "Clase (nota de prácticas, sec. 18) · T2 diap. 50" },
  { t: "discos", q: "Antes de aplicar un update inestable, congelas una MV encendida entera: todos sus discos, el contenido de su RAM y su configuración hardware. ¿Cómo se llama este tipo de snapshot? (una palabra)", s: ["checkpoint"], why: "Se puede congelar un solo dispositivo de almacenamiento o una MV completa con memoria y varios discos: esto último es un checkpoint. Al revertirlo, la RAM guardada se carga como RAM actual de la MV (diap. 56).", src: "T2 diaps. 49 y 55" },
  { t: "discos", q: "Partes de un disco sin snapshots y haces create PIT1, create PIT2 y create PIT3, escribiendo en el disco después de cada uno. ¿De qué volúmenes se compone ahora el estado actual?", o: ["Base + Δcurrent, porque cada create consolida el delta anterior en el base", "Base + Δsnap2 + Δsnap3 + Δcurrent", "Base + Δsnap2 + Δsnap3, que es el estado PIT3", "Δsnap3 + Δcurrent, porque solo se conservan los dos últimos deltas"], a: 1, why: "Cada create protege el volumen actual, lo marca con la etiqueta y crea un delta vacío encima, sin cambiar el estado: PIT1 = Base, PIT2 = Base + Δsnap2 y PIT3 = Base + Δsnap2 + Δsnap3. Lo escrito después de PIT3 está en Δcurrent, así que el estado actual los suma todos.", src: "Snap diap. 6" },
  { t: "discos", q: "PIT1 = Base, PIT2 = Base + Δsnap2, PIT3 = Base + Δsnap2 + Δsnap3, y el estado actual es Base + Δsnap2 + Δsnap3 + Δcurrent. Haces revert PIT2. ¿Qué ocurre? (Selecciona una o más)", o: ["Se elimina Δcurrent y el estado actual anterior se pierde", "PIT3 sigue existiendo y se puede volver a él", "Se crea un delta vacío para el estado actual, que cuelga de PIT2", "Δsnap3 se consolida con Δsnap2"], a: [0, 1, 2], why: "Revert siempre elimina el delta del estado actual (lo actual se pierde si no creas antes un snapshot) y crea un delta vacío respecto al estado elegido. Los demás snapshots no se tocan: PIT3 queda en otra rama y no se consolida nada.", src: "Snap diap. 7" },
  { t: "discos", q: "Base (PIT1) → Δsnap2 (PIT2) → Δsnap3 (PIT3), y el estado actual también cuelga de PIT2: Base + Δsnap2 + Δcurrent. ¿Qué afirmaciones son correctas? (Selecciona una o más)", o: ["delete PIT3: se elimina Δsnap3 sin más", "delete PIT1: se aplica Δsnap2 sobre el disco base, que pasa a ser PIT2", "delete PIT2: se integra Δsnap2 en Δsnap3; Δcurrent no se toca", "delete PIT2: se aplica Δsnap2 sobre el disco base"], a: [0, 1], why: "Caso 1, sin estados posteriores: delete PIT3 solo elimina Δsnap3; caso 2, sin estados anteriores: delete PIT1 aplica Δsnap2 sobre el base. Caso 3: delete PIT2 integra Δsnap2 en cada delta que depende de PIT2 (Δsnap3 y también Δcurrent); aplicarlo al base cambiaría PIT1.", src: "Snap diaps. 8–10" },
  { t: "discos", q: "De Base (PIT1) cuelgan dos ramas: Δsnap2 (PIT2) y el estado actual, Base + Δcurrent. ¿Se puede borrar PIT1?", o: ["Sí: se aplica Δsnap2 sobre el disco base, como al borrar el primer snapshot de una cadena", "Sí: se elimina el snapshot sin más, porque no tiene estados anteriores", "No: antes de una bifurcación tiene que existir un estado previo al que referenciar, y de PIT1 dependen PIT2 y el estado actual", "Sí, siempre que la MV esté apagada"], a: 2, why: "Antes de una bifurcación tiene que existir obligatoriamente un estado previo para referenciarlo, y eso limita el borrado de snapshots. Aplicar Δsnap2 sobre el base estropearía el estado actual, que es Base + Δcurrent y no lleva Δsnap2.", src: "Snap diap. 11" },
  { t: "discos", q: "Al eliminar un snapshot, el hipervisor incorpora un delta al delta siguiente o al disco base para no corromper los datos. ¿Cómo se llama esa operación? (una palabra)", s: ["consolidacion", "commit"], why: "«Consolidación: incorporación de un delta al siguiente o al base». Borrar un snapshot suele implicarla (si no, puede haber corrupción de datos) y tarda según la cantidad de información que haya que consolidar. El cuestionario del profesor la llama también commit.", src: "T2 diap. 56" },
  { t: "discos", q: "Base {0:A, 1:B, 2:C} → snap0 → Δ1 {1:X, 2:Y} → snap1 → Δ2 {2:Z} → snap2. Estás en snap2 y el delta actual está vacío. Haces delete all. ¿Qué contiene al final el disco base?", o: ["{0:A, 1:X, 2:Z}", "{0:A, 1:X, 2:Y}", "{0:A, 1:B, 2:Z}", "{0:∅, 1:X, 2:Z}"], a: 0, why: "Delete all sigue en el estado actual pero sin snapshots: los deltas en los que se basa el actual se escriben en el base en orden de creación, así que el bloque 2 se queda con su versión más reciente (Z). Con Y has aplicado los deltas al revés; con B te has saltado Δ1, y con ∅ has perdido los bloques que no estaban en ningún delta.", src: "T2 diap. 56" },
  { t: "discos", q: "El plan de continuidad de negocio (BCP) de una empresa necesita poder volver a un estado fiable de los datos de una aplicación en un instante concreto. ¿Con qué siglas llaman las diapositivas a ese estado?", s: ["pit", "pit (point in time)"], why: "PIT (Point in Time) es el estado de los datos de una aplicación en un momento puntual; es fundamental en el BCP (Business Continuity Plan) y se implementa con snapshots y con backups con integridad PIT.", src: "Snap diap. 3" },
  { t: "discos", q: "Un DBMS con caché write-back está volcando datos a disco cuando el hipervisor crea un snapshot sin avisar a nadie. ¿Qué riesgo tiene volver después a ese snapshot?", o: ["Ninguno: el snapshot copy-on-write conserva todos los bloques escritos hasta ese instante", "Que las estructuras de datos en disco estén corruptas: pudo escribirse un puntero antes que el dato al que apunta", "Que se pierdan los bloques no modificados, porque el delta solo guarda los modificados", "Que el revert sea muy lento, porque antes hay que consolidar la caché del DBMS"], a: 1, why: "Con cachés write-back, lo escrito puede estar a medias y un puntero puede llegar al disco antes que su dato: un snapshot hecho ahí es incoherente y volver a él deja las estructuras corruptas. Por eso los snapshots se crean en un estado quiescente.", src: "Snap diap. 12" },
  { t: "discos", q: "Completa: «Los snapshots se deben crear siempre en un estado ______». La aplicación se pausa donde sus estructuras en disco son coherentes, sin desconectar sesiones ni devolver errores a los clientes.", s: ["quiescente", "estado quiescente"], why: "«To quiesce» una aplicación es PAUSARLA en un estado en el que sus estructuras en disco son coherentes (integridad PIT): no se detiene, las sesiones no se desconectan y los clientes no reciben errores; solo se bloquean las operaciones hasta salir del estado quiescente.", src: "Snap diap. 12" },
  { t: "discos", q: "El hipervisor puede llevar por sí solo una aplicación a un estado quiescente antes de crear el snapshot, sin ayuda de la propia aplicación ni del SO guest.", o: ["Verdadero", "Falso"], a: 1, why: "Los hipervisores no pueden forzar a una aplicación a pausarse en un punto estable porque desconocen su funcionamiento. La quiescencia se integra en cada capa: lógica de negocio, DBMS (LOCK ALL TABLES, FLUSH ALL TABLES, QUIESCE) y SO (sync, fsfreeze).", src: "Snap diap. 13" },
  { t: "discos", q: "¿En qué orden se crea un snapshot con integridad PIT del disco de datos de una base de datos?", o: ["Quiesce de la BD → freeze del sistema de ficheros → create snapshot → unfreeze → unquiesce", "Freeze del sistema de ficheros → quiesce de la BD → create snapshot → unquiesce → unfreeze", "Create snapshot → quiesce de la BD → freeze del sistema de ficheros → unfreeze → unquiesce", "Freeze del sistema de ficheros → create snapshot → unfreeze; la BD no hace falta pausarla, porque fsfreeze ya vuelca todas las cachés"], a: 0, why: "Se va de arriba abajo: la BD pausa sus transacciones y vuelca su caché, y después fsfreeze vuelca la del SO y pausa las escrituras; se crea el snapshot y se deshace en orden inverso. fsfreeze no vuelca la caché propia del DBMS, y si congelas antes el sistema de ficheros, la BD ya no puede volcarla.", src: "Snap diap. 13" },
  { t: "discos", q: "Base thin {0, 2, 3, 5, 8, 10} → snap0 → Δ1 {2, 6} → snap1 → Δ2 {3, 6, 11} → snap2 → Δ3 {0, 11} → snap3. Estás en snap3 y el delta actual es Δ = {5}. Sin caché de disco y con metadatos que se leen en un acceso, ¿cuántos accesos al disco real necesita leer el bloque 10?", s: ["6", "seis"], why: "Cadena desde snap3: Δ → Δ3 → Δ2 → Δ1 → base, y el 10 solo está en la base thin: 5 lecturas de metadatos (Δ, Δ3, Δ2, Δ1 y base) + 1 del dato = 6. Si te sale 5, te has dejado la lectura del dato.", src: "Ejercicio de Snapshots (retroalimentación del profesor) · T2 diap. 50" },
  { t: "discos", q: "Base thin {1, 2, 4, 6, 7, 9} → snap0 → Δ1 {1, 3} → snap1 → Δ2 {4, 7} → snap2. Has hecho revert a snap1 y el delta actual es Δ = {2}. Sin caché de disco y con metadatos de un acceso, ¿cuántos accesos al disco real necesita leer el bloque 4?", s: ["4", "cuatro"], why: "Desde snap1 la cadena es Δ → Δ1 → base: Δ2 guarda lo escrito después de snap1, en otra rama, y no cuenta aunque tenga el 4. Metadatos de Δ, Δ1 y base (3) + dato (1) = 4.", src: "Ejercicio de Snapshots (retroalimentación del profesor) · T2 diap. 50" },
  { t: "discos", q: "Base thick (sin metadatos) → snap0 → Δ1 {3, 5} → snap1. Estás en snap1 y el delta actual es Δ = {0, 5}. Sin caché de disco y con metadatos de un acceso, ¿cuántos accesos al disco real necesita leer el bloque 7?", s: ["3", "tres"], why: "Metadatos de Δ y de Δ1 (2 accesos; el 7 no está) y la base thick se lee directamente, sin metadatos, en el offset LBA × tamaño de bloque (1 acceso): 3. Con base thin serían 4.", src: "Ejercicio de Snapshots (retroalimentación del profesor) · T2 diap. 50" },
  { t: "discos", q: "Base thin {0, 1, 3, 5, 6} → snap0 → Δ1 {2, 5} → snap1 → Δ2 {0, 3, 8} → snap2. Estás en snap2 y el delta actual es Δ = {1, 6}. Sin caché de disco y con metadatos de un acceso, ¿cuántos accesos al disco real necesita escribir el bloque 3?", s: ["3", "tres"], why: "Escribir nunca baja por la cadena: Δ2 y la base están congelados aunque tengan el 3. Metadatos de Δ (no está) + escribir el offset nuevo en sus metadatos + escribir el dato = 3.", src: "Ejercicio de Snapshots (retroalimentación del profesor) · T2 diap. 50" },
  { t: "discos", q: "Base thick (sin metadatos) → snap0 → Δ1 {2, 8} → snap1. Estás en snap1 y el delta actual es Δ = {4}. Escribes el bloque 8 y justo después lo lees. Sin caché de disco y con metadatos de un acceso, ¿cuántos accesos al disco real suman las dos operaciones?", s: ["5", "cinco"], why: "La escritura va al delta actual aunque el 8 esté en Δ1: metadatos de Δ (no está) + offset nuevo + dato = 3. Después el 8 ya está en Δ, así que leerlo cuesta metadatos + dato = 2; en total, 5.", src: "Ejercicio de Snapshots (retroalimentación del profesor) · T2 diap. 50" },
  { t: "discos", q: "Un prototipo de MV se «bloquea» para usarlo como máquina prefabricada, con un estado conocido, de la que se sacan los clones. ¿Cómo se denomina comercialmente? (una palabra)", s: ["plantilla", "template", "plantilla (template)"], why: "Los prototipos se bloquean para formar una biblioteca de máquinas prefabricadas con un estado conocido del que partir: comercialmente, plantilla («template»). Los linked-clones guardan solo sus cambios respecto a ella.", src: "T2 diap. 57" },
  { t: "discos", q: "Necesitas 10 MVs a partir de una plantilla que vas a seguir actualizando cada mes, sin romper las MVs ya creadas. ¿Qué te conviene?", o: ["Linked-clones, que se crean casi al instante y reciben las actualizaciones de la plantilla", "Full-clones: cada uno es una copia completa del disco y no depende de la plantilla", "Linked-clones, consolidando cada mes la plantilla nueva en el delta de cada clon", "Full-clones, porque ocupan menos disco que los linked-clones"], a: 1, why: "Un linked-clone guarda solo sus cambios respecto a la plantilla, así que la plantilla no se puede actualizar sin destruir los clones. El full-clone es una copia completa: ocupa más y tarda más en crearse, pero no depende de ella.", src: "T2 diaps. 58–59" },
  { t: "discos", q: "Un linked-clone hereda las desventajas de rendimiento de los snapshots, porque su disco es un snapshot del disco de la plantilla.", o: ["Verdadero", "Falso"], a: 0, why: "La lista de los linked-clones incluye las «desventajas de los snapshots»: al leer hay que consultar el índice de bloques del delta y al escribir, gestionar la asignación de espacio, así que el rendimiento baja.", src: "T2 diaps. 50, 58 y 59" },
  { t: "discos", q: "Según las diapositivas, en una infraestructura de escritorios virtuales con linked-clones, ¿qué pasa con la MV de un usuario cuando cierra su sesión?", o: ["Se consolida en la plantilla, para que la siguiente sesión conserve sus cambios", "Se convierte en full-clone, para independizarla de la plantilla", "Se destruye: en la siguiente sesión, el broker de MVs le da una recién clonada", "Se queda apagada y la reutiliza el siguiente usuario que abra sesión"], a: 2, why: "En los escritorios virtuales la vida de cada MV es breve: el clon se destruye cuando el usuario sale y en cada sesión se usa uno recién clonado, que un broker de MVs genera bajo demanda. Consolidar en la plantilla no se puede sin destruir los demás clones.", src: "T2 diap. 60" },

  // ---------- 07 redes
  { t: "red", q: "Cada NIC virtual…", o: ["Comparte la MAC del host", "Tiene su propia MAC única", "No tiene MAC", "Usa la MAC del switch"], a: 1, why: "Y el administrador elige a qué LAN virtual se conecta." },
  { t: "red", q: "¿Por qué se emulan NICs populares como Intel e1000?", o: ["Porque son más rápidas", "Para que el guest use un driver estándar", "Porque lo exige SCSI", "Por las VLAN"], a: 1, why: "Las NICs optimizadas (virtio, vmxnet) necesitan un driver especial." },
  { t: "red", q: "En modo bridged, las MVs…", o: ["Están aisladas", "Tienen visibilidad total de nivel 2 de la LAN externa", "Salen con la IP del host", "No tienen IP"], a: 1, why: "La NIC actúa como un puente Ethernet." },
  { t: "red", q: "En modo NAT, las MVs…", o: ["Tienen visibilidad de nivel 2", "Salen con la IP del host a través de un router NAT; desde fuera no se puede entrar sin redirigir puertos", "No tienen salida", "Son DomU"], a: 1, why: "Visibilidad a nivel IP con las limitaciones de NAT." },
  { t: "red", q: "Una LAN host-only…", o: ["Está asociada a la NIC real", "No está asociada a ninguna NIC real: aislada, para comunicar MVs", "Da salida a Internet", "Usa 802.1q"], a: 1, why: "En la P2, el bridge privado br1 es este caso." },
  { t: "red", q: "Un vSwitch sin ninguna NIC real…", o: ["No funciona", "Está aislado del exterior", "Usa NAT automáticamente", "Es un trunk"], a: 1, why: "Con más de una NIC se usan para balanceo o fail-over." },
  { t: "red", q: "¿Cómo multiplexa una NIC real varias VLANs?", o: ["Con una IP por VLAN", "En modo trunk 802.1q, con una etiqueta de VLAN en la cabecera de cada trama", "Con NAT", "No se puede"], a: 1, why: "El switch externo también debe soportar 802.1q." },
  { t: "red", q: "Entre dos MVs del mismo vSwitch, los paquetes…", o: ["Salen por la NIC real", "Se copian entre buffers de memoria del hipervisor (muy rápido)", "Pasan por el router", "Se cifran"], a: 1, why: "Hacia fuera se comparte la NIC real en modo promiscuo." },
  { t: "red", q: "¿Por qué la NIC real recibe en modo promiscuo?", o: ["Para cifrar", "Porque debe aceptar tramas dirigidas a las MACs de todas las MVs y entregarlas a la vNIC correspondiente", "Por las VLAN", "Para el DHCP"], a: 1, why: "Cada MV emite con su propia MAC." },
  // del profesor: cuestionario
  { t: "red", q: "¿En un virtualizador tipo 1, qué tipo de activos de red nos suele proporcionar el hipervisor?", o: ["todo tipo de activos de red: hubs, bridges, routers, pasarelas, etc.", "switches virtuales únicamente", "switches y routers virtuales", "ninguno, hay que construirlos con máquinas virtuales"], a: 1, why: "T2, diap. 64 (LANs virtuales en native): el hipervisor emula uno o más switches virtuales Ethernet, con VLANs (grupos de puertos con tag 802.1q). Routers, no: se construyen con MVs.", src: "Cuestionario, pregunta 13 · T2 diap. 64", prof: true },
  { t: "red", q: "La implementación de switches virtuales con funcionalidad bridge para conectar MVs con el exterior requiere:", o: ["que los NIC reales soporten la funcionalidad de VLAN", "que los NIC reales estén en modo promiscuo", "que los NIC reales estén paravirtualizados", "que los NIC reales realicen traducción NAT"], a: 1, why: "T2, diap. 65: «Cada MV usa su propia MAC para emitir. La recepción se hace en modo promiscuo». La NIC real tiene que aceptar tramas dirigidas a MACs que no son la suya, las de las MVs. El NAT es otra forma de conectar (la de los hosted), no un requisito del bridge.", src: "Cuestionario, pregunta 14 · T2 diap. 65", prof: true },
  { t: "red", q: "¿En un virtualizador tipo 1, qué tipo de elementos enrutadores de red (routers) nos suele proporcionar el hipervisor?", o: ["no es necesario, ya que generalmente hay disponible una preconfiguración con NAT", "ninguno, hay que construirlos añadiendo una capa 3 a los switches virtuales", "ninguno, hay que construirlos con máquinas virtuales", "routers estándar, junto otro tipo de activos de red: hubs, bridges, pasarelas, etc."], a: 2, why: "En los dibujos de las LANs virtuales en native, el «NAT router» es una MV conectada a un vSwitch. La a es del hosted: VirtualBox o VMware Workstation traen los modos bridged, NAT y host-only. Hosted = bridged / NAT / host-only; native = solo vSwitches y VLANs, y los routers son MVs.", src: "Cuestionario, pregunta 26 · T2 diaps. 63 y 66–69", prof: true },
  // nuevas
  { t: "red", q: "Instalas en una MV un SO antiguo al que no puedes añadir drivers. ¿Qué NIC virtual le configuras para que tenga red?", o: ["Una NIC optimizada para alto rendimiento, como vmnetIII", "Ninguna: el hipervisor le ofrece sockets, como hace un SO con sus procesos", "La NIC real del servidor, con la misma MAC para todas las MVs", "Una NIC que emule una tarjeta muy popular, como Intel e1000 o PCnet"], a: 3, why: "El hipervisor emula la interfaz física (registros de control y estado) de NICs muy populares, como Intel e1000 o PCnet, para que el guest use un driver estándar, que un SO antiguo ya trae. Las optimizadas para alto rendimiento (vmnetII, vmnetIII) requieren un driver especial, y cada NIC virtual tiene su propia MAC única. Además, el hipervisor ofrece hardware virtual (NIC → NIC virtual), no sockets: eso es lo que da un SO a sus procesos (T1 diap. 13).", src: "T2 diap. 62; T1 diap. 13" },
  { t: "red", q: "En VirtualBox tienes tres MVs: A debe verse en tu LAN como un equipo más; B solo tiene que salir a Internet, sin ser visible en la LAN; C solo debe hablar con otras MVs, aislada del exterior. ¿Qué modo de red le das a cada una?", o: ["A: NAT · B: bridged · C: host-only", "A: bridged · B: host-only · C: NAT", "A: host-only · B: NAT · C: bridged", "A: bridged · B: NAT · C: host-only"], a: 3, why: "Bridged: la NIC hace de bridge Ethernet (nivel 2) entre la LAN virtual y la externa, así que la MV tiene visibilidad total a nivel 2 y es un equipo más. NAT: se interpone un router IP con NAT que usa como dirección externa la IP del host, así que la MV sale, pero oculta tras esa IP. Host-Only: la LAN no se asocia a ninguna NIC, queda aislada del exterior y sirve para comunicar MVs.", src: "T2 diap. 63" },
  { t: "red", q: "Una MV de VirtualBox en modo NAT tiene, igual que una en bridged, visibilidad total a nivel 2 de la LAN externa.", o: ["Verdadero", "Falso"], a: 1, why: "Eso solo pasa en bridged, donde la NIC hace de bridge Ethernet de nivel 2. En NAT se interpone un router IP con NAT que usa como dirección externa la IP del host, así que la MV ve la LAN externa solo a nivel IP y con las limitaciones propias del NAT.", src: "T2 diap. 63" },
  { t: "red", q: "En un hipervisor hosted, ¿de qué tres formas puede asociarse cada LAN virtual a una NIC real del host? (Escribe los nombres de las diapositivas, en su orden y separados por punto y coma.)", s: ["bridged; nat; host-only", "bridged; nat; host only", "bridged; nat; hostonly"], why: "Diap. 63: Bridged (la NIC hace de bridge Ethernet de nivel 2 entre la LAN virtual y la externa), NAT (un router IP con NAT que usa como dirección externa la IP del host) y Host-Only (la LAN no se asocia a ninguna NIC: queda aislada y sirve para comunicar MVs). En un native no se eligen estos modos: el hipervisor emula vSwitches con VLANs (diap. 64), y para hacer NAT hay que montar un router con una MV (diap. 69 y P26 del cuestionario del profesor).", src: "T2 diap. 63" },
  { t: "red", q: "En un hipervisor tipo 1 (native), ¿qué elementos de red emula el propio hipervisor?", o: ["Un modo NAT ya preparado para dar salida a las MVs, como en VirtualBox", "Una o más NICs virtuales en cada MV, cada una con su propia MAC", "Routers virtuales para encaminar el tráfico entre VLANs", "Switches virtuales Ethernet (vSwitches), con sus VLANs"], a: [1, 3], why: "Virtualizar la red requiere emular una o más NICs en cada MV, cada una con su propia MAC (diaps. 61–62), y, en native, uno o más switches virtuales Ethernet con sus VLANs (diap. 64). El modo NAT ya preparado es de los hosted (diap. 63). Que no emule routers no lo dicen las diapositivas con esas palabras: lo fija el cuestionario del profesor (P13: «switches virtuales únicamente»; P26: los routers hay que construirlos con MVs). Ojo: la P13 pregunta por «activos de red», y una NIC virtual no es un activo de red, pero el hipervisor también la emula.", src: "T2 diaps. 61, 62 y 64; cuestionario del profesor, P13 y P26" },
  { t: "red", q: "En un hipervisor native, un vSwitch tiene asociadas dos NICs reales, conectadas a un switch externo. ¿Qué afirmaciones son correctas?", o: ["Cada una aparenta un enlace Ethernet punto a punto entre el vSwitch y el switch externo", "Cada NIC real se asigna a una sola MV, que emite con la MAC de esa NIC", "Se pueden usar a la vez con una política de balanceo de carga", "Se pueden usar con una política de fail-over: si una falla, el tráfico sigue por la otra"], a: [0, 2, 3], why: "Diap. 64: si un vSwitch tiene más de una NIC real, se pueden usar simultáneamente con políticas de balanceo de carga o de fail-over, y cada NIC real aparenta un enlace Ethernet punto a punto entre el switch virtual y un switch externo. Las NICs reales no se reparten entre MVs: se comparten, y cada MV emite con su propia MAC (diap. 65).", src: "T2 diaps. 64 y 65" },
  { t: "red", q: "En un hipervisor native, dentro de cada vSwitch se definen una o más VLANs, y a cada una se le asocia un tag 802.1q. ¿Qué otro nombre reciben esas VLANs en las diapositivas? (Escribe solo el término.)", s: ["grupos de puertos", "grupo de puertos", "port groups", "port group"], why: "Diap. 64: «Dentro de cada vSwitch se definen 1 o más VLANs (grupos de puertos)» y «A cada grupo de puertos se le asocia un tag de VLAN 802.1q». Una MV puede conectar varias NICs virtuales a grupos de puertos distintos. En el ejemplo de servidor son el Grupo 1 (VLAN 101), el 2 (102), el 3 (103), el Aislado (104) y el NAT (105) (diap. 66).", src: "T2 diaps. 64 y 66" },
  { t: "red", q: "En un hipervisor native, una MV tiene que estar a la vez en la VLAN 102 y en la VLAN 103. ¿Cómo se configura?", o: ["No se puede: cada MV pertenece a una sola VLAN", "Con dos NICs virtuales, cada una conectada a un grupo de puertos distinto", "Con una sola NIC virtual que tenga dos MACs, una por VLAN", "Con un router del vSwitch que una las dos VLANs"], a: 1, why: "Diap. 64: una MV puede tener una o más NICs virtuales conectadas a distintos grupos de puertos. Es lo que hace la segunda MV del ejemplo de servidor: vNIC0 en el Grupo 2 (VLAN 102) y vNIC1 en el Grupo 3 (VLAN 103) (diap. 66). Cada NIC virtual tiene una sola MAC, la suya (diap. 62), y un vSwitch conmuta tramas, no enruta.", src: "T2 diaps. 64 y 66" },
  { t: "red", q: "Una NIC real de un servidor native lleva al exterior las VLAN 102 y 103 de un vSwitch. ¿Qué tiene que cumplir el puerto del switch externo al que se conecta?", o: ["Estar también en modo promiscuo", "Hacer NAT con la IP del servidor", "Nada: los tags de VLAN se quitan antes de salir por la NIC real", "Soportar también la multiplexación IEEE 802.1q"], a: 3, why: "Diap. 64: las NICs reales multiplexan el enlace en modo trunk 802.1q, con el tag de la VLAN en la cabecera de cada paquete, y los switches externos deben soportar también la multiplexación IEEE 802.1q en los puertos donde se conectan. Es la NIC2 del ejemplo de servidor, que lleva VLANs={102,103} (diap. 66). El modo promiscuo es de la NIC real del servidor, para recibir las tramas dirigidas a las MACs de las MVs (diap. 65).", src: "T2 diaps. 64 y 66" },
  { t: "red", q: "Dos MVs conectadas al mismo grupo de puertos de un vSwitch se pasan las tramas a velocidad de acceso a memoria, aunque la NIC real de ese vSwitch sea de solo 100 Mb/s.", o: ["Verdadero", "Falso"], a: 0, why: "Diap. 65: el paso de paquetes Ethernet entre NICs de MVs conectadas al mismo switch virtual se hace mediante buffers de memoria del hipervisor, a velocidad de acceso a memoria. La NIC real solo interviene en las comunicaciones con el switch exterior.", src: "T2 diap. 65" },
  { t: "red", q: "En un hipervisor native, como todas las MVs de un vSwitch comparten su NIC real, todas emiten hacia el switch exterior con la MAC de esa NIC.", o: ["Verdadero", "Falso"], a: 1, why: "Diap. 65: comparten la NIC exterior, pero cada MV usa su propia MAC para emitir; por eso la NIC real recibe en modo promiscuo y entrega cada paquete a la NIC virtual con la MAC correspondiente. Salir con la dirección del host es lo que hace el NAT de los hosted, y a nivel IP (diap. 63).", src: "T2 diap. 65" },
  { t: "red", q: "En un servidor native se desactiva el modo promiscuo de la NIC real que une un vSwitch con el switch exterior. ¿Qué ocurre?", o: ["Las MVs siguen emitiendo, pero no les llegan las tramas del exterior dirigidas a sus MACs", "Nada: el modo promiscuo solo hace falta para multiplexar VLANs en modo trunk", "Las MVs dejan de poder emitir, porque cada una emite con su propia MAC", "Las MVs pasan a recibir con la MAC de la NIC real, como en NAT"], a: 0, why: "Diap. 65: cada MV emite con su propia MAC y la recepción se hace en modo promiscuo, para entregar cada paquete a la NIC virtual con la MAC correspondiente. Qué pasa al desactivarlo no está en las diapositivas, pero se deduce: sin modo promiscuo, la NIC real solo acepta las tramas dirigidas a su propia MAC (y las de difusión), así que descarta las que van a las MACs de las MVs; emitir no depende de él. El trunk 802.1q es otra cosa: multiplexa VLANs (diap. 64). Es la idea de la P14 del cuestionario del profesor.", src: "T2 diap. 65; cuestionario del profesor, P14" },
  { t: "red", q: "Pasas de VirtualBox a un hipervisor tipo 1 (p. ej., VMware ESXi) y quieres que un grupo de MVs salga a Internet por NAT, como antes. ¿Qué haces?", o: ["Seleccionar el modo NAT en la NIC virtual de cada MV", "Poner la NIC real en modo promiscuo para que las MVs salgan con la IP del servidor", "Conectar las MVs a un vSwitch sin NIC real y poner una MV que haga de router NAT entre ese vSwitch y otro con NIC real", "Conectar las MVs a un vSwitch sin NIC real y dejar que el hipervisor haga NAT con la IP del servidor"], a: 2, why: "En native, el hipervisor emula switches virtuales (diap. 64) y, según el cuestionario del profesor, solo eso: «switches virtuales únicamente» (P13); los routers, también el de NAT, hay que construirlos con MVs (P26). El modo NAT ya preparado es de los hosted (diap. 63). Es el montaje del ejemplo de servidor: el Grupo NAT está en un vSwitch sin NIC real y su tráfico pasa por un router NAT antes de salir por NIC2 (diaps. 66 y 69).", src: "T2 diaps. 64 y 69; cuestionario del profesor, P13 y P26" },
  { t: "red", q: "En el ejemplo de «LANs virtuales en servidores», una MV tiene vNIC0 en el Grupo 1 (VLAN 101, vSwitch1 → NIC1) y vNIC1 en el Grupo 2 (VLAN 102, vSwitch2 → NIC2). ¿Qué afirmaciones son correctas?", o: ["Su tráfico público hacia el exterior sale por vNIC0, vSwitch1 y NIC1", "Sus dos NICs virtuales comparten la misma MAC, porque son de la misma MV", "Con la otra MV del Grupo 2 del ejemplo se comunica sin que sus tramas pasen por ninguna NIC real", "Con la otra MV del Grupo 2 del ejemplo solo puede comunicarse a través del router NAT"], a: [0, 2], why: "Diap. 67 («Tráfico público hacia el exterior»): baja por vNIC0, el Grupo 1, vSwitch1 y NIC1 hasta el switch externo y el router. Diap. 68 («Tráfico entre servidores locales»): con la otra MV del Grupo 2 habla dentro de vSwitch2, por buffers de memoria del hipervisor (diap. 65), sin NICs reales ni routers. Y cada NIC virtual tiene su propia MAC única (diap. 62).", src: "T2 diaps. 67 y 68" },
  { t: "red", q: "En el ejemplo de «LANs virtuales en servidores», dos MVs tienen su única NIC virtual (vNIC0) en el Grupo Aislado (VLAN 104), cuyo vSwitch no tiene ninguna NIC real. ¿Qué pueden hacer?", o: ["Nada: un vSwitch sin NIC real no puede pasar tramas entre sus MVs", "Hablar entre sí y salir al exterior por NIC2, que se comparte", "Hablar entre sí, por memoria del hipervisor, pero no salir al exterior", "Hablar entre sí, pero solo a través del router NAT"], a: 2, why: "Un vSwitch con 0 NICs reales está aislado del exterior (diap. 64), no de sus propias MVs: es el «tráfico entre servidores locales» de la diap. 68, que pasa por buffers de memoria del hipervisor (diap. 65).", src: "T2 diaps. 64 y 68" },
  { t: "red", q: "En el ejemplo de «LANs virtuales en servidores», el vSwitch del Grupo NAT (VLAN 105) no tiene ninguna NIC real. ¿Cómo sale al exterior el tráfico público de su MV?", o: ["Por ese vSwitch, que hace la traducción NAT, y luego por NIC1", "Por ese vSwitch, un router NAT construido con una MV, NIC2, el switch externo y el router", "Directamente por NIC2 en modo bridged, con la IP propia de la MV", "No sale: el Grupo NAT está aislado del exterior, como el Grupo Aislado"], a: 1, why: "Diap. 69 («Tráfico público NAT»): el tráfico de esa MV baja por el Grupo NAT y su vSwitch, pasa por el router NAT del servidor y sale por NIC2 hacia el switch externo y el router. En el dibujo es un icono de router; que sea una MV lo fija el cuestionario del profesor: el hipervisor native solo da switches virtuales (P13) y los routers hay que construirlos con MVs (P26).", src: "T2 diap. 69; cuestionario del profesor, P13 y P26" },
  { t: "red", q: "El driver e1000 de un guest escribe en un registro de control de su NIC virtual. ¿Qué ocurre?", o: ["La escritura llega tal cual al registro de la NIC real del servidor", "El acceso al hardware se intercepta y el software del hipervisor emula su efecto en la NIC virtual", "VT-x emula por hardware la tarjeta e1000, sin que intervenga el software del hipervisor", "El guest recibe una excepción de instrucción ilegal: una MV no puede acceder a registros de E/S"], a: 1, why: "Diap. 70: la emulación de una arquitectura requiere un mecanismo para interceptar los accesos al hardware (instrucciones privilegiadas) y un sistema software que emule todos los recursos virtuales; el hardware de virtualización solo ayuda a mejorar el rendimiento interceptando instrucciones privilegiadas. La e1000 de la MV es la emulación de los registros de control y estado de esa tarjeta (diap. 62), y el acceso lo resuelve el hipervisor sin que el guest vea ningún error.", src: "T2 diaps. 62 y 70" },
  { t: "red", q: "Dos MVs iguales en un servidor con VT-x: una con NIC e1000 y otra con una NIC optimizada (vmnetIII) y su driver especial. Según el resumen del tema, ¿qué cabe esperar del rendimiento de red?", o: ["El mismo, porque VT-x intercepta igual las instrucciones privilegiadas de las dos", "Mejor en la e1000, porque el guest usa un driver estándar que ya trae", "Puede ser mejor en la vmnetIII: depende de cómo se implemente y optimice cada periférico", "El mismo, porque con VT-x la red ya no se emula por software, sino por hardware"], a: 2, why: "Diap. 70: el hardware de virtualización solo ayuda interceptando instrucciones privilegiadas; el rendimiento del hardware virtual depende de la implementación concreta de cada periférico y de las optimizaciones aplicadas. Las NICs como vmnetIII están optimizadas para alto rendimiento a cambio de un driver especial (diap. 62).", src: "T2 diaps. 62 y 70" },

  // ---------- 08 virtualización en Intel x86
  // del profesor: cuestionario
  { t: "x86", q: "Dos de las instrucciones que hacen que la arquitectura Intel IA32 no sea estrictamente virtualizable son PUSHF/POPF que introducen/extraen una palabra de estado en la pila de programa, respectivamente. En terminología de Popek y Goldberg, dichas instrucciones se clasifican como:", o: ["Behaviour sensitive", "Control sensitive", "Volatile", "Insensitive"], a: 0, why: "Behaviour sensitive: su comportamiento depende del modo. POPF en el anillo 3 solo escribe los flags aritméticos (no puede enmascarar las interrupciones, IF) y PUSHF lee unos EFLAGS incompletos, pero ninguna provoca trap: son sensibles no privilegiadas y por eso el IA-32 no cumple el teorema 1. Control sensitive son las que cambian la configuración de recursos. Truco: Control = cambia; Behaviour = depende.", src: "Cuestionario, pregunta 7 · T1 diap. 17 y T3 diap. 12", prof: true },
  { t: "x86", q: "Empareja los siguientes términos en relación a los niveles de privilegio (anillos) en la familia de CPUs Intel x86 con soporte de virtualización: «Aplicaciones de usuario del guest»", o: ["Ring 3", "Ring 2", "Ring 1", "Ring 0", "Ring -1", "Ring -2"], a: 0, why: "Las aplicaciones de usuario, del guest o del host, corren en el anillo 3, el de menos privilegio.", src: "Cuestionario, pregunta 16 · T3 diaps. 6, 8 y 13–14", prof: true },
  { t: "x86", q: "Empareja los siguientes términos en relación a los niveles de privilegio (anillos) en la familia de CPUs Intel x86 con soporte de virtualización: «Sistema operativo host»", o: ["Ring 3", "Ring 2", "Ring 1", "Ring 0", "Ring -1", "Ring -2"], a: 3, why: "El SO host corre en el anillo 0 (modo kernel). Los anillos 1 y 2 existen en modo protegido pero no se usan.", src: "Cuestionario, pregunta 16 · T3 diaps. 6, 8 y 13–14", prof: true },
  { t: "x86", q: "Empareja los siguientes términos en relación a los niveles de privilegio (anillos) en la familia de CPUs Intel x86 con soporte de virtualización: «Hipervisor»", o: ["Ring 3", "Ring 2", "Ring 1", "Ring 0", "Ring -1", "Ring -2"], a: 4, why: "Con VT-x el hipervisor corre en modo VMX root y el guest en VMX non-root, cada uno con su anillo 0: el hipervisor queda por debajo del ring 0 del guest, y el dibujo de T3, diap. 14, lo llama ring −1.", src: "Cuestionario, pregunta 16 · T3 diaps. 6, 8 y 13–14", prof: true },
  { t: "x86", q: "Empareja los siguientes términos en relación a los niveles de privilegio (anillos) en la familia de CPUs Intel x86 con soporte de virtualización: «System Management Mode (SMM)»", o: ["Ring 3", "Ring 2", "Ring 1", "Ring 0", "Ring -1", "Ring -2"], a: 5, why: "El SMM es «conocido como anillo −2: máximo nivel de privilegio»: firmware de la placa en SMRAM, al que se entra con la interrupción SMI# y del que se sale con RSM.", src: "Cuestionario, pregunta 16 · T3 diaps. 6, 8 y 13–14", prof: true },
  { t: "x86", q: "¿En qué modo de funcionamiento (real mode, virtual 8086 mode, ...) de un microprocesador moderno compatible x86 estará disponible el soporte VT-x de virtualización?", s: ["long mode", "modo largo"], why: "T3, diap. 15: «VMXON/VMXOFF: instrucciones para activar/desactivar el modo Root desde long mode». La pregunta pone los modos en inglés, así que contesta long mode. Si no te la dieran por buena, la otra candidata es protected mode (en el hardware real VT-x exige modo protegido).", src: "Cuestionario, pregunta 27 · T3 diap. 15", prof: true },
  // nuevas
  { t: "x86", q: "Según el tema, ¿qué ocurre en los años 90 que impulsa el resurgir de la virtualización?", o: ["El x86 se convierte en una arquitectura predominante y los «commodity OSs» carecen de prestaciones empresariales", "Intel y AMD incorporan soporte hardware de virtualización en sus CPUs", "IBM presenta VM/370, capaz de ejecutar incluso una MV dentro de otra MV", "Intel añade el bit CR4.UMIP para que SGDT, SIDT, SLDT y SMSW sean privilegiadas"], a: 0, why: "Es lo que la diapositiva sitúa en los años 90, justo antes de que VMware fuera pionera en virtualizar x86 (~1999). Las demás opciones son otras fechas de la misma historia: VM/370 es de 1972, el soporte HW de Intel y AMD de ~2006 y UMIP de 2018.", src: "T3 diap. 2" },
  { t: "x86", q: "Selecciona las afirmaciones correctas sobre los modos de ejecución de IA-32:", o: ["Tras el arranque o un RESET, el procesador siempre comienza en modo real", "En modo virtual 8086, el software del 8086 corre como un proceso del anillo 0 del modo protegido", "El modo protegido es el modo de funcionamiento normal; de sus 4 anillos, el 1 y el 2 no se utilizan", "El modo virtual 8086 lo activa el kernel en el cambio de contexto, poniendo a 1 el bit VM de EFLAGS"], a: [0, 2, 3], why: "Las tres ciertas salen casi literales de las diaps. 5–7: el procesador arranca siempre en modo real; el protegido es el modo normal y sus anillos 1 y 2 «no se utilizan»; y el virtual 8086 lo activa el kernel en el cambio de contexto con el bit VM de EFLAGS (nada que ver con VMX/VT-x). La falsa: ese software corre como proceso de anillo 3, no de anillo 0. Que el dibujo de trap & emulate (diap. 14) meta al guest en el anillo 1 no cambia lo que dice la diap. 6 de un SO normal.", src: "T3 diaps. 5–7" },
  { t: "x86", q: "Desde cualquier modo, una interrupción no enmascarable SMI#, disparada por eventos del hardware, hace que el procesador ejecute una rutina de firmware del fabricante de la placa base situada en SMRAM. ¿Con qué número de anillo se conoce ese modo?", s: ["-2", "−2", "anillo -2", "anillo −2", "anillo-2", "ring -2", "ring −2", "ring-2", "anillo - 2", "menos 2", "anillo menos 2"], why: "Es el System Management Mode (SMM), conocido como anillo -2: el máximo nivel de privilegio, por encima del hipervisor con VT-x (anillo -1) y del kernel (anillo 0). Trampa: el -1 es el hipervisor, no el SMM.", src: "T3 diap. 8" },
  { t: "x86", q: "¿Con qué instrucción especial sale el procesador del System Management Mode (SMM)?", s: ["rsm", "rsm (resume from smm)", "resume from smm", "resume from system management mode", "rsm (resume from system management mode)"], why: "RSM = Resume from SMM. Al SMM se entra por la interrupción SMI# (no con una instrucción) y se sale con RSM; no confundir con VMXOFF, que desactiva el modo Root de VT-x.", src: "T3 diap. 8" },
  { t: "x86", q: "Un SO de 64 bits tiene que ejecutar una aplicación antigua de IA-32 sin recompilarla. ¿En qué modo del procesador correrá esa aplicación?", o: ["En modo virtual 8086", "En modo 64-bit (submodo del modo long)", "En modo real", "En modo compatibilidad (submodo del modo long)"], a: 3, why: "El modo compatibilidad hace con las apps de IA-32 en un SO de 64 bits lo que el virtual 8086 hacía con el software del 8086 en IA-32: las ejecuta sin recompilar (y solo ven 4 GB). Trampa: el virtual 8086 es un modo de IA-32, no del modo long.", src: "T3 diap. 9" },
  { t: "x86", q: "El modo long del x86-64 tiene dos submodos. ¿Cuáles son? (en el orden de la diapositiva, separados por «;»)", s: ["modo 64-bit; modo compatibilidad", "64-bit; compatibilidad", "modo 64 bits; modo compatibilidad", "64 bits; compatibilidad", "modo 64-bit; modo de compatibilidad", "modo de 64 bits; modo de compatibilidad", "64-bit; modo compatibilidad", "modo 64-bit; compatibilidad", "modo 64 bits; compatibilidad", "64 bits; modo compatibilidad", "64 bit; compatibilidad", "modo 64 bit; modo compatibilidad", "modo 64-bits; modo compatibilidad", "64-bit; modo de compatibilidad", "64-bit mode; compatibility mode", "64-bit; compatibility"], why: "Modo 64-bit (SSOO y apps de 64 bits, registros de 64 bits, direccionamiento relativo al PC) y modo compatibilidad (apps de IA-32 en un SO de 64 bits, sin recompilar). Es el mismo long mode desde el que VMXON activa el modo Root.", src: "T3 diap. 9" },
  { t: "x86", q: "Según el estudio de Robin e Irvine (USENIX'00) que cita el tema, ¿cuántas instrucciones problemáticas impiden virtualizar el x86 en sentido clásico? (escribe el número)", s: ["18", "dieciocho"], why: "Son 18 instrucciones sensitive que no dan trap sin privilegio o que dejan a la MV «fisgonear» en el hipervisor: SGDT, SIDT, SLDT, SMSW, PUSHF(D), POPF(D), LAR, LSL, VERR, VERW, POP, PUSH, CALL, JMP, INT, RET, STR y MOVE. Por ellas el x86 no cumple el teorema 1 de Popek y Goldberg.", src: "T3 diap. 10" },
  { t: "x86", q: "Con la estrategia híbrida de VMware para el x86 sin soporte HW, un proceso de usuario del guest ejecuta un bucle de sumas y después hace una llamada al sistema. ¿Cómo se ejecuta cada parte?", o: ["Todo con traducción binaria just-in-time, tanto el bucle como el código del kernel del guest", "El bucle, con traducción binaria; el código del kernel del guest, con trap & emulate", "El bucle, directamente en la CPU real (trap & emulate); el código del kernel del guest, con traducción binaria just-in-time", "El bucle, en modo VMX Non-Root; el código del kernel del guest, en modo VMX Root"], a: 2, why: "La traducción binaria solo entra cuando el guest pasa a modo kernel (del anillo 3 al 0); en modo usuario basta con trap & emulate, y unas sumas se ejecutan tal cual, sin trap. Es la patente de VMware (1998-2002), anterior al soporte HW (~2006), así que no puede usar los modos VMX.", src: "T3 diap. 10; T2 diap. 26" },
  { t: "x86", q: "Se intenta virtualizar un x86 sin soporte HW (ni VT-x ni UMIP) mediante trap & emulate puro, con el SO guest deprivilegiado. Para saber en qué modo está, el guest ejecuta SMSW. ¿Qué ocurre?", o: ["Se produce un trap y el hipervisor le devuelve el CR0 de su CPU virtual", "No hay trap: SMSW guarda en memoria el CR0 real, y el guest ve, por ejemplo, el modo protegido del hipervisor (CR0.PE)", "No hay trap: SMSW guarda en memoria unos EFLAGS incompletos", "Se produce un VM exit incondicional hacia el modo Root"], a: 1, why: "SMSW (Store Machine Status Word) es behavior sensitive no privilegiada: guarda CR0 en memoria sin dar trap, así que la MV lee un dato erróneo, el del hipervisor. El trap de la primera opción es lo que permitiría CR4.UMIP = 1; los EFLAGS incompletos son cosa de PUSHF, y sin soporte HW no hay VM exits.", src: "T3 diap. 11" },
  { t: "x86", q: "En 2018, con la microarquitectura Cannon Lake, se introdujo una característica de seguridad que permite marcar SGDT, SLDT, SIDT y SMSW como privilegiadas. ¿Qué bit de CR4 hay que poner a 1? (escribe su nombre)", s: ["umip", "cr4.umip", "user-mode instruction prevention", "user mode instruction prevention", "umip (user-mode instruction prevention)", "user-mode instruction prevention (umip)", "cr4.umip (user-mode instruction prevention)", "cr4.umip = 1", "cr4.umip=1", "umip = 1", "umip=1"], why: "CR4.UMIP = 1 (User-Mode Instruction Prevention) convierte esas instrucciones behavior sensitive en privilegiadas, es decir, en instrucciones que dan trap en modo usuario. Trampa: el bit está en CR4, no en CR0, que es el registro que lee SMSW.", src: "T3 diap. 11" },
  { t: "x86", q: "Si se activa CR4.UMIP = 1 (Cannon Lake, 2018), PUSHF y POPF pasan a ser instrucciones privilegiadas.", o: ["Verdadero", "Falso"], a: 1, why: "Según el tema, UMIP solo marca como privilegiadas SGDT, SLDT, SIDT y SMSW (diap. 11); PUSHF y POPF siguen siendo behavior sensitive no privilegiadas (diap. 12). Trampa: las seis están entre las 18 problemáticas, pero UMIP solo se aplica a esas cuatro.", src: "T3 diaps. 11–12" },
  { t: "x86", q: "Sin soporte HW, el SO guest entra en su modo kernel virtual, pero sigue en el anillo 3. Ejecuta POPF para poner IF = 0 y enmascarar las interrupciones. ¿Qué ocurre?", o: ["POPF provoca un trap por falta de privilegio y el hipervisor emula el cambio de IF", "Se enmascaran las interrupciones de toda la máquina física", "POPF solo escribe los arithmetic flags: IF no cambia, no hay trap y el hipervisor no se entera", "POPF provoca un VM exit condicional, según la bitmask de los VM-execution control fields"], a: 2, why: "POPF es behavior sensitive no privilegiada: en el anillo 3 solo escribe los arithmetic flags e ignora en silencio IF, que es un system flag. Si diera trap (primera opción), el hipervisor podría emularla, que es justo lo que exige el teorema 1 de Popek y Goldberg.", src: "T3 diap. 12" },
  { t: "x86", q: "Selecciona lo que es cierto del modo VMX Non-Root de Intel VT-x:", o: ["Es el modo en el que debe correr el hipervisor para tener el control de todos los recursos", "Todas las instrucciones se comportan igual que en la arquitectura tradicional, para que el software legacy funcione", "Se rediseñan todas las instrucciones sensitive: o provocan trap o tienen la semántica correcta", "El SO guest debe ejecutarse en este modo, en su anillo 0, y así se puede virtualizar con trap & emulate clásico"], a: [2, 3], why: "Non-Root es el modo del guest: allí corre en su anillo 0 porque sus instrucciones sensitive están rediseñadas para permitir el trap & emulate clásico. Root es el del hipervisor (también en su anillo 0) y del software legacy, donde todo se comporta como en el x86 tradicional.", src: "T3 diap. 13" },
  { t: "x86", q: "Con Intel VT-x, el SO guest se sigue deprivilegiando a un anillo 1 o 3 para que sus instrucciones sensitive provoquen trap.", o: ["Verdadero", "Falso"], a: 1, why: "Con VT-x el guest corre en su anillo 0 del modo Non-Root, donde las sensitive ya están rediseñadas (trap o semántica correcta), y el VMM pasa al modo Root, el «Ring -1» del dibujo. Bajar al guest al anillo 1 era el modelo trap & emulate sin soporte HW. Matiz: el guest sigue teniendo menos privilegio que el hipervisor (el «modo pseudoprivilegiado» de T2, diap. 27), pero no porque baje de anillo.", src: "T3 diaps. 13–14; T2 diap. 27" },
  { t: "x86", q: "Según los dibujos de anillos del tema (SO tradicional, modelo trap & emulate y con soporte HW), selecciona las afirmaciones correctas:", o: ["Con soporte HW, el VMM se ejecuta en el anillo -2 del modo Root", "En el modelo trap & emulate sin soporte HW, el SO guest se ejecuta en el anillo 1 y el VMM en el anillo 0", "Con soporte HW, la llamada al sistema de una aplicación del guest entra primero en el VMM, igual que en el modelo trap & emulate", "Con soporte HW, el SO guest se ejecuta en el anillo 0 del modo Non-Root"], a: [1, 3], why: "Sin HW, el guest se deprivilegia al anillo 1 y el VMM ocupa el 0; con VT-x, el guest vuelve a su anillo 0 (Non-Root) y el VMM queda debajo, en el «Ring -1» del modo Root (el -2 es el SMM). En el dibujo con soporte HW, la llamada al sistema va directa al vector de interrupciones del guest; en el de trap & emulate, en cambio, entra primero en el del VMM, que se la pasa al guest.", src: "T3 diap. 14" },
  { t: "x86", q: "Las instrucciones VMXON y VMXOFF de las Virtual Machine Extensions (VMX) de Intel VT sirven para...", o: ["lanzar una MV por primera vez y reanudarla tras un VM exit", "pasar de modo Root a Non-Root (VM Entry) y de Non-Root a Root (VM Exit)", "entrar en el System Management Mode y salir de él", "activar y desactivar el modo Root, desde long mode"], a: 3, why: "VMXON/VMXOFF activan y desactivan el modo Root desde long mode: abren y cierran toda la sesión de VMX. Lanzar y reanudar una MV (VMLAUNCH/VMRESUME) es el VM Entry, volver al VMM es el VM Exit, y del SMM se sale con RSM.", src: "T3 diap. 15" },
  { t: "x86", q: "En el tema 2, la instrucción vmrun pasa a modo guest cargando en el procesador el estado de la MV guardado en el VMCB. Con la terminología de Intel VT-x del tema 3, ¿qué instrucciones hacen ese papel?", o: ["VMXON y VMXOFF", "VMPTRLD y VMPTRST", "VMLAUNCH y VMRESUME (VM Entry)", "VMREAD y VMWRITE"], a: 2, why: "El VM Entry ejecuta la MV con VMLAUNCH o VMRESUME: carga su contexto y cambia de modo Root a Non-Root, como vmrun con el VMCB (T2, diap. 28). Trampa de nombres: el tema 2 dice VMCB y vmrun (los nombres de AMD, aunque eso las diapositivas no lo dicen) y el tema 3 usa los de Intel: VMCS y VMLAUNCH/VMRESUME.", src: "T3 diap. 15; T2 diap. 28" },
  { t: "x86", q: "Con VT-x, para pasar de ejecutar la MV 1 a ejecutar la MV 2 hacen falta un VM Exit (de la MV 1 al VMM) y después un VM Entry (del VMM a la MV 2).", o: ["Verdadero", "Falso"], a: 0, why: "En el dibujo del cambio de contexto las MVs nunca saltan de una a otra: cada VM Exit lleva al VMM (Non-Root → Root), que es quien planifica las MVs, y el VMM hace el VM Entry de la siguiente (Root → Non-Root).", src: "T3 diap. 15" },
  { t: "x86", q: "En Intel VT, ¿cómo se llama la estructura de memoria que reúne la guest-state area, la host-state area, los campos de control de VM-execution, exit y entry y los VM-exit information fields? (escribe las siglas)", s: ["vmcs", "virtual machine control structure", "vmcs (virtual machine control structure)", "virtual machine control structure (vmcs)"], why: "VMCS = Virtual Machine Control Structure, la forma eficiente de Intel VT de hacer el cambio de contexto entre MVs. Trampa: el VMCB (Virtual Machine Control Block) del tema 2 es la estructura análoga; es el nombre que usa AMD, aunque eso las diapositivas no lo dicen.", src: "T3 diap. 16" },
  { t: "x86", q: "Se produce un VM Exit. ¿Qué hace la CPU con el VMCS?", o: ["Guarda el contexto del guest en la guest-state area y carga el del hipervisor desde la host-state area", "Guarda el contexto del hipervisor en la host-state area y carga el del guest desde la guest-state area", "Nada: el hipervisor tiene que copiar el contexto del guest con VMWRITE", "Guarda el contexto del guest en la host-state area para que lo lea el hipervisor"], a: 0, why: "En un VM Exit la CPU guarda el contexto del guest en la guest-state area y lee el del hipervisor de la host-state area; en un VM Entry, al revés. Lo hace automáticamente: VMREAD, VMWRITE y VMCLEAR sirven para configurar el VMCS, no para cambiar de contexto.", src: "T3 diap. 16" },
  { t: "x86", q: "Una MV se inicia por primera vez con Intel VT. ¿Qué secuencia de ejemplo da el tema?", o: ["VMCLEAR → VMWRITE → VMRESUME → VM EXIT → VMREAD → VMLAUNCH", "VMCLEAR → VMWRITE → VMLAUNCH → VM EXIT → VMREAD → VMRESUME", "VMWRITE → VMCLEAR → VMLAUNCH → VM EXIT → VMWRITE → VMLAUNCH", "VMXON → VMLAUNCH → VMCLEAR → VM EXIT → VMREAD → VMXOFF"], a: 1, why: "Primero se prepara el VMCS (VMCLEAR y VMWRITE), VMLAUNCH hace la primera entrada y, tras el VM exit, el hipervisor consulta el VMCS (VMREAD) y vuelve a entrar con VMRESUME. Trampa: VMLAUNCH es para la primera entrada; VMRESUME, para volver después de un exit.", src: "T3 diap. 16" },
  { t: "x86", q: "Un guest se está ejecutando en modo Non-Root. ¿Cuáles de estas causas provocan SIEMPRE un VM exit, sin depender de ninguna bitmask?", o: ["El guest ejecuta CPUID", "El guest ejecuta SIDT", "Se produce un fallo de página en el guest", "El guest ejecuta VMLAUNCH"], a: [0, 3], why: "Son exits incondicionales CPUID, INVD y las instrucciones VMX (VMCLEAR, VMLAUNCH…). SIDT es condicional, como HLT, IN, OUT, LIDT o MOV to/from CR3 (depende de la bitmask de los VM-execution control fields), y el fallo de página también lo es (bit 14).", src: "T3 diap. 17" },
  { t: "x86", q: "Selecciona las parejas Intel/AMD bien emparejadas con el recurso que virtualizan:", o: ["RAM: EPT (Intel) y AMD-Vi (AMD)", "CPU: VT-x (Intel) y AMD-V (AMD)", "E/S: VT-d (Intel) y AMD-Vi, también llamado IOMMU (AMD)", "RAM: VT-d (Intel) y NPT (AMD)"], a: [1, 2], why: "CPU: VT-x / AMD-V; RAM: EPT (Extended Page Tables) / NPT (Nested Paging); E/S: VT-d / AMD-Vi (IOMMU). Trampas: AMD-V (CPU) y AMD-Vi (E/S) solo se distinguen por una «i», y VT-d no es de memoria sino de E/S.", src: "T3 diap. 18" },
  { t: "x86", q: "Quieres asignar directamente una tarjeta de red física a una MV, de modo que el SO guest use el driver real del dispositivo y el VMM no tenga que emularlo. ¿Qué soporte HW de Intel lo permite?", o: ["VT-x", "EPT (Extended Page Tables)", "VT-d (Virtualization Technology for Directed I/O)", "CR4.UMIP"], a: 2, why: "VT-d virtualiza la E/S (en AMD, AMD-Vi o IOMMU) y permite la asignación directa de dispositivos a una MV, con un hardware de DMA-remapping entre el VMM y los dispositivos. Trampa: VT-x es para la CPU y EPT para la RAM.", src: "T3 diaps. 18–19" },
  { t: "x86", q: "En un PC x86 con Linux quieres arrancar un guest compilado para ARM. ¿Qué afirmación es correcta?", o: ["QEMU puede ejecutarlo por emulación, pero no acelerarlo con KVM: según el tema, KVM solo le sirve de acelerador si ambas plataformas, la virtual y la real, son x86", "QEMU lo ejecuta con virtualización nativa hosted y lo acelera con KVM: basta con cargar kvm.ko y kvm-intel.ko", "QEMU no puede: solo admite guests x86/x86-64", "Hace falta VT-d para traducir las instrucciones ARM a x86"], a: 0, why: "QEMU hace virtualización nativa hosted (x86/x86-64) o bien emulación, y arm está entre sus targets; KVM solo le sirve de acelerador si la plataforma virtual y la real son x86. Es el caso de CPU virtual distinta de la real, que se resuelve con emulación (T2, diap. 5).", src: "T3 diap. 24; T2 diap. 5" },
  { t: "x86", q: "¿Cuál de estos productos es, según el tema, un hipervisor bare metal?", o: ["VirtualBox", "VMware Workstation", "VMware Fusion", "Oracle VM Server"], a: 3, why: "Oracle VM Server es bare metal y se instala en servidores x86 y SPARC; VirtualBox (originalmente de Sun) es un hosted hypervisor. VMware Workstation, Player y Fusion son su software de escritorio (tipo 2); el tipo 1 de VMware es vSphere (ESXi).", src: "T3 diaps. 22 y 26" },
  { t: "x86", q: "Xen nació como un proyecto de la universidad de Cambridge a finales de los 90 y, aunque en 2004 se fundó XenSource, el proyecto open source siguió abierto.", o: ["Verdadero", "Falso"], a: 0, why: "Cronología de Xen: Cambridge (finales de los 90), código abierto (2002), XenSource (2004, sin cerrar el proyecto) y compra de XenSource por Citrix (2007). Trampa: Citrix no fundó XenSource, la adquirió.", src: "T3 diap. 27" },
  { t: "x86", q: "En Xen, los drivers del hardware están en el Dom0. En el esquema de Hyper-V, ¿qué parte desempeña ese papel?", o: ["La partición hija (Child Partition), con el Virtualization Service Consumer (VSC)", "La partición padre (Parent Partition), con los Device Drivers y el Virtualization Service Provider (VSP)", "El propio hipervisor, en el «Ring -1»", "El VMBus"], a: 1, why: "Xen e Hyper-V son bare metal con máquina privilegiada: en Xen, el Dom0 (Kernel0 con los drivers); en Hyper-V, la partición padre (Windows Kernel, Device Drivers y VSP). El tema 1 lo dice con estas palabras: la MV privilegiada que ejecuta los drivers se llama también «Dom0, Parent Part.» (T1, diap. 24). Las particiones hijas usan el VSC y el VMBus, y el hipervisor queda en el «Ring -1».", src: "T3 diaps. 27–28; T1 diap. 24" },

  // ---------- 09 qemu: máquinas y discos
  { t: "qemu", q: "En qemu-img create -F qcow2 -f qcow2 -b base.qcow2 clon.qcow2, -F indica…", o: ["El formato del clon", "El formato del disco base", "El tamaño", "Que se fuerce"], a: 1, why: "-f es el formato del disco nuevo y -b el base." },
  { t: "qemu", q: "¿Qué comando muestra de qué disco base depende un clon?", o: ["qemu-img check", "qemu-img info --backing-chain clon.qcow2", "ls -l", "qemu-img commit"], a: 1, why: "Debe aparecer «backing file: …»." },
  { t: "qemu", q: "Para hacer un full clone independiente de un linked clone se usa…", o: ["cp", "qemu-img convert -O qcow2 origen.qcow2 destino.qcow2", "ln -s", "qemu-img rebase"], a: 1, why: "cp copiaría solo el delta, que sigue dependiendo de la base." },
  { t: "qemu", q: "¿Qué hace qemu-img commit clon.qcow2?", o: ["Crea un clon", "Vuelca (consolida) los cambios del clon en su disco base", "Borra el clon", "Crea un snapshot"], a: 1, why: "Cuidado si la base la comparten otros clones." },
  { t: "qemu", q: "¿Qué opción de qemu-system-x86_64 activa la aceleración hardware?", o: ["-accel tcg", "--enable-kvm", "-smp", "-nographic"], a: 1, why: "Sin ella QEMU emula (TCG) y va muy lento." },
  { t: "qemu", q: "¿Cómo se apaga a lo bruto una MV lanzada con -nographic en primer plano?", o: ["Ctrl+C", "Ctrl+A y luego x", "Ctrl+Z", "exit"], a: 1, why: "Ctrl+C va a la MV. Ctrl+A c abre el monitor de QEMU." },
  { t: "qemu", q: "¿Por qué sale la pantalla negra al arrancar con -nographic?", o: ["La MV está rota", "El kernel manda sus mensajes a una pantalla gráfica que no existe; hay que añadir console=ttyS0", "Falta RAM", "Falta --enable-kvm"], a: 1, why: "Para siempre: en /boot/extlinux.conf de la base, línea APPEND." },
  { t: "qemu", q: "¿Por qué el cambio de console=ttyS0 se hace en la MV base y no en el clon?", o: ["Porque el clon es de solo lectura", "Para que todos los clones lo hereden: leen de la base lo que no han modificado", "Porque la base es más rápida", "No importa"], a: 1, why: "Es el copy-on-write en acción." },
  { t: "qemu", q: "La opción -serial mon:telnet::5000,server=on,wait=off…", o: ["Abre SSH", "Publica la consola de la MV por telnet en el puerto 5000 del servidor y arranca sin esperar conexión", "Configura la red", "Abre el firewall"], a: 1, why: "Cada MV necesita un puerto distinto y hay que abrirlo en el firewall." },
  { t: "qemu", q: "¿Qué pasa si lanzas QEMU con -nographic y & pero sin < /dev/null?", o: ["Nada", "Bash la detiene (estado T) porque QEMU quiere leer del teclado", "Se ejecuta más rápido", "Se apaga el servidor"], a: 1, why: "< /dev/null le da una entrada vacía." },
  { t: "qemu", q: "¿Para qué sirve -qmp unix:…sock en la práctica?", o: ["Para la red", "Para que el profesor controle y consulte la MV por QMP al corregir", "Para el disco", "Para telnet"], a: 1, why: "QEMU Machine Protocol: orquestación local desde scripts." },
  { t: "qemu", q: "Un shutdown (apagado suave) desde el hipervisor se hace…", o: ["Matando el proceso", "Enviando un evento ACPI al guest", "Con Ctrl+A x", "Borrando el disco"], a: 1, why: "Power off es duro; shutdown deja que el guest se apague ordenadamente." },
  { t: "qemu", q: "¿Qué hace la opción -snapshot de qemu-system?", o: ["Crea un snapshot permanente", "Los cambios de esa ejecución se descartan al apagar", "Hace un full clone", "Comprime el disco"], a: 1, why: "Snapshot temporal." },

  // ---------- 10 qemu: redes
  { t: "qemured", q: "En QEMU, el frontend de red es…", o: ["El mecanismo que conecta con el exterior", "El dispositivo de red virtual que ve el guest (-device)", "El bridge", "El firewall"], a: 1, why: "El backend (-netdev) conecta con el exterior; se emparejan por id." },
  { t: "qemured", q: "¿Qué modelo de NIC da mejor rendimiento pero necesita drivers paravirtualizados?", o: ["e1000", "rtl8139", "virtio-net", "pcnet"], a: 2, why: "e1000 y rtl8139 usan drivers estándar." },
  { t: "qemured", q: "La red user (SLiRP)…", o: ["Necesita root", "No necesita root, es limitada y no permite ICMP (ping)", "Da la mejor velocidad", "Conecta MVs entre sí"], a: 1, why: "Es el backend por defecto, para acceso básico a Internet." },
  { t: "qemured", q: "Con la red user, desde la MV el host está en…", o: ["10.0.2.15", "10.0.2.2 (la puerta de enlace)", "192.168.1.1", "No se puede llegar"], a: 1, why: "La MV suele tener 10.0.2.15 y el DNS es 10.0.2.3." },
  { t: "qemured", q: "hostfwd=tcp::8080-:80 significa…", o: ["El 80 del host va al 8080 del guest", "Lo que llega al 8080 del host se redirige al 80 del guest", "Abre el firewall", "Bloquea el 80"], a: 1, why: "Formato: host (izquierda) - guest (derecha)." },
  { t: "qemured", q: "¿Por qué se ejecutan dos firewall-cmd, uno con --permanent?", o: ["Por error", "Uno aplica el cambio ya y el otro lo guarda para después de reiniciar", "Uno es para IPv6", "Uno es para UDP"], a: 1, why: "Sin --permanent el cambio se pierde al reiniciar el firewall." },
  { t: "qemured", q: "¿Qué fichero hay que editar para que QEMU pueda usar el bridge br1?", o: ["/etc/hosts", "/etc/qemu/bridge.conf con «allow br1»", "/etc/network/interfaces", "/boot/extlinux.conf"], a: 1, why: "Es la ACL de bridges que QEMU puede usar sin privilegios." },
  { t: "qemured", q: "¿Por qué el bridge de la P2 es «privado»?", o: ["Porque tiene contraseña", "Porque no está conectado a ninguna NIC real: no tiene salida al exterior", "Porque usa NAT", "Porque es IPv6"], a: 1, why: "Solo comunica las MVs entre sí y con el host." },
  { t: "qemured", q: "Al conectar varias MVs al mismo bridge hay que asegurarse de que…", o: ["Tengan la misma MAC", "Cada interfaz tenga una MAC distinta (y cada MV su disco y su puerto)", "Usen la red user", "Tengan la misma IP"], a: 1, why: "La MAC debe ser única en la LAN." },
  { t: "qemured", q: "¿Con qué herramienta se crea el bridge en la práctica?", o: ["brctl", "nmcli (Network Manager)", "ifconfig", "qemu-img"], a: 1, why: "nmcli connection add type bridge con-name bridge1 ifname br1 …" },
  { t: "qemured", q: "Con la red user, ¿pueden dos MVs del mismo host comunicarse directamente?", o: ["Sí, siempre", "No: cada MV tiene su red user aislada; para una LAN entre ellas se usa un bridge", "Solo con ping", "Solo por IPv6"], a: 1, why: "Por eso la P2 monta un bridge privado." },
  { t: "qemured", q: "¿Qué opción desactiva la red por completo?", o: ["-nic none", "-netdev off", "-net 0", "-nographic"], a: 0, why: "O -nodefaults. Sin opciones de red, QEMU crea una NIC user por defecto." },
];
